window.__X_NEWS__ = {"updated_at": "2026-10-22 02:06 Asia/Shanghai", "updated_at_iso": "2026-10-21T18:06:31.000Z", "count": 92, "domains": ["科技", "商业", "中国", "国际", "体育", "娱乐", "科学"], "items": [{"id": "2112386205996245100", "domain": "科技", "title_en": "Sam Altman Outlines Three Paths for Safe Advanced AI Development", "title_zh": "奥特曼勾勒先进 AI 安全发展的三条路径", "hook_en": "Sam Altman gathered OpenAI staff to map out three stark options for handling super-smart AI, right as the Trump administration steps in with its own oversight plans.", "hook_zh": "萨姆·奥特曼召集 OpenAI 员工讨论应对超强 AI 的三条截然不同选项，恰逢特朗普政府推出自有监管计划。", "summary_en": "Last week, Altman described an international body like the IAEA to enforce safety at frontier labs, which he favors; a CERN-style merger of AI labs to share models, known as the 'Demis plan'; and a rejected idea of one lab dominating by disabling rivals' hardware, dubbed the 'Eliezer plan.' He stressed OpenAI must pick a path within a year to avoid falling behind competitors amid safety pressures. The talk coincides with the Trump administration's new Super Intelligence Force, using existing laws to tackle national security and civil liberties risks from advanced AI. Reports from The Information have sparked online talks on AI's future, blending safety concerns with hopes for shared prosperity.", "summary_zh": "上周奥特曼描述了三条路径：他倾向的类似国际原子能机构的国际机构以约束前沿实验室安全；被称为「Demis 方案」的类 CERN 实验室合并以共享模型；以及被否决的「Eliezer 方案」——由单一实验室通过瘫痪对手硬件来主导。他强调 OpenAI 须在一年内选定路径，以免在安全压力下落后于竞争对手。谈话正值特朗普政府成立「超级智能部队」，拟用现有法律应对先进 AI 带来的国家安全与公民自由风险。《The Information》相关报道引发网上对 AI 未来的讨论，交织安全关切与共享繁荣期待。", "body_en": "Sam Altman Outlines Three Paths for Safe Advanced AI Development.\n\nSam Altman gathered OpenAI staff to map out three stark options for handling super-smart AI, right as the Trump administration steps in with its own oversight plans.\n\nLast week, Altman described an international body like the IAEA to enforce safety at frontier labs, which he favors; a CERN-style merger of AI labs to share models, known as the 'Demis plan'; and a rejected idea of one lab dominating by disabling rivals' hardware, dubbed the 'Eliezer plan.' He stressed OpenAI must pick a path within a year to avoid falling behind competitors amid safety pressures.\n\nThe talk coincides with the Trump administration's new Super Intelligence Force, using existing laws to tackle national security and civil liberties risks from advanced AI. Reports from The Information have sparked online talks on AI's future, blending safety concerns with hopes for shared prosperity.", "body_zh": "奥特曼勾勒先进 AI 安全发展的三条路径。\n\n萨姆·奥特曼召集 OpenAI 员工讨论应对超强 AI 的三条截然不同选项，恰逢特朗普政府推出自有监管计划。\n\n上周奥特曼描述了三条路径：他倾向的类似国际原子能机构的国际机构以约束前沿实验室安全；被称为「Demis 方案」的类 CERN 实验室合并以共享模型；以及被否决的「Eliezer 方案」——由单一实验室通过瘫痪对手硬件来主导。他强调 OpenAI 须在一年内选定路径，以免在安全压力下落后于竞争对手。\n\n谈话正值特朗普政府成立「超级智能部队」，拟用现有法律应对先进 AI 带来的国家安全与公民自由风险。《The Information》相关报道引发网上对 AI 未来的讨论，交织安全关切与共享繁荣期待。", "url": "https://x.com/i/trending/2112386205996245100", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T14:10:55.000Z"}, {"id": "2112883740699480270", "domain": "科技", "title_en": "OpenAI Partners with Google Cloud to Offer Frontier Models in Model Garden", "title_zh": "OpenAI 与谷歌云合作，前沿模型将入驻 Model Garden", "hook_en": "OpenAI's powerful models like GPT-6 Astra are landing on Google Cloud, giving businesses a unified spot to access top AI tools without juggling platforms.", "hook_zh": "GPT-6 Astra 等 OpenAI 强模型即将登陆谷歌云，企业可在同一平台调用顶尖 AI 工具，不必再多端切换。", "summary_en": "Google Cloud announced today that enterprise customers can soon use OpenAI's frontier models, including GPT-6 Astra and Codex agentic workflows, directly in its Model Garden alongside Gemini, Claude, and over 200 others. Businesses can purchase through the Google Cloud Marketplace, apply existing spending commitments, and integrate into tools like Google Antigravity and Gemini Agent for flexible task handling. This expands OpenAI's reach beyond Microsoft Azure—now non-exclusive—to more cloud options, supporting regulated industries with strong data governance and high-performance setup. Analysts see it as a win for multi-model strategies and easier AI adoption.", "summary_zh": "谷歌云今日宣布，企业客户很快可在 Model Garden 中直接使用 OpenAI 前沿模型，包括 GPT-6 Astra 与 Codex 智能体工作流，并与 Gemini、Claude 及逾 200 款其他模型并列。企业可通过谷歌云 Marketplace 采购、沿用既有消费承诺，并接入 Google Antigravity、Gemini Agent 等工具灵活处理任务。此举使 OpenAI 在微软 Azure 之外拓展云端触达——Azure 现已非独家——也为受监管行业提供更强数据治理与高性能部署选项。分析人士认为，这有利于多模型策略，并降低 AI 落地门槛。", "body_en": "OpenAI Partners with Google Cloud to Offer Frontier Models in Model Garden.\n\nOpenAI's powerful models like GPT-6 Astra are landing on Google Cloud, giving businesses a unified spot to access top AI tools without juggling platforms.\n\nGoogle Cloud announced today that enterprise customers can soon use OpenAI's frontier models, including GPT-6 Astra and Codex agentic workflows, directly in its Model Garden alongside Gemini, Claude, and over 200 others. Businesses can purchase through the Google Cloud Marketplace, apply existing spending commitments, and integrate into tools like Google Antigravity and Gemini Agent for flexible task handling.\n\nThis expands OpenAI's reach beyond Microsoft Azure—now non-exclusive—to more cloud options, supporting regulated industries with strong data governance and high-performance setup. Analysts see it as a win for multi-model strategies and easier AI adoption.", "body_zh": "OpenAI 与谷歌云合作，前沿模型将入驻 Model Garden。\n\nGPT-6 Astra 等 OpenAI 强模型即将登陆谷歌云，企业可在同一平台调用顶尖 AI 工具，不必再多端切换。\n\n谷歌云今日宣布，企业客户很快可在 Model Garden 中直接使用 OpenAI 前沿模型，包括 GPT-6 Astra 与 Codex 智能体工作流，并与 Gemini、Claude 及逾 200 款其他模型并列。企业可通过谷歌云 Marketplace 采购、沿用既有消费承诺，并接入 Google Antigravity、Gemini Agent 等工具灵活处理任务。\n\n此举使 OpenAI 在微软 Azure 之外拓展云端触达——Azure 现已非独家——也为受监管行业提供更强数据治理与高性能部署选项。分析人士认为，这有利于多模型策略，并降低 AI 落地门槛。", "url": "https://x.com/i/trending/2112883740699480270", "category": "News", "topics": ["Technology", "AI", "Business & Finance"], "updated_at": "2026-10-21T17:08:05.000Z"}, {"id": "2112281282239664552", "domain": "科技", "title_en": "NVIDIA Runs Record 104-Qubit Quantum Simulation on JUPITER Supercomputer", "title_zh": "英伟达在 JUPITER 超算上完成创纪录 104 量子比特模拟", "hook_en": "NVIDIA researchers pushed classical computing to mimic a fault-tolerant quantum system with 104 qubits—the largest simulation yet—using thousands of GPUs in Germany.", "hook_zh": "英伟达研究人员用德国数千块 GPU，推动经典计算模拟容错量子系统，达 104 量子比特——迄今最大规模。", "summary_en": "On Europe’s JUPITER supercomputer at the Jülich Supercomputing Centre, NVIDIA simulated a 104-qubit fault-tolerant quantum processor with 8,192 GH200 GPUs, including realistic hardware noise that past efforts overlooked. The simulation validated magic state cultivation, a method that slashes physical qubit needs by about 90 percent, guiding error mitigation for drug discovery, financial modeling, and materials science. CEO Jensen Huang highlighted how such digital twins of factories will let workers design AI cars and robotic plants virtually first. This bridges GPU simulations with real quantum hardware, de-risking development and speeding practical machines.", "summary_zh": "在于利希超算中心的欧洲 JUPITER 超算上，英伟达用 8192 块 GH200 GPU 模拟了 104 量子比特容错量子处理器，并纳入以往常被忽略的真实硬件噪声。模拟验证了「魔法态培育」方法，可将物理量子比特需求削减约 90%，为药物发现、金融建模与材料科学的误差缓解提供指引。CEO 黄仁勋强调，此类工厂数字孪生可让工人先虚拟设计 AI 汽车与机器人产线。此举衔接 GPU 模拟与真实量子硬件，降低开发风险并加速实用化。", "body_en": "NVIDIA Runs Record 104-Qubit Quantum Simulation on JUPITER Supercomputer.\n\nNVIDIA researchers pushed classical computing to mimic a fault-tolerant quantum system with 104 qubits—the largest simulation yet—using thousands of GPUs in Germany.\n\nOn Europe’s JUPITER supercomputer at the Jülich Supercomputing Centre, NVIDIA simulated a 104-qubit fault-tolerant quantum processor with 8,192 GH200 GPUs, including realistic hardware noise that past efforts overlooked. The simulation validated magic state cultivation, a method that slashes physical qubit needs by about 90 percent, guiding error mitigation for drug discovery, financial modeling, and materials science.\n\nCEO Jensen Huang highlighted how such digital twins of factories will let workers design AI cars and robotic plants virtually first. This bridges GPU simulations with real quantum hardware, de-risking development and speeding practical machines.", "body_zh": "英伟达在 JUPITER 超算上完成创纪录 104 量子比特模拟。\n\n英伟达研究人员用德国数千块 GPU，推动经典计算模拟容错量子系统，达 104 量子比特——迄今最大规模。\n\n在于利希超算中心的欧洲 JUPITER 超算上，英伟达用 8192 块 GH200 GPU 模拟了 104 量子比特容错量子处理器，并纳入以往常被忽略的真实硬件噪声。模拟验证了「魔法态培育」方法，可将物理量子比特需求削减约 90%，为药物发现、金融建模与材料科学的误差缓解提供指引。\n\nCEO 黄仁勋强调，此类工厂数字孪生可让工人先虚拟设计 AI 汽车与机器人产线。此举衔接 GPU 模拟与真实量子硬件，降低开发风险并加速实用化。", "url": "https://x.com/i/trending/2112281282239664552", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-19T20:43:59.000Z"}, {"id": "2112176711844458620", "domain": "科技", "title_en": "Anthropic Commits Shares to Public Benefit Fund", "title_zh": "Anthropic 设立公益基金，承诺拨出股份服务公共目的", "hook_en": "Anthropic's pledge to dedicate 5% of its shares to public good initiatives feels like a direct response to AI's promise of abundance for everyone.", "hook_zh": "Anthropic 宣布把约 5% 股份用于公益，回应“AI 带来普遍丰裕”的期待。", "summary_en": "The AI company behind Claude models announced a Public Benefit Fund starting with 5% of shares, pending stockholder approval, which could grow by up to 2% for every 50% valuation increase above a baseline. Combined with prior pledges, this totals about 20% of shares for purposes like nonprofit donations, aid to affected groups, or addressing AI's job impacts—building on a $200 million labor study commitment, with no funds for lobbying. Elon Musk replied that this is what he will do, later specifying 'universal high income,' fueling talk of AI-driven prosperity shared widely, though some see it as flexible public benefit rather than formal income programs.", "summary_zh": "这家推出 Claude 的公司宣布设立“公益基金”，起步拨出 5% 股份（须经股东批准），估值每高出基准 50% 还可再增拨最多 2%。加上此前承诺，约合 20% 股份可用于非营利捐赠、援助受影响群体或应对就业冲击等，并延续其 2 亿美元劳工研究投入，且不用于游说。埃隆·马斯克回应称自己也会这么做，并提到“普遍高收入”，引发关于如何分享 AI 红利的讨论。", "body_en": "Anthropic Commits Shares to Public Benefit Fund.\n\nAnthropic's pledge to dedicate 5% of its shares to public good initiatives feels like a direct response to AI's promise of abundance for everyone.\n\nThe AI company behind Claude models announced a Public Benefit Fund starting with 5% of shares, pending stockholder approval, which could grow by up to 2% for every 50% valuation increase above a baseline.\n\nCombined with prior pledges, this totals about 20% of shares for purposes like nonprofit donations, aid to affected groups, or addressing AI's job impacts—building on a $200 million labor study commitment, with no funds for lobbying. Elon Musk replied that this is what he will do, later specifying 'universal high income,' fueling talk of AI-driven prosperity shared widely, though some see it as flexible public benefit rather than formal income programs.", "body_zh": "Anthropic 设立公益基金，承诺拨出股份服务公共目的。\n\nAnthropic 宣布把约 5% 股份用于公益，回应“AI 带来普遍丰裕”的期待。\n\n这家推出 Claude 的公司宣布设立“公益基金”，起步拨出 5% 股份（须经股东批准），估值每高出基准 50% 还可再增拨最多 2%。\n\n加上此前承诺，约合 20% 股份可用于非营利捐赠、援助受影响群体或应对就业冲击等，并延续其 2 亿美元劳工研究投入，且不用于游说。埃隆·马斯克回应称自己也会这么做，并提到“普遍高收入”，引发关于如何分享 AI 红利的讨论。", "url": "https://x.com/i/trending/2112176711844458620", "category": "News", "topics": ["Business & Finance", "Technology"], "updated_at": "2026-10-20T21:34:55.000Z"}, {"id": "2112630070984802593", "domain": "科技", "title_en": "OpenAI Launches Locked Chats for Private ChatGPT Conversations", "title_zh": "OpenAI 推出「锁定对话」，保护私密 ChatGPT 聊天", "hook_en": "Ever had a ChatGPT chat too personal to leave in plain view? OpenAI's new Locked Chats let you tuck it away, protected by a PIN or your fingerprint.", "hook_zh": "把屏幕递给别人前，想先藏起敏感对话？锁定对话用 PIN 或生物识别就能搞定。", "summary_en": "The feature hides selected chats from history, pins, and searches, making them accessible only through a four-digit PIN on all platforms or biometrics on supported phones. It rolled out starting October 20 across Free, Plus, Pro, Business, Enterprise, and Edu plans on web, desktop, and mobile. Locked chats keep new messages in a separate memory section without affecting regular ones, though they lack end-to-end encryption and can't be recovered if the PIN is reset. This adds device-level privacy amid discussions on ChatGPT's memory system, where a study found most entries include psychological insights or personal data created automatically.", "summary_zh": "用户可将聊天移入受保护区域，从历史、置顶与搜索中隐藏，需四位 PIN（全平台）或手机生物识别才能打开。功能自 10 月 20 日起覆盖免费到企业、教育等各档套餐的网页、桌面与移动端。锁定对话的新消息进入独立记忆分区，不影响普通聊天；但不提供端到端加密，重置 PIN 后也无法恢复。此举回应了围绕 ChatGPT 记忆与隐私的讨论。", "body_en": "OpenAI Launches Locked Chats for Private ChatGPT Conversations.\n\nEver had a ChatGPT chat too personal to leave in plain view? OpenAI's new Locked Chats let you tuck it away, protected by a PIN or your fingerprint.\n\nThe feature hides selected chats from history, pins, and searches, making them accessible only through a four-digit PIN on all platforms or biometrics on supported phones. It rolled out starting October 20 across Free, Plus, Pro, Business, Enterprise, and Edu plans on web, desktop, and mobile.\n\nLocked chats keep new messages in a separate memory section without affecting regular ones, though they lack end-to-end encryption and can't be recovered if the PIN is reset. This adds device-level privacy amid discussions on ChatGPT's memory system, where a study found most entries include psychological insights or personal data created automatically.", "body_zh": "OpenAI 推出「锁定对话」，保护私密 ChatGPT 聊天。\n\n把屏幕递给别人前，想先藏起敏感对话？锁定对话用 PIN 或生物识别就能搞定。\n\n用户可将聊天移入受保护区域，从历史、置顶与搜索中隐藏，需四位 PIN（全平台）或手机生物识别才能打开。功能自 10 月 20 日起覆盖免费到企业、教育等各档套餐的网页、桌面与移动端。\n\n锁定对话的新消息进入独立记忆分区，不影响普通聊天；但不提供端到端加密，重置 PIN 后也无法恢复。此举回应了围绕 ChatGPT 记忆与隐私的讨论。", "url": "https://x.com/i/trending/2112630070984802593", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-21T08:41:04.000Z"}, {"id": "2112595601669919101", "domain": "科技", "title_en": "OpenAI Quiets Support for AI Chip Export Limits to China", "title_zh": "OpenAI 淡化对输华 AI 芯片出口限制的支持", "hook_en": "OpenAI once pushed hard for strict U.S. limits on advanced AI chips heading to China. Now, the company has gone quiet, leaving policymakers surprised and critics pointing fingers.", "hook_zh": "OpenAI 曾力推美国严格限制先进 AI 芯片流向中国，如今却噤声，令政策制定者意外，批评者纷纷指责。", "summary_en": "Last year, OpenAI lobbied for curbs on sales of Nvidia's advanced processors to Beijing-backed AI labs to protect U.S. interests. Capitol Hill aides note the firm has stopped advocating, a shift that aids Nvidia—which opposes tighter rules—and aligns with broader political approaches amid a major 2025 infrastructure partnership worth up to $100 billion. Critics like Samuel Hammond call it shortsighted for U.S. AI dominance and security, while OpenAI stresses maintaining a compute lead through effective controls as part of strategy. Rival Anthropic continues backing restriction bills as lawmakers eye defense bill amendments.", "summary_zh": "去年 OpenAI 曾游说限制英伟达先进处理器售予有北京背景的 AI 实验室，以维护美方利益。国会山助手称公司已停止倡议；这一转向有利于反对加严规则的英伟达，也契合更广政治取态，并与 2025 年一项最高可达 1000 亿美元的重大基础设施合作相呼应。Samuel Hammond 等批评者称其短视，有损美国 AI 主导与安全；OpenAI 则强调通过有效管制保持算力领先。对手 Anthropic 仍支持限制法案，议员正关注国防授权法案修正案。", "body_en": "OpenAI Quiets Support for AI Chip Export Limits to China.\n\nOpenAI once pushed hard for strict U.S. limits on advanced AI chips heading to China. Now, the company has gone quiet, leaving policymakers surprised and critics pointing fingers.\n\nLast year, OpenAI lobbied for curbs on sales of Nvidia's advanced processors to Beijing-backed AI labs to protect U.S. interests. Capitol Hill aides note the firm has stopped advocating, a shift that aids Nvidia—which opposes tighter rules—and aligns with broader political approaches amid a major 2025 infrastructure partnership worth up to $100 billion.\n\nCritics like Samuel Hammond call it shortsighted for U.S. AI dominance and security, while OpenAI stresses maintaining a compute lead through effective controls as part of strategy. Rival Anthropic continues backing restriction bills as lawmakers eye defense bill amendments.", "body_zh": "OpenAI 淡化对输华 AI 芯片出口限制的支持。\n\nOpenAI 曾力推美国严格限制先进 AI 芯片流向中国，如今却噤声，令政策制定者意外，批评者纷纷指责。\n\n去年 OpenAI 曾游说限制英伟达先进处理器售予有北京背景的 AI 实验室，以维护美方利益。国会山助手称公司已停止倡议；这一转向有利于反对加严规则的英伟达，也契合更广政治取态，并与 2025 年一项最高可达 1000 亿美元的重大基础设施合作相呼应。\n\nSamuel Hammond 等批评者称其短视，有损美国 AI 主导与安全；OpenAI 则强调通过有效管制保持算力领先。对手 Anthropic 仍支持限制法案，议员正关注国防授权法案修正案。", "url": "https://x.com/i/trending/2112595601669919101", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T17:34:14.000Z"}, {"id": "2112540739628630161", "domain": "科技", "title_en": "Amazon Explores Offloading $8 Billion in Nvidia Chips to Investors", "title_zh": "亚马逊探讨向投资者转移约 80 亿美元英伟达芯片", "hook_en": "Amazon has thousands of cutting-edge Nvidia chips ready for its U.S. data centers, but power shortages mean many sit unused in warehouses.", "hook_zh": "大量先进英伟达芯片已备好进美国数据中心，却因电力不足堆在仓库。", "summary_en": "The company is in talks to shift about $8 billion worth of Grace Blackwell chips into a special-purpose vehicle, which would lease them back to Amazon and raise funds through debt and a small equity stake. This comes as internal documents reveal a massive influx of Nvidia GB300 racks—$5 billion in one month alone—piling up due to insufficient power and infrastructure in data centers across Nevada and Virginia. Observers note the timing raises questions about Amazon's AI hardware glut amid its $220 billion capital spending push, though some see the move as smart financing to keep using the chips without owning them outright.", "summary_zh": "公司正洽谈将约 80 亿美元 Grace Blackwell 芯片装入特殊目的载体，再回租给亚马逊，并以债务与少量股权融资。内部文件显示英伟达 GB300 机架大量涌入——单月即约 50 亿美元——因内华达与弗吉尼亚等地电力与基础设施不足而积压。有人质疑其在约 2200 亿美元资本开支背景下的算力过剩，也有人视之为「用而不必全资持有」的融资安排。", "body_en": "Amazon Explores Offloading $8 Billion in Nvidia Chips to Investors.\n\nAmazon has thousands of cutting-edge Nvidia chips ready for its U.S. data centers, but power shortages mean many sit unused in warehouses.\n\nThe company is in talks to shift about $8 billion worth of Grace Blackwell chips into a special-purpose vehicle, which would lease them back to Amazon and raise funds through debt and a small equity stake.\n\nThis comes as internal documents reveal a massive influx of Nvidia GB300 racks—$5 billion in one month alone—piling up due to insufficient power and infrastructure in data centers across Nevada and Virginia. Observers note the timing raises questions about Amazon's AI hardware glut amid its $220 billion capital spending push, though some see the move as smart financing to keep using the chips without owning them outright.", "body_zh": "亚马逊探讨向投资者转移约 80 亿美元英伟达芯片。\n\n大量先进英伟达芯片已备好进美国数据中心，却因电力不足堆在仓库。\n\n公司正洽谈将约 80 亿美元 Grace Blackwell 芯片装入特殊目的载体，再回租给亚马逊，并以债务与少量股权融资。内部文件显示英伟达 GB300 机架大量涌入——单月即约 50 亿美元——因内华达与弗吉尼亚等地电力与基础设施不足而积压。\n\n有人质疑其在约 2200 亿美元资本开支背景下的算力过剩，也有人视之为「用而不必全资持有」的融资安排。", "url": "https://x.com/i/trending/2112540739628630161", "category": "News", "topics": ["Business & Finance", "Stocks", "Technology", "AI"], "updated_at": "2026-10-20T13:52:24.000Z"}, {"id": "2112741574346162483", "domain": "科技", "title_en": "Nvidia in Talks for Hundreds of Millions Investment in Firmus After Scrapped IPO", "title_zh": "Nvidia 洽谈向 Firmus 注资数亿美元，Firmus 已搁置 IPO", "hook_en": "Firmus had its sights set on a massive IPO, but pulled back amid market jitters. Now Nvidia, already a partner, is stepping up with talks of a huge cash infusion.", "hook_zh": "Firmus 本瞄准大型 IPO，却因市场紧张而撤回；已是合作方的 Nvidia，正讨论大规模注资。", "summary_en": "Australian AI cloud provider Firmus abandoned its planned blockbuster IPO on the Australian Securities Exchange earlier this month due to investor concerns over high valuations and its short track record. Nvidia, which already invests in Firmus and partners on a major GPU deployment in Indonesia's Batam campus, is now discussing an equity investment of several hundred million dollars—possibly at least AU$500 million. This move aligns with Nvidia's strategy to back neocloud operators amid surging AI computing demand, as Firmus pivots to private funding up to US$3 billion. No final deal details are confirmed yet.", "summary_zh": "澳大利亚 AI 云服务商 Firmus 本月初因投资者担忧估值过高与业绩记录偏短，放弃在澳大利亚证券交易所的大型 IPO。已投资 Firmus、并在印尼巴淡岛校园合作大规模 GPU 部署的 Nvidia，正讨论数亿美元股权投资，金额可能至少 5 亿澳元。此举契合 Nvidia 在 AI 算力需求飙升背景下支持 neocloud 运营商的策略；Firmus 则转向最高可达约 30 亿美元的私募融资。最终交易细节尚未确认。", "body_en": "Nvidia in Talks for Hundreds of Millions Investment in Firmus After Scrapped IPO.\n\nFirmus had its sights set on a massive IPO, but pulled back amid market jitters. Now Nvidia, already a partner, is stepping up with talks of a huge cash infusion.\n\nAustralian AI cloud provider Firmus abandoned its planned blockbuster IPO on the Australian Securities Exchange earlier this month due to investor concerns over high valuations and its short track record. Nvidia, which already invests in Firmus and partners on a major GPU deployment in Indonesia's Batam campus, is now discussing an equity investment of several hundred million dollars—possibly at least AU$500 million.\n\nThis move aligns with Nvidia's strategy to back neocloud operators amid surging AI computing demand, as Firmus pivots to private funding up to US$3 billion. No final deal details are confirmed yet.", "body_zh": "Nvidia 洽谈向 Firmus 注资数亿美元，Firmus 已搁置 IPO。\n\nFirmus 本瞄准大型 IPO，却因市场紧张而撤回；已是合作方的 Nvidia，正讨论大规模注资。\n\n澳大利亚 AI 云服务商 Firmus 本月初因投资者担忧估值过高与业绩记录偏短，放弃在澳大利亚证券交易所的大型 IPO。已投资 Firmus、并在印尼巴淡岛校园合作大规模 GPU 部署的 Nvidia，正讨论数亿美元股权投资，金额可能至少 5 亿澳元。\n\n此举契合 Nvidia 在 AI 算力需求飙升背景下支持 neocloud 运营商的策略；Firmus 则转向最高可达约 30 亿美元的私募融资。最终交易细节尚未确认。", "url": "https://x.com/i/trending/2112741574346162483", "category": "News", "topics": ["Technology", "AI", "Business & Finance"], "updated_at": "2026-10-21T04:17:50.000Z"}, {"id": "2112496630352281688", "domain": "科技", "title_en": "Microsoft Pulls Out of UK's Largest Planned AI Data Center Over Power Shortage", "title_zh": "电力短缺，微软退出英国最大拟建 AI 数据中心", "hook_en": "Microsoft backed away from a massive AI supercomputer project in Essex after learning grid power won't arrive until the 2030s. The move spotlights Britain's struggle to fuel its AI dreams with reliable electricity.", "hook_zh": "得知电网供电要到 2030 年代才能到位后，微软退出埃塞克斯巨型 AI 超算项目。", "summary_en": "Nscale planned a £2 billion facility in Loughton, the UK's biggest AI data center, with Microsoft as anchor tenant for a setup using 23,000 Nvidia chips and up to 90 megawatts of capacity. UK Power Networks cited decade-long delays, prompting Microsoft to terminate just for this site while keeping ties with Nscale strong. Nscale presses on with alternative power and other locations, amid talk of grid bottlenecks holding back the UK's third-place global AI ranking. Observers debate fixes like faster permits and targeted grid investments to match policy ambition with infrastructure reality.", "summary_zh": "Nscale 原计划在劳顿投资 20 亿英镑建设英国最大 AI 数据中心，微软为锚定租户，拟部署约 2.3 万块英伟达芯片、容量最高约 90 兆瓦。英国电力网络公司称供电延迟可能长达十年，微软因此仅终止该站点合作，与 Nscale 其他合作仍保持。Nscale 正寻求替代电力与其他选址；舆论认为电网瓶颈拖累英国全球 AI 第三的定位，呼吁加快许可与定向电网投资。", "body_en": "Microsoft Pulls Out of UK's Largest Planned AI Data Center Over Power Shortage.\n\nMicrosoft backed away from a massive AI supercomputer project in Essex after learning grid power won't arrive until the 2030s. The move spotlights Britain's struggle to fuel its AI dreams with reliable electricity.\n\nNscale planned a £2 billion facility in Loughton, the UK's biggest AI data center, with Microsoft as anchor tenant for a setup using 23,000 Nvidia chips and up to 90 megawatts of capacity. UK Power Networks cited decade-long delays, prompting Microsoft to terminate just for this site while keeping ties with Nscale strong.\n\nNscale presses on with alternative power and other locations, amid talk of grid bottlenecks holding back the UK's third-place global AI ranking. Observers debate fixes like faster permits and targeted grid investments to match policy ambition with infrastructure reality.", "body_zh": "电力短缺，微软退出英国最大拟建 AI 数据中心。\n\n得知电网供电要到 2030 年代才能到位后，微软退出埃塞克斯巨型 AI 超算项目。\n\nNscale 原计划在劳顿投资 20 亿英镑建设英国最大 AI 数据中心，微软为锚定租户，拟部署约 2.3 万块英伟达芯片、容量最高约 90 兆瓦。英国电力网络公司称供电延迟可能长达十年，微软因此仅终止该站点合作，与 Nscale 其他合作仍保持。\n\nNscale 正寻求替代电力与其他选址；舆论认为电网瓶颈拖累英国全球 AI 第三的定位，呼吁加快许可与定向电网投资。", "url": "https://x.com/i/trending/2112496630352281688", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T10:54:58.000Z"}, {"id": "2112343868393816356", "domain": "科技", "title_en": "NVIDIA Unveils DSX POD to Slash AI Factory Deployment to 14 Days", "title_zh": "英伟达发布模块化 AI 工厂，部署最短可压至 14 天", "hook_en": "Imagine shipping a fully equipped AI factory in a container, ready to plug in and produce results in just two weeks. NVIDIA made that vision real at GTC Berlin.", "hook_zh": "把原本需要数月的 AI 工厂建设压缩到约 14 天——英伟达新的 DSX POD 系统把预装、全接线的集装箱直接交付，插上即可用。", "summary_en": "NVIDIA launched its DSX POD modular AI factory during CEO Jensen Huang’s keynote, cutting setup times from months to 14 days for Vera Rubin systems. These 28,500 kg containers arrive factory-tested and cabled, built with partners like Dell, HPE, and Lenovo to ease scaling bottlenecks. Nebius CEO Arkady Volozh highlighted booming European demand, with plans for 1 GW of capacity by 2027, while features like closed-loop cooling address power and water constraints. First units roll out worldwide in early 2027, speeding Europe's AI growth.", "summary_zh": "在柏林 GTC 上，英伟达推出 DSX POD 参考设计，把完整的 Vera Rubin AI 工厂装进经工厂测试的集装箱，供合作伙伴异地集成。部署周期可由数月缩短至最短约 14 天，缓解数据中心建设瓶颈，并加快代币生产带来的收入，CEO 黄仁勋对此着重强调。活动还聚焦欧洲云服务商 Nebius，黄仁勋称赞其表现强劲；CEO Arkady Volozh 表示需求旺盛，扩张目标指向约 80 亿美元年经常性收入。DSX POD 单元计划于 2027 年初在全球推出，助力欧洲 AI 生态。", "body_en": "NVIDIA Unveils Modular AI Factories Slashing Deployment to 14 Days.\n\nImagine turning months of AI factory construction into just 14 days of setup. NVIDIA's new DSX POD system makes that possible, delivering pre-built, fully wired containers ready to plug in.\n\nAt GTC Berlin, NVIDIA introduced the DSX POD reference design, which packs complete Vera Rubin AI factories into factory-tested containers for partners to integrate off-site. This cuts deployment from months to as little as 14 days, addressing key bottlenecks in data center builds and speeding up revenue from token production, as CEO Jensen Huang emphasized.\n\nThe event spotlighted European cloud provider Nebius, praised by Huang for its strong performance, with CEO Arkady Volozh noting robust demand and expansion plans targeting $8 billion in annual recurring revenue. DSX POD units will roll out worldwide in early 2027, boosting Europe's AI ecosystem.", "body_zh": "英伟达发布模块化 AI 工厂，部署最短可压至 14 天。\n\n把原本需要数月的 AI 工厂建设压缩到约 14 天——英伟达新的 DSX POD 系统把预装、全接线的集装箱直接交付，插上即可用。\n\n在柏林 GTC 上，英伟达推出 DSX POD 参考设计，把完整的 Vera Rubin AI 工厂装进经工厂测试的集装箱，供合作伙伴异地集成。部署周期可由数月缩短至最短约 14 天，缓解数据中心建设瓶颈，并加快代币生产带来的收入，CEO 黄仁勋对此着重强调。\n\n活动还聚焦欧洲云服务商 Nebius，黄仁勋称赞其表现强劲；CEO Arkady Volozh 表示需求旺盛，扩张目标指向约 80 亿美元年经常性收入。DSX POD 单元计划于 2027 年初在全球推出，助力欧洲 AI 生态。", "url": "https://x.com/i/trending/2112343868393816356", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T17:08:30.000Z"}, {"id": "2112905935199125989", "domain": "科技", "title_en": "DeepSeek Open-Sources AI Inference Framework Amid U.S. Federal Ban", "title_zh": "DeepSeek 在美国联邦禁令声中开源 AI 推理框架", "hook_en": "DeepSeek just released the engine powering its massive AI services to the world, even as U.S. agencies cut it off over security concerns.", "hook_zh": "DeepSeek 刚向全球开源支撑其大规模 AI 服务的推理引擎，与此同时美国联邦机构正以安全为由切断其产品。", "summary_en": "The Chinese AI startup open-sourced DeepInfer, its production framework for models like DeepSeek-V4.1-Flash, optimized for NVIDIA Blackwell GPUs and Huawei Ascend chips to slash compute costs and energy use. It supports features like expert parallelism and speculative decoding, with benchmarks showing speeds up to 609 tokens per second on multi-GPU setups. The release came days after the U.S. Department of Homeland Security ordered federal agencies on October 19 to remove DeepSeek products due to risks of data transfers to China, a move China called discriminatory. Developers are testing it for cheaper AI inference, though training code and data remain private.", "summary_zh": "这家中国 AI 初创公司开源了生产级框架 DeepInfer，用于 DeepSeek-V4.1-Flash 等模型，并针对英伟达 Blackwell GPU 与华为昇腾芯片优化，以降低算力成本与能耗。框架支持专家并行、推测解码等特性，多卡基准测试速度可达每秒 609 tokens。发布数日前，美国国土安全部于 10 月 19 日要求联邦机构移除 DeepSeek 产品，理由是数据可能流向中国；中方称此举具有歧视性。开发者正试用其更便宜的推理能力，但训练代码与数据仍未公开。", "body_en": "DeepSeek Open-Sources AI Inference Framework Amid U.S. Federal Ban.\n\nDeepSeek just released the engine powering its massive AI services to the world, even as U.S. agencies cut it off over security concerns.\n\nThe Chinese AI startup open-sourced DeepInfer, its production framework for models like DeepSeek-V4.1-Flash, optimized for NVIDIA Blackwell GPUs and Huawei Ascend chips to slash compute costs and energy use. It supports features like expert parallelism and speculative decoding, with benchmarks showing speeds up to 609 tokens per second on multi-GPU setups.\n\nThe release came days after the U.S. Department of Homeland Security ordered federal agencies on October 19 to remove DeepSeek products due to risks of data transfers to China, a move China called discriminatory. Developers are testing it for cheaper AI inference, though training code and data remain private.", "body_zh": "DeepSeek 在美国联邦禁令声中开源 AI 推理框架。\n\nDeepSeek 刚向全球开源支撑其大规模 AI 服务的推理引擎，与此同时美国联邦机构正以安全为由切断其产品。\n\n这家中国 AI 初创公司开源了生产级框架 DeepInfer，用于 DeepSeek-V4.1-Flash 等模型，并针对英伟达 Blackwell GPU 与华为昇腾芯片优化，以降低算力成本与能耗。框架支持专家并行、推测解码等特性，多卡基准测试速度可达每秒 609 tokens。\n\n发布数日前，美国国土安全部于 10 月 19 日要求联邦机构移除 DeepSeek 产品，理由是数据可能流向中国；中方称此举具有歧视性。开发者正试用其更便宜的推理能力，但训练代码与数据仍未公开。", "url": "https://x.com/i/trending/2112905935199125989", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T17:48:30.000Z"}, {"id": "2112190704650748351", "domain": "科技", "title_en": "Tenstorrent Raises $1.5 Billion at $6.2 Billion Valuation", "title_zh": "Tenstorrent 融资 15 亿美元，估值升至 62 亿美元", "hook_en": "Tenstorrent's CEO Jim Keller summed up their edge simply: 'We built one architecture and sell it at every size.' The startup just backed that vision with a massive funding round.", "hook_zh": "Tenstorrent CEO Jim Keller 这样概括优势：「我们只做一套架构，按各种规模卖。」公司刚刚用一轮巨额融资坐实了这一愿景。", "summary_en": "The AI chip company, founded in Toronto and now in Santa Clara, California, secured $1.5 billion in Series E funding led by Trace Capital and Innovation X, boosting its valuation from $2.6 billion to $6.2 billion. Investors like ARK Invest, Fidelity, and Tether joined in to fuel volume production of Galaxy servers, which pack dozens of RISC-V AI chips for running open-weight models in chatbots and video tools. Tenstorrent positions its scalable, open hardware as a flexible alternative to Nvidia dominance, with plans to license designs to partners including Samsung and LG. Earlier takeover interest from Intel and Qualcomm was passed up to stay independent.", "summary_zh": "这家源自多伦多、现总部在加州圣克拉拉的 AI 芯片公司完成由 Trace Capital 与 Innovation X 领投的 E 轮 15 亿美元融资，估值从 26 亿美元升至 62 亿美元。ARK Invest、Fidelity、Tether 等跟投，资金将用于 Galaxy 服务器量产——机柜内集成数十颗 RISC-V AI 芯片，面向聊天机器人与视频工具等开源权重模型推理。Tenstorrent 以可扩展的开放硬件对标英伟达主导地位，并计划向三星、LG 等伙伴授权设计。此前曾婉拒英特尔、高通收购意向，坚持独立发展。", "body_en": "Tenstorrent Raises $1.5 Billion at $6.2 Billion Valuation.\n\nTenstorrent's CEO Jim Keller summed up their edge simply: 'We built one architecture and sell it at every size.' The startup just backed that vision with a massive funding round.\n\nThe AI chip company, founded in Toronto and now in Santa Clara, California, secured $1.5 billion in Series E funding led by Trace Capital and Innovation X, boosting its valuation from $2.6 billion to $6.2 billion. Investors like ARK Invest, Fidelity, and Tether joined in to fuel volume production of Galaxy servers, which pack dozens of RISC-V AI chips for running open-weight models in chatbots and video tools.\n\nTenstorrent positions its scalable, open hardware as a flexible alternative to Nvidia dominance, with plans to license designs to partners including Samsung and LG. Earlier takeover interest from Intel and Qualcomm was passed up to stay independent.", "body_zh": "Tenstorrent 融资 15 亿美元，估值升至 62 亿美元。\n\nTenstorrent CEO Jim Keller 这样概括优势：「我们只做一套架构，按各种规模卖。」公司刚刚用一轮巨额融资坐实了这一愿景。\n\n这家源自多伦多、现总部在加州圣克拉拉的 AI 芯片公司完成由 Trace Capital 与 Innovation X 领投的 E 轮 15 亿美元融资，估值从 26 亿美元升至 62 亿美元。ARK Invest、Fidelity、Tether 等跟投，资金将用于 Galaxy 服务器量产——机柜内集成数十颗 RISC-V AI 芯片，面向聊天机器人与视频工具等开源权重模型推理。\n\nTenstorrent 以可扩展的开放硬件对标英伟达主导地位，并计划向三星、LG 等伙伴授权设计。此前曾婉拒英特尔、高通收购意向，坚持独立发展。", "url": "https://x.com/i/trending/2112190704650748351", "category": "News", "topics": ["Technology", "Business & Finance", "AI", "Entrepreneurship"], "updated_at": "2026-10-19T19:40:19.000Z"}, {"id": "2112908301625356787", "domain": "科技", "title_en": "AI Agents Uncover Brain Disease Leads in 32 Minutes", "title_zh": "AI 智能体 32 分钟挖出脑疾病新线索", "hook_en": "Thousands of AI agents pored over millions of mouse brain cells, spotting fresh clues for neurodegenerative diseases in record time.", "hook_zh": "成千上万个 AI 智能体梳理数百万小鼠脑细胞，以创纪录速度发现神经退行性疾病的新线索。", "summary_en": "OpenAI, PerturbAI, and Scripps Research used distributed GPT-Rosalind agents to analyze a massive CRISPR brain atlas. Each agent zeroed in on one gene, checked cell responses across brain regions, scanned literature, and drafted explanations—combining into a detailed atlas in just 32 minutes. Standout discoveries included DCTN1's link to cholesterol issues in Perry syndrome and differing impacts of TSC1 versus TSC2 in neuron communication, ideas human experts favored over single-agent outputs. The approach, building on OpenAI's Orchestra Bio acquisition, promises to speed up drug discovery by handling data volumes that overwhelm traditional methods.", "summary_zh": "OpenAI、PerturbAI 与 Scripps 研究所用分布式 GPT-Rosalind 智能体分析大规模 CRISPR 脑图谱。每个智能体聚焦一个基因，核对跨脑区细胞反应、检索文献并起草解释，32 分钟内汇总成详细图谱。亮点包括 DCTN1 与 Perry 综合征胆固醇问题的关联，以及 TSC1 与 TSC2 对神经元通讯影响的差异；人类专家更认可多智能体结果，而非单智能体输出。该方法依托 OpenAI 收购 Orchestra Bio 的布局，有望处理传统方法难以消化的数据量，加速药物发现。", "body_en": "AI Agents Uncover Brain Disease Leads in 32 Minutes.\n\nThousands of AI agents pored over millions of mouse brain cells, spotting fresh clues for neurodegenerative diseases in record time.\n\nOpenAI, PerturbAI, and Scripps Research used distributed GPT-Rosalind agents to analyze a massive CRISPR brain atlas. Each agent zeroed in on one gene, checked cell responses across brain regions, scanned literature, and drafted explanations—combining into a detailed atlas in just 32 minutes.\n\nStandout discoveries included DCTN1's link to cholesterol issues in Perry syndrome and differing impacts of TSC1 versus TSC2 in neuron communication, ideas human experts favored over single-agent outputs. The approach, building on OpenAI's Orchestra Bio acquisition, promises to speed up drug discovery by handling data volumes that overwhelm traditional methods.", "body_zh": "AI 智能体 32 分钟挖出脑疾病新线索。\n\n成千上万个 AI 智能体梳理数百万小鼠脑细胞，以创纪录速度发现神经退行性疾病的新线索。\n\nOpenAI、PerturbAI 与 Scripps 研究所用分布式 GPT-Rosalind 智能体分析大规模 CRISPR 脑图谱。每个智能体聚焦一个基因，核对跨脑区细胞反应、检索文献并起草解释，32 分钟内汇总成详细图谱。\n\n亮点包括 DCTN1 与 Perry 综合征胆固醇问题的关联，以及 TSC1 与 TSC2 对神经元通讯影响的差异；人类专家更认可多智能体结果，而非单智能体输出。该方法依托 OpenAI 收购 Orchestra Bio 的布局，有望处理传统方法难以消化的数据量，加速药物发现。", "url": "https://x.com/i/trending/2112908301625356787", "category": "News", "topics": ["Technology", "AI", "Science"], "updated_at": "2026-10-21T16:58:22.000Z"}, {"id": "2112585549961994313", "domain": "商业", "title_en": "Hyperliquid Urges CFTC to Approve AI Compute Derivatives", "title_zh": "Hyperliquid 敦促 CFTC 批准 AI 算力衍生品", "hook_en": "AI compute power has surged as a key U.S. economic driver, but wild price swings leave data centers and developers exposed without hedging tools.", "hook_zh": "AI 算力已成美国经济关键推动力，但价格剧烈波动让数据中心与开发者在缺乏对冲工具时暴露风险。", "summary_en": "The Hyperliquid Policy Center submitted a letter to the CFTC on October 20, 2026, pushing for derivatives like perpetual futures on GPU rental prices and AI inference services to manage volatility in this vital market. They pointed to massive investments—0.8% of U.S. GDP in Q1 2026—and real examples like NVIDIA H100 rental rates dropping from $2.50-$3.19 per hour in late 2024 to $1.92-$2.00 a year later, with no way for data centers or AI firms to hedge risks since compute can't be stored. CFTC Chair Michael S. Selig has signaled support, noting America needs robust derivatives to win the AI race, and the agency recently approved its first true perpetual futures contract.", "summary_zh": "Hyperliquid 政策中心于 2026 年 10 月 20 日致函美国商品期货交易委员会（CFTC），推动推出 GPU 租金与 AI 推理服务等永续期货类衍生品，以管理这一关键市场的波动。信中指出 2026 年一季度相关投资约占美国 GDP 的 0.8%，并以英伟达 H100 租金从 2024 年末每小时约 2.50–3.19 美元降至一年后约 1.92–2.00 美元为例：算力无法储存，数据中心与 AI 公司目前几乎无法对冲。CFTC 主席迈克尔·S·塞利格已释放支持信号，称美国需强劲衍生品市场才能赢得 AI 竞赛，该机构近期亦批准了首份真正的永续期货合约。", "body_en": "Hyperliquid Urges CFTC to Approve AI Compute Derivatives.\n\nAI compute power has surged as a key U.S. economic driver, but wild price swings leave data centers and developers exposed without hedging tools.\n\nThe Hyperliquid Policy Center submitted a letter to the CFTC on October 20, 2026, pushing for derivatives like perpetual futures on GPU rental prices and AI inference services to manage volatility in this vital market. They pointed to massive investments—0.8% of U.S.\n\nGDP in Q1 2026—and real examples like NVIDIA H100 rental rates dropping from $2.50-$3.19 per hour in late 2024 to $1.92-$2.00 a year later, with no way for data centers or AI firms to hedge risks since compute can't be stored. CFTC Chair Michael S. Selig has signaled support, noting America needs robust derivatives to win the AI race, and the agency recently approved its first true perpetual futures contract.", "body_zh": "Hyperliquid 敦促 CFTC 批准 AI 算力衍生品。\n\nAI 算力已成美国经济关键推动力，但价格剧烈波动让数据中心与开发者在缺乏对冲工具时暴露风险。\n\nHyperliquid 政策中心于 2026 年 10 月 20 日致函美国商品期货交易委员会（CFTC），推动推出 GPU 租金与 AI 推理服务等永续期货类衍生品，以管理这一关键市场的波动。\n\n信中指出 2026 年一季度相关投资约占美国 GDP 的 0.8%，并以英伟达 H100 租金从 2024 年末每小时约 2.50–3.19 美元降至一年后约 1.92–2.00 美元为例：算力无法储存，数据中心与 AI 公司目前几乎无法对冲。CFTC 主席迈克尔·S·塞利格已释放支持信号，称美国需强劲衍生品市场才能赢得 AI 竞赛，该机构近期亦批准了首份真正的永续期货合约。", "url": "https://x.com/i/trending/2112585549961994313", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T16:51:10.000Z"}, {"id": "2112796521959985524", "domain": "商业", "title_en": "America's Finance Hits Record-Breaking Pace with Mega-Deals", "title_zh": "美国资本市场连创纪录：巨额IPO与债券齐发", "hook_en": "From SpaceX's massive IPO to SoftBank's record junk-bond sale, U.S. markets just powered through an eye-popping wave of financial feats.", "hook_zh": "从 SpaceX 超大规模 IPO 到软银创纪录的垃圾债发行，美国市场正掀起一波令人瞩目的融资潮。", "summary_en": "The Economist highlighted a stunning lineup of achievements, including the biggest IPO ever from SpaceX, huge equity raises by Google and others, OpenAI's private funding, Broadcom's debt deal, Amazon's bond issuance, the first trillion-dollar ETF, and Berkshire Hathaway's cash pile. SoftBank recently sealed the largest corporate junk-bond offering on record, raising over $11 billion for AI investments amid a surge in new markets for compute and predictions. Observers celebrated this resilience as proof of America's unmatched capital markets strength, with comments hailing its bottomless appetite for innovation and ability to sideline setbacks.", "summary_zh": "《经济学人》梳理了一系列里程碑：SpaceX 完成史上最大 IPO，谷歌等巨头大幅增发股权，OpenAI 继续私募融资，博通债务交易、亚马逊发债、首只万亿美元 ETF 以及伯克希尔庞大现金储备也同台亮相。软银近日完成有史以来最大规模公司垃圾债发行，筹资逾 110 亿美元投入 AI。观察者认为，这印证了美国资本市场的深度与对创新的吸纳能力。", "body_en": "America's Finance Hits Record-Breaking Pace with Mega-Deals.\n\nFrom SpaceX's massive IPO to SoftBank's record junk-bond sale, U.S. markets just powered through an eye-popping wave of financial feats.\n\nThe Economist highlighted a stunning lineup of achievements, including the biggest IPO ever from SpaceX, huge equity raises by Google and others, OpenAI's private funding, Broadcom's debt deal, Amazon's bond issuance, the first trillion-dollar ETF, and Berkshire Hathaway's cash pile.\n\nSoftBank recently sealed the largest corporate junk-bond offering on record, raising over $11 billion for AI investments amid a surge in new markets for compute and predictions. Observers celebrated this resilience as proof of America's unmatched capital markets strength, with comments hailing its bottomless appetite for innovation and ability to sideline setbacks.", "body_zh": "美国资本市场连创纪录：巨额IPO与债券齐发。\n\n从 SpaceX 超大规模 IPO 到软银创纪录的垃圾债发行，美国市场正掀起一波令人瞩目的融资潮。\n\n《经济学人》梳理了一系列里程碑：SpaceX 完成史上最大 IPO，谷歌等巨头大幅增发股权，OpenAI 继续私募融资，博通债务交易、亚马逊发债、首只万亿美元 ETF 以及伯克希尔庞大现金储备也同台亮相。软银近日完成有史以来最大规模公司垃圾债发行，筹资逾 110 亿美元投入 AI。\n\n观察者认为，这印证了美国资本市场的深度与对创新的吸纳能力。", "url": "https://x.com/i/trending/2112796521959985524", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T06:46:48.000Z"}, {"id": "2112044241161433358", "domain": "商业", "title_en": "Asia Markets Plunge on AI Spending Worries and Oil Pressures", "title_zh": "亚洲股市因 AI 开支忧虑与油价承压深跌", "hook_en": "Japanese and South Korean stocks have shed hundreds of billions in value over two tense weeks. Investors are pulling back from AI bets amid rising oil prices and global jitters.", "hook_zh": "日韩股市两周蒸发数千亿美元市值。投资者在油价上涨与全球动荡中撤出 AI 押注。", "summary_en": "Japan's Nikkei dropped nearly 10% in recent sessions, wiping out over ¥100 trillion, or about $700 billion, from equities. South Korea's KOSPI fell around 3.5% to 4% on Tuesday, part of a 22% two-week slide that erased ₩1,118 trillion, or $745 billion, with Samsung Electronics and SK Hynix hit hard as key AI chip suppliers. A South Korean AI cloud firm, Elice Inc., saw its shares plunge 30% on its IPO debut despite heavy retail interest, fueled by U.S. tech sell-offs, Middle East oil tensions, and doubts over AI investment returns. Markets now eye earnings reports and oil shifts for signs of recovery.", "summary_zh": "日经近几日累计下跌近 10%，市值蒸发逾 100 万亿日元（约 7000 亿美元）。韩国综指周二再跌约 3.5%–4%，两周累计约 22%、蒸发约 1118 万亿韩元（约 7450 亿美元），三星电子与 SK 海力士等 AI 供应链重镇受创。韩国 AI 云公司 Elice 上市首日暴跌约 30%。市场等待财报与油价信号。", "body_en": "Asia Markets Plunge on AI Spending Worries and Oil Pressures.\n\nJapanese and South Korean stocks have shed hundreds of billions in value over two tense weeks. Investors are pulling back from AI bets amid rising oil prices and global jitters.\n\nJapan's Nikkei dropped nearly 10% in recent sessions, wiping out over ¥100 trillion, or about $700 billion, from equities. South Korea's KOSPI fell around 3.5% to 4% on Tuesday, part of a 22% two-week slide that erased ₩1,118 trillion, or $745 billion, with Samsung Electronics and SK Hynix hit hard as key AI chip suppliers.\n\nA South Korean AI cloud firm, Elice Inc., saw its shares plunge 30% on its IPO debut despite heavy retail interest, fueled by U.S. tech sell-offs, Middle East oil tensions, and doubts over AI investment returns. Markets now eye earnings reports and oil shifts for signs of recovery.", "body_zh": "亚洲股市因 AI 开支忧虑与油价承压深跌。\n\n日韩股市两周蒸发数千亿美元市值。投资者在油价上涨与全球动荡中撤出 AI 押注。\n\n日经近几日累计下跌近 10%，市值蒸发逾 100 万亿日元（约 7000 亿美元）。韩国综指周二再跌约 3.5%–4%，两周累计约 22%、蒸发约 1118 万亿韩元（约 7450 亿美元），三星电子与 SK 海力士等 AI 供应链重镇受创。\n\n韩国 AI 云公司 Elice 上市首日暴跌约 30%。市场等待财报与油价信号。", "url": "https://x.com/i/trending/2112044241161433358", "category": "News", "topics": ["Stocks"], "updated_at": "2026-10-20T12:59:35.000Z"}, {"id": "2112431560116826201", "domain": "商业", "title_en": "Former Finance Secretary Sparks Debate on India's GDP in Dollar Terms", "title_zh": "前财秘以美元口径 GDP 数据引发印度增长辩论", "hook_en": "Subhash Chandra Garg, ex-Finance Secretary, shared IMF data showing India's GDP growth in current US dollars at just 3.87%—well below the world average and China's rate—prompting a lively back-and-forth online.", "hook_zh": "前财政秘书苏巴什·钱德拉·加尔格分享 IMF 数据称，印度按现价美元计 GDP 增速仅 3.87%，低于全球均值与中国，引发网上热议。", "summary_en": "Garg contrasted this with India's real GDP growth of around 7% in local terms, arguing the dollar measure gives a fuller picture often missed in domestic talks. Critics say focusing on dollars mixes in currency fluctuations and overlooks actual output, while supporters like Sanjay Jha tie it to investor outflows exceeding Rs 3 lakh crore from Indian stocks in 2026 and job concerns. The IMF's October 2026 outlook projects India's real growth at 7%, but nominal dollar GDP lags partly due to rupee depreciation, highlighting tensions between real output metrics and global investor views.", "summary_zh": "加尔格将其与印度本币实际 GDP 约 7% 的增速对照，认为美元口径更能呈现国内讨论常忽略的全貌。批评者称盯住美元会混入汇率波动、忽视实际产出；支持者如 Sanjay Jha 则将其与 2026 年印度股市外资流出逾 3 万亿卢比及就业担忧挂钩。IMF 2026 年 10 月展望仍预计印度实际增速 7%，但名义美元 GDP 因卢比贬值等因素滞后，凸显产出指标与全球投资者视角之间的张力。", "body_en": "Former Finance Secretary Sparks Debate on India's GDP in Dollar Terms.\n\nSubhash Chandra Garg, ex-Finance Secretary, shared IMF data showing India's GDP growth in current US dollars at just 3.87%—well below the world average and China's rate—prompting a lively back-and-forth online.\n\nGarg contrasted this with India's real GDP growth of around 7% in local terms, arguing the dollar measure gives a fuller picture often missed in domestic talks.\n\nCritics say focusing on dollars mixes in currency fluctuations and overlooks actual output, while supporters like Sanjay Jha tie it to investor outflows exceeding Rs 3 lakh crore from Indian stocks in 2026 and job concerns. The IMF's October 2026 outlook projects India's real growth at 7%, but nominal dollar GDP lags partly due to rupee depreciation, highlighting tensions between real output metrics and global investor views.", "body_zh": "前财秘以美元口径 GDP 数据引发印度增长辩论。\n\n前财政秘书苏巴什·钱德拉·加尔格分享 IMF 数据称，印度按现价美元计 GDP 增速仅 3.87%，低于全球均值与中国，引发网上热议。\n\n加尔格将其与印度本币实际 GDP 约 7% 的增速对照，认为美元口径更能呈现国内讨论常忽略的全貌。批评者称盯住美元会混入汇率波动、忽视实际产出；支持者如 Sanjay Jha 则将其与 2026 年印度股市外资流出逾 3 万亿卢比及就业担忧挂钩。\n\nIMF 2026 年 10 月展望仍预计印度实际增速 7%，但名义美元 GDP 因卢比贬值等因素滞后，凸显产出指标与全球投资者视角之间的张力。", "url": "https://x.com/i/trending/2112431560116826201", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T06:36:16.000Z"}, {"id": "2112771431633502285", "domain": "商业", "title_en": "Nifty Gaps Up Then Faces Selling Pressure on October 21", "title_zh": "节后高开后 Nifty 遭遇抛压", "hook_en": "Nifty started the day with a promising gap-up above 23,000, fueled by IT gains and IPO buzz, but sellers quickly stepped in as charts signaled risks.", "hook_zh": "排灯节后 Nifty 曾乐观跳空高开，但卖方迅速入场，指数在震荡中回落。", "summary_en": "After Monday's 1.11% drop to 22,888.95, the index opened higher on positive GIFT Nifty signals, Jio Platforms IPO excitement, and India-US trade hopes, yet Elliott Wave analysis warned of a downside zone between 23,060-23,175 targeting 22,560-22,478. Analysts like Ashish H Kyal highlighted key levels, with a break above 22,970 eyeing 23,050-23,120 or below 22,830 pressuring 22,728, and morning targets hit before a sharp reversal. Broader factors included global cues and high Brent crude at $110, underscoring the market's focus on precise supports around 22,700-22,800 amid volatility.", "summary_zh": "指数周一收于 22888.95，跌 1.11%；随后开于约 23016，最高 23120.90，再回落至 22700–22800 一带。技术派如 SweeGlu 艾略特波浪使用者在 23060–23175 区间看到抛售，下行关注 22560–22478；Ashish H Kyal 指出关键区间波动，Mahesh Khandelwal 则预期自 22500 一带反转冲向 24000 上方。布伦特原油约每桶 110 美元加重通胀担忧；Jio Platforms IPO 与二季报推动部分 IT 买盘，但整体仍偏获利了结。", "body_en": "Nifty Gaps Up Then Faces Selling Pressure on October 21.\n\nNifty started the day with a promising gap-up above 23,000, fueled by IT gains and IPO buzz, but sellers quickly stepped in as charts signaled risks.\n\nAfter Monday's 1.11% drop to 22,888.95, the index opened higher on positive GIFT Nifty signals, Jio Platforms IPO excitement, and India-US trade hopes, yet Elliott Wave analysis warned of a downside zone between 23,060-23,175 targeting 22,560-22,478.\n\nAnalysts like Ashish H Kyal highlighted key levels, with a break above 22,970 eyeing 23,050-23,120 or below 22,830 pressuring 22,728, and morning targets hit before a sharp reversal. Broader factors included global cues and high Brent crude at $110, underscoring the market's focus on precise supports around 22,700-22,800 amid volatility.", "body_zh": "节后高开后 Nifty 遭遇抛压。\n\n排灯节后 Nifty 曾乐观跳空高开，但卖方迅速入场，指数在震荡中回落。\n\n指数周一收于 22888.95，跌 1.11%；随后开于约 23016，最高 23120.90，再回落至 22700–22800 一带。技术派如 SweeGlu 艾略特波浪使用者在 23060–23175 区间看到抛售，下行关注 22560–22478；Ashish H Kyal 指出关键区间波动，Mahesh Khandelwal 则预期自 22500 一带反转冲向 24000 上方。\n\n布伦特原油约每桶 110 美元加重通胀担忧；Jio Platforms IPO 与二季报推动部分 IT 买盘，但整体仍偏获利了结。", "url": "https://x.com/i/trending/2112771431633502285", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T08:16:34.000Z"}, {"id": "2112266057628913774", "domain": "商业", "title_en": "Hedge Funds Dump Tech Stocks at Fastest Pace in Decade", "title_zh": "对冲基金十年最快速度抛售科技股", "hook_en": "Hedge funds hit the sell button on tech stocks harder than they have in at least a decade, unloading positions amid sharp market drops.", "hook_zh": "对冲基金对科技股的抛售力度至少创下十年来最快，正值市场大跌。", "summary_en": "Through October 15, hedge funds cut technology exposure at the quickest rate since at least 2016, reversing all net buying of AI stocks since early 2025 in just one week. Semiconductors bore the brunt, making up 57% of U.S. tech sales, as the Nasdaq 100 fell 5.5%—its worst week since April 2025—and the SOX index hit its lowest ratio to the S&P 500 since April. Investors also rushed into credit default swaps on AI-linked firms like Nvidia and Meta, with spreads hitting records and trading volumes surging, while funds shifted toward U.S. Treasurys amid a negative risk-appetite signal.", "summary_zh": "截至 10 月 15 日，对冲基金削减科技敞口的速度为至少 2016 年以来最快，一周内就逆转了自 2025 年初以来对 AI 股的净买入。半导体占美国科技卖出的 57%；纳斯达克 100 当周跌 5.5%，为 2025 年 4 月以来最差。投资者还大量买入英伟达、Meta 等 AI 相关信用违约互换，利差与成交量创新高，同时资金转向美债。", "body_en": "Hedge Funds Dump Tech Stocks at Fastest Pace in Decade.\n\nHedge funds hit the sell button on tech stocks harder than they have in at least a decade, unloading positions amid sharp market drops.\n\nThrough October 15, hedge funds cut technology exposure at the quickest rate since at least 2016, reversing all net buying of AI stocks since early 2025 in just one week. Semiconductors bore the brunt, making up 57% of U.S.\n\ntech sales, as the Nasdaq 100 fell 5.5%—its worst week since April 2025—and the SOX index hit its lowest ratio to the S&P 500 since April. Investors also rushed into credit default swaps on AI-linked firms like Nvidia and Meta, with spreads hitting records and trading volumes surging, while funds shifted toward U.S. Treasurys amid a negative risk-appetite signal.", "body_zh": "对冲基金十年最快速度抛售科技股。\n\n对冲基金对科技股的抛售力度至少创下十年来最快，正值市场大跌。\n\n截至 10 月 15 日，对冲基金削减科技敞口的速度为至少 2016 年以来最快，一周内就逆转了自 2025 年初以来对 AI 股的净买入。半导体占美国科技卖出的 57%；纳斯达克 100 当周跌 5.5%，为 2025 年 4 月以来最差。\n\n投资者还大量买入英伟达、Meta 等 AI 相关信用违约互换，利差与成交量创新高，同时资金转向美债。", "url": "https://x.com/i/trending/2112266057628913774", "category": "News", "topics": ["Business & Finance", "Technology"], "updated_at": "2026-10-20T21:07:55.000Z"}, {"id": "2112319265076367697", "domain": "商业", "title_en": "Jio Platforms IPO Fully Subscribed in 100 Minutes on Opening Day", "title_zh": "Jio Platforms IPO 开盘当日极速满额认购", "hook_en": "Reliance Industries' massive Jio Platforms IPO hit full subscription in just 100 minutes, with bids pouring in from institutions and employees alike.", "hook_zh": "印度史上最大 IPO 开门红：Jio Platforms 不到两小时即满额认购，机构抢筹踊跃。", "summary_en": "The ₹30,213 crore offering opened October 21 at ₹1,065-₹1,119 per share, aiming to repay up to ₹27,500 crore in Jio telecom debt while boosting employee morale through early salary advances for 4.2 lakh staff. Qualified institutional buyers led the charge, oversubscribing their quota early and pushing overall demand to three times by day's end. Zerodha's Nithin Kamath credited Jio's affordable data for bringing millions online and growing India's investor base from 2 crore in 2016 to over 13 crore today, marking this as the largest and fastest-subscribed IPO in recent history.", "summary_zh": "信实工业旗下 Jio Platforms 于 10 月 21 日启动约 30213 亿卢比 IPO，发行价区间每份 1065–1119 卢比，规模与认购速度均刷新纪录。锚定投资者事先承诺约 8110 亿卢比，合格机构买方份额在数分钟内超额认购逾 3 倍，散户兴趣稳步上升。募集资金主要用于还债与公司用途，估值约在 1000–1080 亿美元；申购至 10 月 23 日，预计 10 月 28 日上市。Zerodha 的 Nithin Kamath 称，Jio 推动印度数字浪潮，也让投资者基数从 2016 年约 2000 万增至逾 1.3 亿。", "body_en": "Jio Platforms IPO Fully Subscribed in 100 Minutes on Opening Day.\n\nReliance Industries' massive Jio Platforms IPO hit full subscription in just 100 minutes, with bids pouring in from institutions and employees alike.\n\nThe ₹30,213 crore offering opened October 21 at ₹1,065-₹1,119 per share, aiming to repay up to ₹27,500 crore in Jio telecom debt while boosting employee morale through early salary advances for 4.2 lakh staff.\n\nQualified institutional buyers led the charge, oversubscribing their quota early and pushing overall demand to three times by day's end. Zerodha's Nithin Kamath credited Jio's affordable data for bringing millions online and growing India's investor base from 2 crore in 2016 to over 13 crore today, marking this as the largest and fastest-subscribed IPO in recent history.", "body_zh": "Jio Platforms IPO 开盘当日极速满额认购。\n\n印度史上最大 IPO 开门红：Jio Platforms 不到两小时即满额认购，机构抢筹踊跃。\n\n信实工业旗下 Jio Platforms 于 10 月 21 日启动约 30213 亿卢比 IPO，发行价区间每份 1065–1119 卢比，规模与认购速度均刷新纪录。锚定投资者事先承诺约 8110 亿卢比，合格机构买方份额在数分钟内超额认购逾 3 倍，散户兴趣稳步上升。\n\n募集资金主要用于还债与公司用途，估值约在 1000–1080 亿美元；申购至 10 月 23 日，预计 10 月 28 日上市。Zerodha 的 Nithin Kamath 称，Jio 推动印度数字浪潮，也让投资者基数从 2016 年约 2000 万增至逾 1.3 亿。", "url": "https://x.com/i/trending/2112319265076367697", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T16:35:07.000Z"}, {"id": "2112933585816781110", "domain": "商业", "title_en": "ANC Official Blames Global Conflicts for South Africa's Economic Woes, Faces Sharp Backlash", "title_zh": "非国大官员把经济困局甩给全球冲突，遭尖锐反弹", "hook_en": "Charles Sekoati pointed to wars in Ukraine and the Middle East as the culprits behind South Africa's stalled growth. Online critics fired back, saying domestic failures have dragged the economy down for over a decade.", "hook_zh": "Charles Sekoati 把南非增长停滞归咎于乌克兰与中东战事。网上批评者回击：国内失灵已拖累经济十余年。", "summary_en": "On the day Finance Minister Enoch Godongwana presented the Medium-Term Budget Policy Statement, ANC finance whip Charles Sekoati told Newzroom Afrika that unforeseen global crises like the Russia-Ukraine war and Middle East tensions are blocking job creation and growth. Godongwana noted some fiscal gains, like a stabilized debt-to-GDP ratio at 78.4%, but cut the 2026 growth forecast to 1.2% due to higher oil and food prices. Critics highlighted that South Africa's GDP per capita in 2025 remains below 2008 levels, with IMF data showing 1.0% growth projected for 2026—far below neighbors like Ethiopia at 9.2%—and called the explanation a deflection from years of policy uncertainty, poor infrastructure, and high unemployment.", "summary_zh": "在财政部长 Enoch Godongwana 公布中期预算政策声明当天，非国大财政党鞭 Charles Sekoati 对 Newzroom Afrika 表示，俄乌战争、中东紧张等意外全球危机阻碍就业与增长。Godongwana 提到债务占 GDP 比稳定在 78.4% 等财政改善，但因油价与粮价上涨，将 2026 年增长预期下调至 1.2%。批评者指出，南非 2025 年人均 GDP 仍低于 2008 年水平，IMF 预计 2026 年仅增长 1.0%，远低于邻国如埃塞俄比亚的 9.2%，并称这一解释是在回避多年的政策不确定、基础设施薄弱与高失业。", "body_en": "ANC Official Blames Global Conflicts for South Africa's Economic Woes, Faces Sharp Backlash.\n\nCharles Sekoati pointed to wars in Ukraine and the Middle East as the culprits behind South Africa's stalled growth. Online critics fired back, saying domestic failures have dragged the economy down for over a decade.\n\nOn the day Finance Minister Enoch Godongwana presented the Medium-Term Budget Policy Statement, ANC finance whip Charles Sekoati told Newzroom Afrika that unforeseen global crises like the Russia-Ukraine war and Middle East tensions are blocking job creation and growth.\n\nGodongwana noted some fiscal gains, like a stabilized debt-to-GDP ratio at 78.4%, but cut the 2026 growth forecast to 1.2% due to higher oil and food prices. Critics highlighted that South Africa's GDP per capita in 2025 remains below 2008 levels, with IMF data showing 1.0% growth projected for 2026—far below neighbors like Ethiopia at 9.2%—and called the explanation a deflection from years of policy uncertainty, poor infrastructure, and high unemployment.", "body_zh": "非国大官员把经济困局甩给全球冲突，遭尖锐反弹。\n\nCharles Sekoati 把南非增长停滞归咎于乌克兰与中东战事。网上批评者回击：国内失灵已拖累经济十余年。\n\n在财政部长 Enoch Godongwana 公布中期预算政策声明当天，非国大财政党鞭 Charles Sekoati 对 Newzroom Afrika 表示，俄乌战争、中东紧张等意外全球危机阻碍就业与增长。\n\nGodongwana 提到债务占 GDP 比稳定在 78.4% 等财政改善，但因油价与粮价上涨，将 2026 年增长预期下调至 1.2%。批评者指出，南非 2025 年人均 GDP 仍低于 2008 年水平，IMF 预计 2026 年仅增长 1.0%，远低于邻国如埃塞俄比亚的 9.2%，并称这一解释是在回避多年的政策不确定、基础设施薄弱与高失业。", "url": "https://x.com/i/trending/2112933585816781110", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T15:54:19.000Z"}, {"id": "2112507803138973871", "domain": "商业", "title_en": "Fed's $1.827 Billion Treasury Purchase Lifts Stocks and Crypto", "title_zh": "美联储购入 18.27 亿美元国债，股币齐涨", "hook_en": "US stocks and cryptocurrencies climbed Tuesday after the Federal Reserve bought $1.827 billion in Treasury bills, settling the same day and fueling trader excitement.", "hook_zh": "美联储买入 18.27 亿美元短期国债并于当日交割后，美股与加密货币周二走高，交易员情绪升温。", "summary_en": "The New York Fed's October 19 operation accepted $1.827 billion in 4-to-12-month Treasury bills, with settlement on October 20 as part of its regular secondary-market purchases to maintain banking reserves. Bitcoin rose about 1.35% to near $82,952, while the S&P 500 gained 0.65% to around 7,741, prompting posts calling the move 'massive' and bullish for risk assets. Traders highlighted the liquidity injection ahead of more scheduled purchases through November, though some noted it mostly replaces maturing holdings rather than expanding the balance sheet.", "summary_zh": "纽约联储 10 月 19 日操作接受约 18.27 亿美元、期限 4 至 12 个月的国债标售，10 月 20 日交割，属维持银行准备金的常规二级市场购买。比特币涨约 1.35% 至近 82952 美元，标普 500 涨约 0.65% 至约 7741 点，有帖文称流动性注入「巨大」并利好风险资产。交易员关注 11 月前更多既定购买，但也有人指出多为滚动到期持仓，并非显著扩表。", "body_en": "Fed's $1.827 Billion Treasury Purchase Lifts Stocks and Crypto.\n\nUS stocks and cryptocurrencies climbed Tuesday after the Federal Reserve bought $1.827 billion in Treasury bills, settling the same day and fueling trader excitement.\n\nThe New York Fed's October 19 operation accepted $1.827 billion in 4-to-12-month Treasury bills, with settlement on October 20 as part of its regular secondary-market purchases to maintain banking reserves.\n\nBitcoin rose about 1.35% to near $82,952, while the S&P 500 gained 0.65% to around 7,741, prompting posts calling the move 'massive' and bullish for risk assets. Traders highlighted the liquidity injection ahead of more scheduled purchases through November, though some noted it mostly replaces maturing holdings rather than expanding the balance sheet.", "body_zh": "美联储购入 18.27 亿美元国债，股币齐涨。\n\n美联储买入 18.27 亿美元短期国债并于当日交割后，美股与加密货币周二走高，交易员情绪升温。\n\n纽约联储 10 月 19 日操作接受约 18.27 亿美元、期限 4 至 12 个月的国债标售，10 月 20 日交割，属维持银行准备金的常规二级市场购买。\n\n比特币涨约 1.35% 至近 82952 美元，标普 500 涨约 0.65% 至约 7741 点，有帖文称流动性注入「巨大」并利好风险资产。交易员关注 11 月前更多既定购买，但也有人指出多为滚动到期持仓，并非显著扩表。", "url": "https://x.com/i/trending/2112507803138973871", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T19:09:54.000Z"}, {"id": "2112795004678676841", "domain": "商业", "title_en": "Indian Markets Slide as Small Caps Tumble, Anger Targets Finance Minister", "title_zh": "印度中小盘暴跌，市场怒火指向财长", "hook_en": "Investors watched in frustration as small and mid-cap stocks plunged on October 21, 2026, fueling direct calls for Finance Minister Nirmala Sitharaman to step down.", "hook_zh": "2026 年 10 月 21 日印度中小盘股急挫，投资者沮丧情绪高涨，社交媒体上出现要求财长西塔拉曼辞职的呼声。", "summary_en": "The Nifty 50 closed at 22,811.35, down 0.34%, and Sensex at 73,709.69, off 0.19%, but small-cap indices dropped over 2.3% with BSE companies losing Rs 11 lakh crore in value over two days. High leverage in small caps, now 49% of margin trading, amplified the sell-off amid rising crude oil prices, foreign selling, and profit booking. Social media users vented anger with posts like 'Nirmala Sitharaman please #resign. You have destroyed Indian Capital market,' while Sitharaman has defended the economy's fundamentals despite liquidity concerns.", "summary_zh": "Nifty 50 收于 22811.35 点跌 0.34%，Sensex 报 73709.69 点跌 0.19%，但小盘指数跌逾 2.3%，孟买证交所公司两日市值蒸发约 11 万亿卢比。小盘股高杠杆——保证金交易占比约 49%——在油价上涨、外资抛售与获利了结中放大跌幅。社交平台出现「请西塔拉曼辞职，你毁掉了印度资本市场」等帖文；财长则继续强调基本面稳健，并谈及流动性问题。", "body_en": "Indian Markets Slide as Small Caps Tumble, Anger Targets Finance Minister.\n\nInvestors watched in frustration as small and mid-cap stocks plunged on October 21, 2026, fueling direct calls for Finance Minister Nirmala Sitharaman to step down.\n\nThe Nifty 50 closed at 22,811.35, down 0.34%, and Sensex at 73,709.69, off 0.19%, but small-cap indices dropped over 2.3% with BSE companies losing Rs 11 lakh crore in value over two days. High leverage in small caps, now 49% of margin trading, amplified the sell-off amid rising crude oil prices, foreign selling, and profit booking.\n\nSocial media users vented anger with posts like 'Nirmala Sitharaman please #resign. You have destroyed Indian Capital market,' while Sitharaman has defended the economy's fundamentals despite liquidity concerns.", "body_zh": "印度中小盘暴跌，市场怒火指向财长。\n\n2026 年 10 月 21 日印度中小盘股急挫，投资者沮丧情绪高涨，社交媒体上出现要求财长西塔拉曼辞职的呼声。\n\nNifty 50 收于 22811.35 点跌 0.34%，Sensex 报 73709.69 点跌 0.19%，但小盘指数跌逾 2.3%，孟买证交所公司两日市值蒸发约 11 万亿卢比。\n\n小盘股高杠杆——保证金交易占比约 49%——在油价上涨、外资抛售与获利了结中放大跌幅。社交平台出现「请西塔拉曼辞职，你毁掉了印度资本市场」等帖文；财长则继续强调基本面稳健，并谈及流动性问题。", "url": "https://x.com/i/trending/2112795004678676841", "category": "News", "topics": ["Business & Finance", "Stocks"], "updated_at": "2026-10-21T13:45:53.000Z"}, {"id": "2112547757474840966", "domain": "商业", "title_en": "Strive Inc. Lists SATS Preferred Stock on Nasdaq After $630 Million Raise", "title_zh": "Strive 完成约 6.3 亿美元融资后，SATS 优先股登陆纳斯达克", "hook_en": "Strive Inc. rang in a new era by listing its high-yield SATS preferred stock on Nasdaq, fresh off raising $630 million to fuel more Bitcoin buys.", "hook_zh": "Strive 将高收益 SATS 优先股在纳斯达克上市，刚完成约 6.3 亿美元融资，用于继续增持比特币。", "summary_en": "The Bitcoin-focused asset manager upsized its IPO and directed most of the $608 million in net proceeds toward additional Bitcoin purchases and income assets, potentially funding over 7,500 BTC to make it the second-largest corporate holder. The 15% Series A Perpetual SATS stock offers daily dividends starting November 9, 2026, trading above its $90 issue price with strong first-day volume of 800,600 shares and $75 million in dollar volume. Chief Risk Officer Jeff Walton welcomed the new ticker, while observers praised the structure for stable income junior to SATA but senior to common shares, fitting into rising corporate Bitcoin treasury trends.", "summary_zh": "这家比特币导向的资管公司上调 IPO 规模，约 6.08 亿美元净募资大部分将用于追加购入比特币与收益资产，理论上可再买逾 7500 枚 BTC，或成第二大企业持币方。15% 股息的 A 系列永久优先股 SATS 自 2026 年 11 月 9 日起按日分红，首日成交约 80.06 万股、约 7500 万美元，价格高于 90 美元发行价。首席风险官 Jeff Walton 欢迎新代码；观察人士称该结构收益相对稳定，清偿顺序低于 SATA、高于普通股，契合企业比特币库存升温趋势。", "body_en": "Strive Inc. Lists SATS Preferred Stock on Nasdaq After $630 Million Raise.\n\nStrive Inc. rang in a new era by listing its high-yield SATS preferred stock on Nasdaq, fresh off raising $630 million to fuel more Bitcoin buys.\n\nThe Bitcoin-focused asset manager upsized its IPO and directed most of the $608 million in net proceeds toward additional Bitcoin purchases and income assets, potentially funding over 7,500 BTC to make it the second-largest corporate holder.\n\nThe 15% Series A Perpetual SATS stock offers daily dividends starting November 9, 2026, trading above its $90 issue price with strong first-day volume of 800,600 shares and $75 million in dollar volume. Chief Risk Officer Jeff Walton welcomed the new ticker, while observers praised the structure for stable income junior to SATA but senior to common shares, fitting into rising corporate Bitcoin treasury trends.", "body_zh": "Strive 完成约 6.3 亿美元融资后，SATS 优先股登陆纳斯达克。\n\nStrive 将高收益 SATS 优先股在纳斯达克上市，刚完成约 6.3 亿美元融资，用于继续增持比特币。\n\n这家比特币导向的资管公司上调 IPO 规模，约 6.08 亿美元净募资大部分将用于追加购入比特币与收益资产，理论上可再买逾 7500 枚 BTC，或成第二大企业持币方。\n\n15% 股息的 A 系列永久优先股 SATS 自 2026 年 11 月 9 日起按日分红，首日成交约 80.06 万股、约 7500 万美元，价格高于 90 美元发行价。首席风险官 Jeff Walton 欢迎新代码；观察人士称该结构收益相对稳定，清偿顺序低于 SATA、高于普通股，契合企业比特币库存升温趋势。", "url": "https://x.com/i/trending/2112547757474840966", "category": "News", "topics": ["Business & Finance", "Cryptocurrency"], "updated_at": "2026-10-21T17:08:28.000Z"}, {"id": "2112620331987062878", "domain": "商业", "title_en": "Investors Surge Protection Purchases on AI Tech Debt", "title_zh": "投资者创纪录买入 CDS，对冲 AI 企业债务风险", "hook_en": "Wall Street traders are snapping up insurance against defaults on massive AI loans, with volumes hitting records as costs climb.", "hook_zh": "AI 公司为数据中心与芯片大举举债之际，投资者正以前所未有的规模买入信用违约互换，防范违约。", "summary_en": "Trading in credit default swaps tied to Nvidia, Meta, Amazon, Alphabet, Microsoft, and others jumped over fourfold to $9 billion weekly in September, fueled by $466 billion in 2026 AI bond sales for data centers and chips. Spreads reached records like Meta's 108 basis points and Nvidia's 101, while riskier names like CoreWeave hit 1,090 amid leverage worries. A report warns of subprime-like risks to pension funds and retirement plans, though analysts point to strong earnings as a counterbalance.", "summary_zh": "与 AI 相关企业在 2026 年累计发行约 4660 亿美元债务，超过去年四倍，支撑大规模数据中心与芯片投资。9 月针对甲骨文、英伟达、Meta 等债券的 CDS 周交易额达 90 亿美元，保护成本飙升——Meta 约 108 个基点、英伟达约 101，CoreWeave 则超过 1000、进入困境区间。分析人士如穆罕默德·埃里安对借贷潮表示不安，亦有报告警示再包装债务卖给养老金等资金或带有类似次贷的风险；也有观点以强劲盈利增长作为对冲论据。", "body_en": "Investors Buy Record CDS to Hedge AI Company Debt Risks.\n\nAs AI firms borrow billions for data centers and chips, investors are snapping up credit default swaps at unprecedented levels to guard against defaults.\n\nAI-linked companies issued $466 billion in debt through 2026, more than quadrupling last year's pace, fueling massive data center and chip investments.\n\nWeekly CDS trading on bonds from Oracle, Nvidia, Meta, and others hit $9 billion in September, with protection costs soaring—Meta at 108 basis points, Nvidia at 101, and CoreWeave over 1,000 in distressed levels. Analysts like Mohamed El-Erian flag unease over the borrowing surge, while reports warn of subprime-like risks in repackaged debt sold to pensions, though some point to strong earnings growth as a counterbalance.", "body_zh": "投资者创纪录买入 CDS，对冲 AI 企业债务风险。\n\nAI 公司为数据中心与芯片大举举债之际，投资者正以前所未有的规模买入信用违约互换，防范违约。\n\n与 AI 相关企业在 2026 年累计发行约 4660 亿美元债务，超过去年四倍，支撑大规模数据中心与芯片投资。\n\n9 月针对甲骨文、英伟达、Meta 等债券的 CDS 周交易额达 90 亿美元，保护成本飙升——Meta 约 108 个基点、英伟达约 101，CoreWeave 则超过 1000、进入困境区间。分析人士如穆罕默德·埃里安对借贷潮表示不安，亦有报告警示再包装债务卖给养老金等资金或带有类似次贷的风险；也有观点以强劲盈利增长作为对冲论据。", "url": "https://x.com/i/trending/2112620331987062878", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T16:34:34.000Z"}, {"id": "2112369182595788855", "domain": "商业", "title_en": "Jio Platforms Gears Up for India's Largest IPO with ₹30,000 Crore Raise", "title_zh": "Jio Platforms 筹备印度史上最大 IPO，拟募资约 3 万亿卢比", "hook_en": "From making mobile data affordable for millions to powering everyday streaming, Jio's decade-long journey has transformed lives across India.", "hook_zh": "从让数亿人用得起移动流量，到撑起日常流媒体，Jio 十余年的旅程改写了印度人的数字生活。", "summary_en": "Jio Platforms, Reliance Industries' digital arm, will launch India's biggest IPO on October 21, offering up to 27 crore shares to raise around ₹30,213 crore at the top price of ₹1,119 each. The funds will mostly repay debt at its telecom subsidiary, which serves 533 million customers and handles 60% of India's wireless data traffic. People fondly remember the shift from cautious video watching to seamless scrolling and calls, crediting Jio's growth under Mukesh and Akash Ambani, while analysts watch if its scale can drive better returns through efficiency and new services like cloud and broadband.", "summary_zh": "信实工业数字臂膀 Jio Platforms 将于 10 月 21 日启动印度最大规模 IPO，最多发售 27 亿股，顶价每股 1119 卢比，约可募资 30213 亿卢比。资金主要用于偿还电信子公司债务；该子公司服务 5.33 亿用户，承载印度约 60% 无线数据流量。公众仍记得从舍不得看视频到流畅刷屏、通话的转变，归功于穆克什与阿卡什·安巴尼治下的扩张；分析师则关注其规模能否通过效率提升与云、宽带等新业务换来更好回报。", "body_en": "Jio Platforms Gears Up for India's Largest IPO with ₹30,000 Crore Raise.\n\nFrom making mobile data affordable for millions to powering everyday streaming, Jio's decade-long journey has transformed lives across India.\n\nJio Platforms, Reliance Industries' digital arm, will launch India's biggest IPO on October 21, offering up to 27 crore shares to raise around ₹30,213 crore at the top price of ₹1,119 each.\n\nThe funds will mostly repay debt at its telecom subsidiary, which serves 533 million customers and handles 60% of India's wireless data traffic. People fondly remember the shift from cautious video watching to seamless scrolling and calls, crediting Jio's growth under Mukesh and Akash Ambani, while analysts watch if its scale can drive better returns through efficiency and new services like cloud and broadband.", "body_zh": "Jio Platforms 筹备印度史上最大 IPO，拟募资约 3 万亿卢比。\n\n从让数亿人用得起移动流量，到撑起日常流媒体，Jio 十余年的旅程改写了印度人的数字生活。\n\n信实工业数字臂膀 Jio Platforms 将于 10 月 21 日启动印度最大规模 IPO，最多发售 27 亿股，顶价每股 1119 卢比，约可募资 30213 亿卢比。\n\n资金主要用于偿还电信子公司债务；该子公司服务 5.33 亿用户，承载印度约 60% 无线数据流量。公众仍记得从舍不得看视频到流畅刷屏、通话的转变，归功于穆克什与阿卡什·安巴尼治下的扩张；分析师则关注其规模能否通过效率提升与云、宽带等新业务换来更好回报。", "url": "https://x.com/i/trending/2112369182595788855", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T02:29:15.000Z"}, {"id": "2112722969550107047", "domain": "商业", "title_en": "InterLink Founder Clears Up Rumors Ahead of ITLG Mainnet Launch", "title_zh": "InterLink 创始人澄清传闻，ITLG 主网即将上线", "hook_en": "After nearly a year of whispers, founder KV stepped in with straight talk on the team's credentials and big partnerships, easing nerves as users gear up for token claims.", "hook_zh": "近一年传言不断后，创始人 KV 就团队资历与大牌合作直言澄清，缓解用户在代币申领前的紧张。", "summary_en": "InterLink, a blockchain using AI for Proof of Personhood, is nearing its ITLG Mainnet with 55 billion mined tokens ready for on-chain migration via a KYC portal—completing Step 1 qualifies users, though not all balances may be claimable. KV highlighted the team's heavy hitters like a NYSE chairman and Wall Street leader, plus partnerships with Google for Startups, OKX, Visa, and AWS, all from U.S. headquarters with global plans. Community tools like vaults for borrowing against tokens and in-app livestreams are rolling out, while supporters point to milestones like the 2026 private mainnet as proof of progress amid lingering questions on supply and verification.", "summary_zh": "InterLink 是用 AI 做「人格证明」的区块链，ITLG 主网临近上线，约 550 亿已挖代币将经 KYC 门户上链迁移——完成第一步即可资格，但并非所有余额都能申领。KV 强调团队有纽交所主席、华尔街高管等，并与 Google for Startups、OKX、Visa、AWS 合作，总部在美国、布局全球。社区借贷金库、应用内直播等工具陆续上线；支持者把 2026 私有主网等节点视为进展证据，供给与验证问题仍存疑。", "body_en": "InterLink Founder Clears Up Rumors Ahead of ITLG Mainnet Launch.\n\nAfter nearly a year of whispers, founder KV stepped in with straight talk on the team's credentials and big partnerships, easing nerves as users gear up for token claims.\n\nInterLink, a blockchain using AI for Proof of Personhood, is nearing its ITLG Mainnet with 55 billion mined tokens ready for on-chain migration via a KYC portal—completing Step 1 qualifies users, though not all balances may be claimable. KV highlighted the team's heavy hitters like a NYSE chairman and Wall Street leader, plus partnerships with Google for Startups, OKX, Visa, and AWS, all from U.S.\n\nheadquarters with global plans. Community tools like vaults for borrowing against tokens and in-app livestreams are rolling out, while supporters point to milestones like the 2026 private mainnet as proof of progress amid lingering questions on supply and verification.", "body_zh": "InterLink 创始人澄清传闻，ITLG 主网即将上线。\n\n近一年传言不断后，创始人 KV 就团队资历与大牌合作直言澄清，缓解用户在代币申领前的紧张。\n\nInterLink 是用 AI 做「人格证明」的区块链，ITLG 主网临近上线，约 550 亿已挖代币将经 KYC 门户上链迁移——完成第一步即可资格，但并非所有余额都能申领。\n\nKV 强调团队有纽交所主席、华尔街高管等，并与 Google for Startups、OKX、Visa、AWS 合作，总部在美国、布局全球。社区借贷金库、应用内直播等工具陆续上线；支持者把 2026 私有主网等节点视为进展证据，供给与验证问题仍存疑。", "url": "https://x.com/i/trending/2112722969550107047", "category": "Other", "topics": ["Technology", "Cryptocurrency"], "updated_at": "2026-10-21T04:52:46.000Z"}, {"id": "2112486884211650655", "domain": "中国", "title_en": "Sindh CM Secures 34 China Deals at Shanghai Conference", "title_zh": "巴基斯坦信德省首席部长在沪签下 34 项对华合作", "hook_en": "Sindh Chief Minister Syed Murad Ali Shah stood by as 34 key agreements were signed in Shanghai, unlocking fresh paths for jobs and growth back home.", "hook_zh": "信德省首席部长穆拉德·阿里·沙阿在上海见证 34 项关键协议签署，为本地就业与增长打开新路。", "summary_en": "At the Sindh Investment and Trade Conference in Shanghai on October 15, 2026, CM Shah witnessed 34 memorandums of understanding and agreements with Chinese partners—10 government-to-government and 24 business-to-business. These cover energy like Thar coal, electric vehicles, AI-driven digital transformation, agriculture, and logistics, building on successes such as power plants and wind farms in the province. The event drew 400 delegates from over 100 companies, highlighting Sindh's ports, workforce, resources, and tax incentives, while follow-up meetings in Wuhan advanced projects like climate-resilient crops and Karachi's water supply. Supporters praise the moves for fostering investment, innovation, and prosperity rooted in the 75-year Pak-China friendship.", "summary_zh": "2026 年 10 月 15 日上海举行的信德投资贸易会议上，沙阿见证与中国伙伴签署 34 份备忘录与协议，其中政府间 10 项、企业间 24 项，涵盖塔尔煤电、电动车、AI 数字化、农业与物流等。活动吸引百余家企业约 400 名代表；后续武汉会谈推进耐气候作物与卡拉奇供水等项目。支持者称这延续巴中建交 75 年的合作传统。", "body_en": "Sindh CM Secures 34 China Deals at Shanghai Conference.\n\nSindh Chief Minister Syed Murad Ali Shah stood by as 34 key agreements were signed in Shanghai, unlocking fresh paths for jobs and growth back home.\n\nAt the Sindh Investment and Trade Conference in Shanghai on October 15, 2026, CM Shah witnessed 34 memorandums of understanding and agreements with Chinese partners—10 government-to-government and 24 business-to-business. These cover energy like Thar coal, electric vehicles, AI-driven digital transformation, agriculture, and logistics, building on successes such as power plants and wind farms in the province.\n\nThe event drew 400 delegates from over 100 companies, highlighting Sindh's ports, workforce, resources, and tax incentives, while follow-up meetings in Wuhan advanced projects like climate-resilient crops and Karachi's water supply. Supporters praise the moves for fostering investment, innovation, and prosperity rooted in the 75-year Pak-China friendship.", "body_zh": "巴基斯坦信德省首席部长在沪签下 34 项对华合作。\n\n信德省首席部长穆拉德·阿里·沙阿在上海见证 34 项关键协议签署，为本地就业与增长打开新路。\n\n2026 年 10 月 15 日上海举行的信德投资贸易会议上，沙阿见证与中国伙伴签署 34 份备忘录与协议，其中政府间 10 项、企业间 24 项，涵盖塔尔煤电、电动车、AI 数字化、农业与物流等。活动吸引百余家企业约 400 名代表；后续武汉会谈推进耐气候作物与卡拉奇供水等项目。\n\n支持者称这延续巴中建交 75 年的合作传统。", "url": "https://x.com/i/trending/2112486884211650655", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T13:25:56.000Z"}, {"id": "2112022699237310708", "domain": "中国", "title_en": "Liangzhu Forum Opens Marking 90th Anniversary of Ancient Ruins Discovery", "title_zh": "良渚论坛开幕：纪念遗址发现 90 周年", "hook_en": "Experts from nearly 60 countries gathered in Hangzhou to celebrate 5,000-year-old Liangzhu ruins, blending ancient history with modern tech and global chats.", "hook_zh": "近 60 国专家齐聚杭州，围绕约五千年历史的良渚遗址，把古代文明、现代技术与国际交流放在同一舞台。", "summary_en": "The fourth Liangzhu Forum, held October 18-20 in Zhejiang province, honors the 90th anniversary of discovering the UNESCO-listed Liangzhu ruins, evidence of an early advanced society with rice farming. Under the theme 'Bridging the Past and the Future,' it features forums, an artists' exhibition, a cultural market with Belt and Road products, and AI glasses at the museum that guide visitors using real archives. An American archaeologist on his first China trip praised the scenery and hopes to study sites, while an Australian curator noted the link between ancient Liangzhu and today's Hangzhou; young volunteers provide bilingual support amid calls for global heritage cooperation.", "summary_zh": "第四届良渚论坛于 10 月 18–20 日在浙江举行，纪念列入联合国教科文组织名录的良渚遗址发现 90 周年——遗址见证早期发达社会与稻作农业。主题为「连接过去与未来」，活动包括论坛、艺术家展览、「一带一路」相关文创市集，以及博物馆用真实档案导览的 AI 眼镜。首次访华的美国考古学家称赞景色并希望研究遗址；澳大利亚策展人谈到古代良渚与今日杭州的关联；青年志愿者提供双语服务，各方呼吁加强全球遗产合作。", "body_en": "Liangzhu Forum Opens Marking 90th Anniversary of Ancient Ruins Discovery.\n\nExperts from nearly 60 countries gathered in Hangzhou to celebrate 5,000-year-old Liangzhu ruins, blending ancient history with modern tech and global chats.\n\nThe fourth Liangzhu Forum, held October 18-20 in Zhejiang province, honors the 90th anniversary of discovering the UNESCO-listed Liangzhu ruins, evidence of an early advanced society with rice farming.\n\nUnder the theme 'Bridging the Past and the Future,' it features forums, an artists' exhibition, a cultural market with Belt and Road products, and AI glasses at the museum that guide visitors using real archives. An American archaeologist on his first China trip praised the scenery and hopes to study sites, while an Australian curator noted the link between ancient Liangzhu and today's Hangzhou; young volunteers provide bilingual support amid calls for global heritage cooperation.", "body_zh": "良渚论坛开幕：纪念遗址发现 90 周年。\n\n近 60 国专家齐聚杭州，围绕约五千年历史的良渚遗址，把古代文明、现代技术与国际交流放在同一舞台。\n\n第四届良渚论坛于 10 月 18–20 日在浙江举行，纪念列入联合国教科文组织名录的良渚遗址发现 90 周年——遗址见证早期发达社会与稻作农业。主题为「连接过去与未来」，活动包括论坛、艺术家展览、「一带一路」相关文创市集，以及博物馆用真实档案导览的 AI 眼镜。\n\n首次访华的美国考古学家称赞景色并希望研究遗址；澳大利亚策展人谈到古代良渚与今日杭州的关联；青年志愿者提供双语服务，各方呼吁加强全球遗产合作。", "url": "https://x.com/i/trending/2112022699237310708", "category": "News", "topics": ["Science"], "updated_at": "2026-10-20T03:21:48.000Z"}, {"id": "2112895365657567737", "domain": "中国", "title_en": "Micron Reaches Labor Deal at Taiwan's Taichung Plant, Averting Strike", "title_zh": "美光与台中厂达成劳资协议，罢工风险缓解", "hook_en": "Workers at Micron's key Taichung chip plant in Taiwan can breathe easier after signing a labor agreement that pulls back from a looming strike.", "hook_zh": "美光台湾关键台中芯片厂劳资双方签署协议，此前一触即发的罢工警报得以缓和。", "summary_en": "The deal at the Taichung facility, Micron's largest in Taiwan and a hub for DRAM and high-bandwidth memory chips vital to AI servers, resolves tensions and cancels mediation set for October 22. It covers multiple issues, with both sides calling talks constructive, though details will go directly to the roughly 15,000 employees across Taiwan sites in coming days. Unions pushed for a permanent profit-sharing plan modeled on rivals like Samsung and SK Hynix, potentially worth billions annually. A separate Taoyuan union still plans a one-day warning strike on October 22, but the Taichung progress eases risks amid tight AI-driven memory demand, boosting Micron shares.", "summary_zh": "台中厂是美光在台最大据点，也是服务 AI 服务器的 DRAM 与高带宽内存枢纽。协议化解紧张，原定 10 月 22 日的调解取消。双方称谈判具建设性，细节将在未来数日直接通报全台约 1.5 万名员工。工会曾争取比照三星、SK 海力士的永久利润分享方案，潜在金额可达每年数十亿。桃园另一工会仍计划 10 月 22 日举行一日警告性罢工，但台中进展在 AI 存储需求紧张背景下降低风险，美光股价亦获提振。", "body_en": "Micron Reaches Labor Deal at Taiwan's Taichung Plant, Averting Strike.\n\nWorkers at Micron's key Taichung chip plant in Taiwan can breathe easier after signing a labor agreement that pulls back from a looming strike.\n\nThe deal at the Taichung facility, Micron's largest in Taiwan and a hub for DRAM and high-bandwidth memory chips vital to AI servers, resolves tensions and cancels mediation set for October 22. It covers multiple issues, with both sides calling talks constructive, though details will go directly to the roughly 15,000 employees across Taiwan sites in coming days.\n\nUnions pushed for a permanent profit-sharing plan modeled on rivals like Samsung and SK Hynix, potentially worth billions annually. A separate Taoyuan union still plans a one-day warning strike on October 22, but the Taichung progress eases risks amid tight AI-driven memory demand, boosting Micron shares.", "body_zh": "美光与台中厂达成劳资协议，罢工风险缓解。\n\n美光台湾关键台中芯片厂劳资双方签署协议，此前一触即发的罢工警报得以缓和。\n\n台中厂是美光在台最大据点，也是服务 AI 服务器的 DRAM 与高带宽内存枢纽。协议化解紧张，原定 10 月 22 日的调解取消。\n\n双方称谈判具建设性，细节将在未来数日直接通报全台约 1.5 万名员工。工会曾争取比照三星、SK 海力士的永久利润分享方案，潜在金额可达每年数十亿。桃园另一工会仍计划 10 月 22 日举行一日警告性罢工，但台中进展在 AI 存储需求紧张背景下降低风险，美光股价亦获提振。", "url": "https://x.com/i/trending/2112895365657567737", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-21T13:20:26.000Z"}, {"id": "2112952164025028892", "domain": "中国", "title_en": "Rep. Burlison Warns Deep State Delays Could Let China or Russia Lead UAP Disclosure", "title_zh": "伯利森警告：UAP 文件拖延或让中俄抢先披露叙事", "hook_en": "Rep. Eric Burlison shared his frustration on Fox Business: a 'Deep State' is still clutching UAP files, potentially handing China or Russia the chance to break the story first.", "hook_zh": "密苏里州共和党众议员埃里克·伯利森在福克斯商业频道吐槽：所谓「深层政府」仍攥着 UAP 档案，可能把先发权拱手让给中国或俄罗斯。", "summary_en": "During an October 21 Fox Business interview, Missouri Republican Burlison highlighted resistance within agencies despite the Trump administration's PURSUE initiative, which has released over 200 UAP documents via war.gov/UFO since May 2026—the largest batch in decades. He argued that withholding more records risks rivals gaining a first-mover advantage in shaping the global narrative on unidentified anomalous phenomena, objects he's seen in briefings that 'defy logic.' Supporters see this as a push for faster transparency and whistleblower protection, while skeptics question the evidence and public release pace amid national security debates.", "summary_zh": "在 10 月 21 日采访中，伯利森称尽管特朗普政府的 PURSUE 倡议自 2026 年 5 月起已通过 war.gov/UFO 释出逾 200 份 UAP 文件——数十年来最大一批——机构内部仍有阻力。他认为继续扣留更多记录，会让对手在塑造全球不明异常现象叙事上抢得先机；他称自己在简报中见过「有违常理」的物体。支持者视之为加速透明与保护举报人的推动，怀疑者则质疑证据与国家安全背景下的公开节奏。", "body_en": "Rep. Burlison Warns Deep State Delays Could Let China or Russia Lead UAP Disclosure.\n\nRep. Eric Burlison shared his frustration on Fox Business: a 'Deep State' is still clutching UAP files, potentially handing China or Russia the chance to break the story first.\n\nDuring an October 21 Fox Business interview, Missouri Republican Burlison highlighted resistance within agencies despite the Trump administration's PURSUE initiative, which has released over 200 UAP documents via war.gov/UFO since May 2026—the largest batch in decades. He argued that withholding more records risks rivals gaining a first-mover advantage in shaping the global narrative on unidentified anomalous phenomena, objects he's seen in briefings that 'defy logic.' Supporters see this as a push for faster transparency and whistleblower protection, while skeptics question the evidence and public release pace amid national security debates.", "body_zh": "伯利森警告：UAP 文件拖延或让中俄抢先披露叙事。\n\n密苏里州共和党众议员埃里克·伯利森在福克斯商业频道吐槽：所谓「深层政府」仍攥着 UAP 档案，可能把先发权拱手让给中国或俄罗斯。\n\n在 10 月 21 日采访中，伯利森称尽管特朗普政府的 PURSUE 倡议自 2026 年 5 月起已通过 war.gov/UFO 释出逾 200 份 UAP 文件——数十年来最大一批——机构内部仍有阻力。\n\n他认为继续扣留更多记录，会让对手在塑造全球不明异常现象叙事上抢得先机；他称自己在简报中见过「有违常理」的物体。支持者视之为加速透明与保护举报人的推动，怀疑者则质疑证据与国家安全背景下的公开节奏。", "url": "https://x.com/i/trending/2112952164025028892", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-21T17:07:26.000Z"}, {"id": "2111803212139569662", "domain": "中国", "title_en": "DeepSeek-V4.1-Flash Tops Coding Leaderboards at Fraction of Cost", "title_zh": "DeepSeek-V4.1-Flash 登顶编程榜，成本仅为对手约十分之一", "hook_en": "DeepSeek AI just dropped an updated open model that climbed to the top of coding leaderboards, outpacing pricier rivals while running smoothly on home setups.", "hook_zh": "DeepSeek 更新开源模型后登上编程榜前列，表现压过更贵的对手，且可在家用设备上流畅运行。", "summary_en": "Released on October 17, DeepSeek-V4.1-Flash-1017 earned the #1 spot among open models on Arena.ai's Code Arena: WebDev leaderboard with 1,670 points, ranking #12 overall ahead of Claude Opus 5 (High) and close to GPT-6 Sol (Max)—all at one-tenth the cost of competitors like Kimi K3 (Max). The 552B-parameter model, with MIT-licensed weights on Hugging Face, also hit #11 in Agent Arena, showing gains in success rates and reliability. Developers quickly optimized it for local use via Unsloth quantizations and DeepSeek's open-source DeepInfer framework, making frontier-level coding and agent performance accessible and affordable.", "summary_zh": "10 月 17 日发布的 DeepSeek-V4.1-Flash-1017 在 Arena.ai 的 Code Arena: WebDev 开源模型榜以 1670 分居首，总榜第 12，领先 Claude Opus 5（High），并接近 GPT-6 Sol（Max），成本约为 Kimi K3（Max）等竞品的十分之一。该 5520 亿参数模型以 MIT 许可权重登陆 Hugging Face，并在 Agent Arena 位列第 11，成功率与稳定性有提升。开发者迅速通过 Unsloth 量化与 DeepSeek 开源的 DeepInfer 框架做本地优化，使前沿级编程与智能体能力更易获得、也更可负担。", "body_en": "DeepSeek-V4.1-Flash Tops Coding Leaderboards at Fraction of Cost.\n\nDeepSeek AI just dropped an updated open model that climbed to the top of coding leaderboards, outpacing pricier rivals while running smoothly on home setups.\n\nReleased on October 17, DeepSeek-V4.1-Flash-1017 earned the #1 spot among open models on Arena.ai's Code Arena: WebDev leaderboard with 1,670 points, ranking #12 overall ahead of Claude Opus 5 (High) and close to GPT-6 Sol (Max)—all at one-tenth the cost of competitors like Kimi K3 (Max).\n\nThe 552B-parameter model, with MIT-licensed weights on Hugging Face, also hit #11 in Agent Arena, showing gains in success rates and reliability. Developers quickly optimized it for local use via Unsloth quantizations and DeepSeek's open-source DeepInfer framework, making frontier-level coding and agent performance accessible and affordable.", "body_zh": "DeepSeek-V4.1-Flash 登顶编程榜，成本仅为对手约十分之一。\n\nDeepSeek 更新开源模型后登上编程榜前列，表现压过更贵的对手，且可在家用设备上流畅运行。\n\n10 月 17 日发布的 DeepSeek-V4.1-Flash-1017 在 Arena.ai 的 Code Arena: WebDev 开源模型榜以 1670 分居首，总榜第 12，领先 Claude Opus 5（High），并接近 GPT-6 Sol（Max），成本约为 Kimi K3（Max）等竞品的十分之一。\n\n该 5520 亿参数模型以 MIT 许可权重登陆 Hugging Face，并在 Agent Arena 位列第 11，成功率与稳定性有提升。开发者迅速通过 Unsloth 量化与 DeepSeek 开源的 DeepInfer 框架做本地优化，使前沿级编程与智能体能力更易获得、也更可负担。", "url": "https://x.com/i/trending/2111803212139569662", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T11:32:56.000Z"}, {"id": "2112188369618784335", "domain": "中国", "title_en": "DHS Orders Federal Agencies to Remove DeepSeek AI Products", "title_zh": "美国土安全部要求民事机构清除 DeepSeek 产品", "hook_en": "The U.S. Department of Homeland Security just drew a firm line on Chinese AI tools in government systems, citing risks of data flowing to China and hidden security threats.", "hook_zh": "联邦民事机构接到明确指令：因涉华安全风险，须从系统中移除相关中国 AI 工具。", "summary_en": "Under a new Federal Register notice dated October 20, 2026, DHS directed civilian federal agencies to halt procurement from Hangzhou DeepSeek Artificial Intelligence Co. and remove all its products, including those embedded in third-party services. The order highlights dangers like sensitive data transfers mandated by Chinese law, collection of personal information, and potential malware in the models. DeepSeek, known for efficient open-weight AI models that run well on modest hardware, now faces these restrictions amid broader U.S. limits on Chinese tech, though defense and intelligence systems remain separately regulated.", "summary_zh": "美国国土安全部于 10 月 20 日下令，要求联邦民事机构从 IT 系统中移除所有 DeepSeek 产品、关联方及相关第三方服务，并停止后续采购。关切包括公司总部位于中国、数据可能移交中国当局、收集个人信息，以及对美国人实施恶意软件或情报搜集的风险。此举凸显美中 AI 博弈；DeepSeek 最新 V4.1 因在日常硬件上的速度与效率仍受关注。命令仅适用于民事机构，可有例外。", "body_en": "DHS Orders Federal Agencies to Remove DeepSeek AI Products.\n\nFederal agencies now face a clear directive: pull DeepSeek's Chinese AI tools from their systems to guard against data risks heading to China.\n\nThe U.S. Department of Homeland Security issued an order on October 20 requiring civilian federal agencies to remove DeepSeek products from IT systems and halt future purchases under the Federal Acquisition Supply Chain Security Act. The move addresses threats like sensitive data transfers to China, potential intelligence generation on U.S.\n\npersons, and malware risks in the models. This builds on prior limits by some agencies and states, applying broadly to civilian executive branch systems while sparing defense networks. Reactions split, with supporters praising network protection and critics noting the model's open-source nature could spur local alternatives.", "body_zh": "美国土安全部要求民事机构清除 DeepSeek 产品。\n\n联邦民事机构接到明确指令：因涉华安全风险，须从系统中移除相关中国 AI 工具。\n\n美国国土安全部于 10 月 20 日下令，要求联邦民事机构从 IT 系统中移除所有 DeepSeek 产品、关联方及相关第三方服务，并停止后续采购。关切包括公司总部位于中国、数据可能移交中国当局、收集个人信息，以及对美国人实施恶意软件或情报搜集的风险。\n\n此举凸显美中 AI 博弈；DeepSeek 最新 V4.1 因在日常硬件上的速度与效率仍受关注。命令仅适用于民事机构，可有例外。", "url": "https://x.com/i/trending/2112188369618784335", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T11:44:28.000Z"}, {"id": "2112525486228156479", "domain": "中国", "title_en": "DeepSeek V4.1 Flash Outperforms OpenAI's GPT-6 Sol on Cybersecurity Benchmarks", "title_zh": "DeepSeek V4.1 Flash 在网络安全基准上胜过受限版 GPT-6 Sol", "hook_en": "In simulated corporate networks, DeepSeek V4.1 Flash 1017 completed more multi-step offensive cybersecurity objectives than a restricted version of OpenAI’s GPT-6 Sol. This open-weight model from China delivered results at lower cost, even using more tokens.", "hook_zh": "在模拟企业网络中，DeepSeek V4.1 Flash 完成的多步进攻目标多于受限版 OpenAI GPT-6 Sol，且成本更低。", "summary_en": "Vals AI's benchmarks show DeepSeek V4.1 Flash 1017, released around October 17, excelling in agentic tasks with a 1-million-token context window and open MIT-licensed weights on Hugging Face. It achieved strong scores like 42.7 objectives in its own harness and runs locally on hardware like two NVIDIA DGX Spark systems, with developers calling the speed a potential national security risk. MiniMax M3.1 Flash competes closely, offering lower costs on coding and visual tasks, as reactions blend excitement over affordable frontier performance with caution about dual-use cyber capabilities now openly available.", "summary_zh": "Vals AI 基准显示，约 10 月 17 日发布的 DeepSeek V4.1 Flash 1017 在智能体任务上表现突出，拥有百万 token 上下文，并以 MIT 许可在 Hugging Face 开源权重。其在自有评测中取得约 42.7 个目标等成绩，可在两台英伟达 DGX Spark 等设备本地运行。开发者称速度惊人，也有人担心双用途网络能力公开可得。MiniMax M3.1 Flash 在编程与视觉任务上成本更低，竞争同样激烈。", "body_en": "DeepSeek V4.1 Flash Outperforms OpenAI's GPT-6 Sol on Cybersecurity Benchmarks.\n\nIn simulated corporate networks, DeepSeek V4.1 Flash 1017 completed more multi-step offensive cybersecurity objectives than a restricted version of OpenAI’s GPT-6 Sol. This open-weight model from China delivered results at lower cost, even using more tokens.\n\nVals AI's benchmarks show DeepSeek V4.1 Flash 1017, released around October 17, excelling in agentic tasks with a 1-million-token context window and open MIT-licensed weights on Hugging Face.\n\nIt achieved strong scores like 42.7 objectives in its own harness and runs locally on hardware like two NVIDIA DGX Spark systems, with developers calling the speed a potential national security risk. MiniMax M3.1 Flash competes closely, offering lower costs on coding and visual tasks, as reactions blend excitement over affordable frontier performance with caution about dual-use cyber capabilities now openly available.", "body_zh": "DeepSeek V4.1 Flash 在网络安全基准上胜过受限版 GPT-6 Sol。\n\n在模拟企业网络中，DeepSeek V4.1 Flash 完成的多步进攻目标多于受限版 OpenAI GPT-6 Sol，且成本更低。\n\nVals AI 基准显示，约 10 月 17 日发布的 DeepSeek V4.1 Flash 1017 在智能体任务上表现突出，拥有百万 token 上下文，并以 MIT 许可在 Hugging Face 开源权重。其在自有评测中取得约 42.7 个目标等成绩，可在两台英伟达 DGX Spark 等设备本地运行。\n\n开发者称速度惊人，也有人担心双用途网络能力公开可得。MiniMax M3.1 Flash 在编程与视觉任务上成本更低，竞争同样激烈。", "url": "https://x.com/i/trending/2112525486228156479", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T17:46:45.000Z"}, {"id": "2112572571275370804", "domain": "中国", "title_en": "Japan Faces Yttrium Shortage, Seeks US Help Against China Curbs", "title_zh": "日本钇供应告急，寻求美方协助应对中国出口限制", "hook_en": "Japan has just months left before running out of yttrium, a vital metal for jet engines and chips, as Chinese shipments nearly halt.", "hook_zh": "用于喷气发动机与芯片的关键金属钇，中国对日发运几近停滞，日本称只剩数月库存。", "summary_en": "Yttrium oxide shipments from China to Japan have almost stopped in 2026 after tighter export restrictions, driving outside prices to $1,150 per kilogram from $6 two years ago. The shortage endangers aerospace, autos, electronics, and defense, with a Japanese official warning of world economy risks if ignored. Japan asked the US to pressure China, while Washington withheld jet engine exports to Beijing and discussed solutions in recent meetings. Allies seek substitutes and new supplies amid limited global processing outside China.", "summary_zh": "2026 年中国收紧出口限制后，氧化钇对日发运几乎停止，日本以外市场价格从两年前每公斤约 6 美元飙至 1150 美元。短缺危及航空航天、汽车、电子与国防，日方官员警告若忽视将冲击世界经济。日本请求美国向中国施压；华盛顿则暂停对北京喷气发动机出口，并在近期会谈中讨论对策。盟友正寻找替代品与新供应，因中国以外全球加工能力有限。", "body_en": "Japan Faces Yttrium Shortage, Seeks US Help Against China Curbs.\n\nJapan has just months left before running out of yttrium, a vital metal for jet engines and chips, as Chinese shipments nearly halt.\n\nYttrium oxide shipments from China to Japan have almost stopped in 2026 after tighter export restrictions, driving outside prices to $1,150 per kilogram from $6 two years ago. The shortage endangers aerospace, autos, electronics, and defense, with a Japanese official warning of world economy risks if ignored.\n\nJapan asked the US to pressure China, while Washington withheld jet engine exports to Beijing and discussed solutions in recent meetings. Allies seek substitutes and new supplies amid limited global processing outside China.", "body_zh": "日本钇供应告急，寻求美方协助应对中国出口限制。\n\n用于喷气发动机与芯片的关键金属钇，中国对日发运几近停滞，日本称只剩数月库存。\n\n2026 年中国收紧出口限制后，氧化钇对日发运几乎停止，日本以外市场价格从两年前每公斤约 6 美元飙至 1150 美元。短缺危及航空航天、汽车、电子与国防，日方官员警告若忽视将冲击世界经济。\n\n日本请求美国向中国施压；华盛顿则暂停对北京喷气发动机出口，并在近期会谈中讨论对策。盟友正寻找替代品与新供应，因中国以外全球加工能力有限。", "url": "https://x.com/i/trending/2112572571275370804", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-20T19:24:35.000Z"}, {"id": "2112810342728323293", "domain": "中国", "title_en": "China Replaces Billboards with Scientists' Portraits in Major Cities", "title_zh": "中国多地用科学家肖像替换地铁商业广告", "hook_en": "Rocket scientist Qian Xuesen's giant portrait now greets shoppers in a Heze mall, replacing flashy ads with faces of national heroes.", "hook_zh": "走进地铁站，巨型屏幕上是杂交水稻先驱袁隆平等科学家，而非炫目广告。这一简单替换引来关于榜样的讨论。", "summary_en": "Since August 2026, cities like Heze, Zhengzhou, and Chongqing have filled public screens in malls, metros, and plazas with portraits of scientists such as Qian Xuesen, Yuan Longping, and Tu Youyou, complete with notes on their breakthroughs in rockets, rice, and malaria drugs. Local venues made these voluntary changes, often timed for holidays to highlight achievements in science and defense. The shift has sparked online talk about honoring innovators over celebrities and what public spaces say about a society's values.", "summary_zh": "中国开始在地铁站、商场等公共大屏用著名科学家肖像替换广告，包括农学家袁隆平、因疟疾治疗获诺奖的屠呦呦、火箭专家钱学森、核物理学家邓稼先等。举措 2026 年 8 月起自山东推开，并扩展至郑州、重庆等城市，尤其在国庆等节点，企业自愿腾出空间致敬科学成就、激励下一代。相关视频在印度等地引发讨论，有人对比本地公共传播，呼吁更重视创新而非商业喧嚣。", "body_en": "China Replaces Metro Ads with Portraits of Scientists.\n\nImagine stepping into a metro station where giant screens honor scientists like hybrid rice pioneer Yuan Longping instead of flashy ads. It's a simple swap that's getting people talking about role models.\n\nChina has started replacing advertisements on large public screens in metro stations, malls, and other spaces with portraits of renowned scientists such as agronomist Yuan Longping, Nobel winner Tu Youyou for malaria treatment, rocket expert Qian Xuesen, and nuclear physicist Deng Jiaxian.\n\nThe initiative began in Shandong province in August 2026 and spread to cities like Zhengzhou and Chongqing, especially around national holidays, with businesses voluntarily dedicating the space to celebrate scientific achievements and inspire the next generation. Videos of these displays have sparked online conversations in places like India, where some contrast it with local public messaging and call for emulating the focus on innovation over commercial noise.", "body_zh": "中国多地用科学家肖像替换地铁商业广告。\n\n走进地铁站，巨型屏幕上是杂交水稻先驱袁隆平等科学家，而非炫目广告。这一简单替换引来关于榜样的讨论。\n\n中国开始在地铁站、商场等公共大屏用著名科学家肖像替换广告，包括农学家袁隆平、因疟疾治疗获诺奖的屠呦呦、火箭专家钱学森、核物理学家邓稼先等。举措 2026 年 8 月起自山东推开，并扩展至郑州、重庆等城市，尤其在国庆等节点，企业自愿腾出空间致敬科学成就、激励下一代。\n\n相关视频在印度等地引发讨论，有人对比本地公共传播，呼吁更重视创新而非商业喧嚣。", "url": "https://x.com/i/trending/2112810342728323293", "category": "News", "topics": ["News"], "updated_at": "2026-10-21T10:44:04.000Z"}, {"id": "2112161836116132305", "domain": "中国", "title_en": "China Restricts Tunnel Boring Machine Exports Targeting India's Projects", "title_zh": "中国限制全断面掘进机出口，印度基建承压", "hook_en": "India's metro and border tunnel builds now face new hurdles from China's export curbs on key machinery. Analysts see it as a direct hit amid ongoing tensions.", "hook_zh": "印度地铁与边境隧道建设因中国对关键机械出口设限再添障碍。分析认为在持续紧张背景下属直接冲击。", "summary_en": "China's commerce ministry imposed export licenses on full-face tunnel boring machines, cutterheads, and high-altitude shotcrete equipment, effective November 18, citing dual-use military risks. The controls target sensitive regions like India, which has relied on these imports for infrastructure despite dropping purchases from $18 million to $3 million yearly. India is countering with a $1.2 billion incentive for local production by firms like BEML and L&T, accelerating self-reliance in heavy machinery.", "summary_zh": "中国商务部对全断面隧道掘进机、刀盘及高原喷射混凝土设备实施出口许可，11 月 18 日起生效，理由为军民两用风险。管控针对印度等敏感地区；印度基建仍依赖此类进口，尽管年采购已从约 1800 万美元降至 300 万美元。印度正以约 12 亿美元激励推动 BEML、L&T 等本土生产，加速重型机械自力更生。", "body_en": "China Restricts Tunnel Boring Machine Exports Targeting India's Projects.\n\nIndia's metro and border tunnel builds now face new hurdles from China's export curbs on key machinery. Analysts see it as a direct hit amid ongoing tensions.\n\nChina's commerce ministry imposed export licenses on full-face tunnel boring machines, cutterheads, and high-altitude shotcrete equipment, effective November 18, citing dual-use military risks.\n\nThe controls target sensitive regions like India, which has relied on these imports for infrastructure despite dropping purchases from $18 million to $3 million yearly. India is countering with a $1.2 billion incentive for local production by firms like BEML and L&T, accelerating self-reliance in heavy machinery.", "body_zh": "中国限制全断面掘进机出口，印度基建承压。\n\n印度地铁与边境隧道建设因中国对关键机械出口设限再添障碍。分析认为在持续紧张背景下属直接冲击。\n\n中国商务部对全断面隧道掘进机、刀盘及高原喷射混凝土设备实施出口许可，11 月 18 日起生效，理由为军民两用风险。管控针对印度等敏感地区；印度基建仍依赖此类进口，尽管年采购已从约 1800 万美元降至 300 万美元。\n\n印度正以约 12 亿美元激励推动 BEML、L&T 等本土生产，加速重型机械自力更生。", "url": "https://x.com/i/trending/2112161836116132305", "category": "News", "topics": ["News", "Business & Finance"], "updated_at": "2026-10-20T19:24:59.000Z"}, {"id": "2112437946263474495", "domain": "中国", "title_en": "China Tracks U.S. Warship Near Disputed South China Sea Shoal", "title_zh": "中国对美舰接近争议南沙礁盘实施跟踪监视", "hook_en": "Early Tuesday, a U.S. littoral combat ship sailed into waters China calls its own near Xianbin Jiao, prompting Beijing to send forces for close monitoring.", "hook_zh": "周二早间，一艘美国濒海战斗舰驶入中国所称仙宾礁附近海域，北京随即派出力量实施抵近监视。", "summary_en": "China's PLA Navy accused the USS Charleston of illegally entering waters adjacent to Xianbin Jiao in the Spratly Islands on October 20, claiming it threatens sovereignty and regional stability. The Philippines countered that the ship stayed in international waters, requiring no permission, and referenced a 2016 arbitral ruling against China's claims. This follows a recent vessel collision near the same shoal and comes amid overlapping territorial assertions by multiple nations in the South China Sea.", "summary_zh": "中国人民解放军海军指控「查尔斯顿」号于 10 月 20 日非法进入南沙群岛仙宾礁邻近水域，称其威胁主权与地区稳定。菲律宾方面反驳称该舰停留在国际水域、无需许可，并援引 2016 年仲裁裁决否定中方主张。此事发生在同礁附近不久前的船只碰撞之后，也正值多国在南海提出重叠领土主张之际。", "body_en": "China Tracks U.S. Warship Near Disputed South China Sea Shoal.\n\nEarly Tuesday, a U.S. littoral combat ship sailed into waters China calls its own near Xianbin Jiao, prompting Beijing to send forces for close monitoring.\n\nChina's PLA Navy accused the USS Charleston of illegally entering waters adjacent to Xianbin Jiao in the Spratly Islands on October 20, claiming it threatens sovereignty and regional stability.\n\nThe Philippines countered that the ship stayed in international waters, requiring no permission, and referenced a 2016 arbitral ruling against China's claims. This follows a recent vessel collision near the same shoal and comes amid overlapping territorial assertions by multiple nations in the South China Sea.", "body_zh": "中国对美舰接近争议南沙礁盘实施跟踪监视。\n\n周二早间，一艘美国濒海战斗舰驶入中国所称仙宾礁附近海域，北京随即派出力量实施抵近监视。\n\n中国人民解放军海军指控「查尔斯顿」号于 10 月 20 日非法进入南沙群岛仙宾礁邻近水域，称其威胁主权与地区稳定。\n\n菲律宾方面反驳称该舰停留在国际水域、无需许可，并援引 2016 年仲裁裁决否定中方主张。此事发生在同礁附近不久前的船只碰撞之后，也正值多国在南海提出重叠领土主张之际。", "url": "https://x.com/i/trending/2112437946263474495", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-20T15:35:04.000Z"}, {"id": "2112579117904535807", "domain": "中国", "title_en": "Micron Funds New York Minerals Processing for AI Chip Supplies", "title_zh": "美光出资支持纽约关键矿物精炼，保障 AI 芯片原料", "hook_en": "Micron is stepping up to secure vital materials for its AI memory chips right at home in New York. The move aims to cut reliance on overseas sources amid surging demand.", "hook_zh": "美光加大在纽约本土保障 AI 存储芯片关键材料供应的力度，意在削减对海外来源的依赖，以应对需求激增。", "summary_en": "Micron Technology announced strategic funding for Indium Corporation to expand refining of critical minerals like indium at its Rome, New York facility, paired with a long-term supply agreement. This supports Micron's $3 billion U.S. semiconductor supply chain investment and addresses China's dominance in key materials production. Despite the positive step for national security and AI growth, shares dipped 2-3% that day amid concerns over AI spending, Taiwan strikes, and competition.", "summary_zh": "美光科技宣布向 Indium Corporation 提供战略性资金，扩大其纽约罗马工厂对铟等关键矿物的精炼，并配套长期供货协议。此举支撑美光约 30 亿美元的美国半导体供应链投资，也回应中国在关键材料生产中的主导地位。尽管对国家安全与 AI 增长属正面一步，当日股价仍因 AI 开支、台湾相关冲击与竞争等担忧下跌约 2%–3%。", "body_en": "Micron Funds New York Minerals Processing for AI Chip Supplies.\n\nMicron is stepping up to secure vital materials for its AI memory chips right at home in New York. The move aims to cut reliance on overseas sources amid surging demand.\n\nMicron Technology announced strategic funding for Indium Corporation to expand refining of critical minerals like indium at its Rome, New York facility, paired with a long-term supply agreement. This supports Micron's $3 billion U.S.\n\nsemiconductor supply chain investment and addresses China's dominance in key materials production. Despite the positive step for national security and AI growth, shares dipped 2-3% that day amid concerns over AI spending, Taiwan strikes, and competition.", "body_zh": "美光出资支持纽约关键矿物精炼，保障 AI 芯片原料。\n\n美光加大在纽约本土保障 AI 存储芯片关键材料供应的力度，意在削减对海外来源的依赖，以应对需求激增。\n\n美光科技宣布向 Indium Corporation 提供战略性资金，扩大其纽约罗马工厂对铟等关键矿物的精炼，并配套长期供货协议。\n\n此举支撑美光约 30 亿美元的美国半导体供应链投资，也回应中国在关键材料生产中的主导地位。尽管对国家安全与 AI 增长属正面一步，当日股价仍因 AI 开支、台湾相关冲击与竞争等担忧下跌约 2%–3%。", "url": "https://x.com/i/trending/2112579117904535807", "category": "News", "topics": ["Technology"], "updated_at": "2026-10-20T16:26:46.000Z"}, {"id": "2112336528253047290", "domain": "中国", "title_en": "Debate Heats Up Over Self-Driving Cars vs Manual Control", "title_zh": "自动驾驶与手控驾驶之争升温", "hook_en": "Fitness coach Jason Helmes shared his Boomer take: he loves gripping the wheel, blasting music, and decompressing on the road without screens.", "hook_zh": "健身教练 Jason Helmes 抛出「婴儿潮一代」式看法：他爱握方向盘、轰着音乐、在路上不看屏幕地放松。", "summary_en": "People are split on self-driving cars, with some cherishing the hands-on drive for its mental break, while others welcome the freedom for family chats, reading, or napping. Waymo is expanding its U.S. robotaxi fleet by ordering thousands of Chinese-made Zeekr vehicles from Geely, adding its sensors in Arizona for service in cities like Los Angeles and San Francisco—though lawmakers raise security and data concerns. Riders already praise perks like sipping coffee in a Tesla Cybercab or easing traffic stress, but many hold onto manual driving's simple joys, eyeing a mix for fun drives and routine trips.", "summary_zh": "公众对自动驾驶态度分裂：有人珍视亲手开车带来的精神放松，也有人欢迎腾出手来聊天、阅读或小憩。Waymo 正扩大美国 Robotaxi 车队，向吉利旗下极氪订购数千辆中国制造车辆，在亚利桑那加装传感器，服务洛杉矶、旧金山等城市——议员则提出安全与数据顾虑。乘客已赞赏在特斯拉 Cybercab 里喝咖啡、减轻拥堵压力等体验，但许多人仍留恋手控驾驶的简单乐趣，设想娱乐路段手开、通勤路段自动驾驶的组合。", "body_en": "Debate Heats Up Over Self-Driving Cars vs Manual Control.\n\nFitness coach Jason Helmes shared his Boomer take: he loves gripping the wheel, blasting music, and decompressing on the road without screens.\n\nPeople are split on self-driving cars, with some cherishing the hands-on drive for its mental break, while others welcome the freedom for family chats, reading, or napping. Waymo is expanding its U.S.\n\nrobotaxi fleet by ordering thousands of Chinese-made Zeekr vehicles from Geely, adding its sensors in Arizona for service in cities like Los Angeles and San Francisco—though lawmakers raise security and data concerns. Riders already praise perks like sipping coffee in a Tesla Cybercab or easing traffic stress, but many hold onto manual driving's simple joys, eyeing a mix for fun drives and routine trips.", "body_zh": "自动驾驶与手控驾驶之争升温。\n\n健身教练 Jason Helmes 抛出「婴儿潮一代」式看法：他爱握方向盘、轰着音乐、在路上不看屏幕地放松。\n\n公众对自动驾驶态度分裂：有人珍视亲手开车带来的精神放松，也有人欢迎腾出手来聊天、阅读或小憩。\n\nWaymo 正扩大美国 Robotaxi 车队，向吉利旗下极氪订购数千辆中国制造车辆，在亚利桑那加装传感器，服务洛杉矶、旧金山等城市——议员则提出安全与数据顾虑。乘客已赞赏在特斯拉 Cybercab 里喝咖啡、减轻拥堵压力等体验，但许多人仍留恋手控驾驶的简单乐趣，设想娱乐路段手开、通勤路段自动驾驶的组合。", "url": "https://x.com/i/trending/2112336528253047290", "category": "News", "topics": ["Technology", "Robotics"], "updated_at": "2026-10-20T00:20:46.000Z"}, {"id": "2112296384745631848", "domain": "国际", "title_en": "France Protests Spark Debate on Russian Interference Claims", "title_zh": "法国抗议潮引发「俄方干涉」说法之争", "hook_en": "Hundreds of thousands marched in France on October 17 over soaring living costs and cuts to education, only for the unrest to fuel sharp online arguments about hidden foreign hands.", "hook_zh": "10 月 17 日法国数十万人抗议生活成本飙升与教育削减，骚乱随后在网上激起「是否有外部黑手」的激烈争论。", "summary_en": "Demonstrations drew around 550,000 people nationwide, including 110,000 in Paris, starting with student demands before expanding to unions and turning violent with looting, arson, and over 1,200 arrests. Estonian MP Marko Mihkelson claimed Russia benefits from the chaos in France and Italy as part of a shadow war, while a satirical post by Wolfgang Richter mocked the idea of Putin paying protesters and called for speech curbs. Officials insist the unrest stems from domestic economic woes, with no evidence of Russian or Iranian organization, though both nations have amplified the violence in propaganda; online views split between those seeing Moscow's gain and critics dismissing it as scapegoating real policy failures.", "summary_zh": "全国约 55 万人上街，巴黎约 11 万，由学生诉求扩至工会，并演变为抢劫、纵火与逾 1200 人被捕。爱沙尼亚议员 Marko Mihkelson 称俄从法、意乱局获益，属影子战争；Wolfgang Richter 的讽刺帖则嘲讽「普京出钱抗议」说法并呼吁限制言论。官方坚持动因是国内经济困境，并无俄、伊组织证据，尽管两国宣传放大了暴力画面；网上有人强调莫斯科受益，也有人批评这是在替真正的政策失败找替罪羊。", "body_en": "France Protests Spark Debate on Russian Interference Claims.\n\nHundreds of thousands marched in France on October 17 over soaring living costs and cuts to education, only for the unrest to fuel sharp online arguments about hidden foreign hands.\n\nDemonstrations drew around 550,000 people nationwide, including 110,000 in Paris, starting with student demands before expanding to unions and turning violent with looting, arson, and over 1,200 arrests.\n\nEstonian MP Marko Mihkelson claimed Russia benefits from the chaos in France and Italy as part of a shadow war, while a satirical post by Wolfgang Richter mocked the idea of Putin paying protesters and called for speech curbs. Officials insist the unrest stems from domestic economic woes, with no evidence of Russian or Iranian organization, though both nations have amplified the violence in propaganda; online views split between those seeing Moscow's gain and critics dismissing it as scapegoating real policy failures.", "body_zh": "法国抗议潮引发「俄方干涉」说法之争。\n\n10 月 17 日法国数十万人抗议生活成本飙升与教育削减，骚乱随后在网上激起「是否有外部黑手」的激烈争论。\n\n全国约 55 万人上街，巴黎约 11 万，由学生诉求扩至工会，并演变为抢劫、纵火与逾 1200 人被捕。爱沙尼亚议员 Marko Mihkelson 称俄从法、意乱局获益，属影子战争；Wolfgang Richter 的讽刺帖则嘲讽「普京出钱抗议」说法并呼吁限制言论。\n\n官方坚持动因是国内经济困境，并无俄、伊组织证据，尽管两国宣传放大了暴力画面；网上有人强调莫斯科受益，也有人批评这是在替真正的政策失败找替罪羊。", "url": "https://x.com/i/trending/2112296384745631848", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T14:03:55.000Z"}, {"id": "2112302146825949613", "domain": "国际", "title_en": "Republican Lawmakers Criticize Trump Waiver of Russia Sanctions", "title_zh": "共和党议员批评特朗普豁免对俄制裁条款", "hook_en": "Congressman Max Miller, representing a district with thousands of Ukrainian Americans, called out the Trump administration for waiving sanctions meant to punish Russia over Ukraine.", "hook_zh": "选区有大量乌克兰裔选民的众议员马克斯·米勒，公开批评特朗普政府豁免本用于惩罚俄罗斯侵乌的制裁条款。", "summary_en": "Reps. Max Miller of Ohio and Jeff Hurd of Colorado sharply criticized the Trump administration's decision to waive key provisions of the bipartisan Lindsey O. Graham Sanctioning Russia and Iran Act of 2026, which Congress passed in September to cut Russia's war funding through tariffs and economic measures. Trump cited national interests like lowering U.S. energy prices and advancing peace talks, but the lawmakers argued it eases pressure on Moscow amid its ongoing attacks on Ukraine without real concessions. The move has sparked mixed reactions, with some praising the critics and others prioritizing domestic issues, highlighting GOP tensions over Ukraine support and energy costs ahead of midterms.", "summary_zh": "俄亥俄州众议员马克斯·米勒与科罗拉多州杰夫·赫德，尖锐批评特朗普政府豁免两党《2026 年林赛·格雷厄姆制裁俄罗斯与伊朗法》关键条款；该法于 9 月通过，拟以关税与经济手段削弱俄战争资金。特朗普以降低美国能源价格、推动和谈等「国家利益」为由，议员则认为在莫斯科未作实质让步、仍持续攻乌之际放松压力。反应分化：有人赞赏批评声音，有人更看重国内议题，凸显中期选举前共和党内在挺乌与能源成本上的张力。", "body_en": "Republican Lawmakers Criticize Trump Waiver of Russia Sanctions.\n\nCongressman Max Miller, representing a district with thousands of Ukrainian Americans, called out the Trump administration for waiving sanctions meant to punish Russia over Ukraine.\n\nReps. Max Miller of Ohio and Jeff Hurd of Colorado sharply criticized the Trump administration's decision to waive key provisions of the bipartisan Lindsey O. Graham Sanctioning Russia and Iran Act of 2026, which Congress passed in September to cut Russia's war funding through tariffs and economic measures.\n\nTrump cited national interests like lowering U.S. energy prices and advancing peace talks, but the lawmakers argued it eases pressure on Moscow amid its ongoing attacks on Ukraine without real concessions. The move has sparked mixed reactions, with some praising the critics and others prioritizing domestic issues, highlighting GOP tensions over Ukraine support and energy costs ahead of midterms.", "body_zh": "共和党议员批评特朗普豁免对俄制裁条款。\n\n选区有大量乌克兰裔选民的众议员马克斯·米勒，公开批评特朗普政府豁免本用于惩罚俄罗斯侵乌的制裁条款。\n\n俄亥俄州众议员马克斯·米勒与科罗拉多州杰夫·赫德，尖锐批评特朗普政府豁免两党《2026 年林赛·格雷厄姆制裁俄罗斯与伊朗法》关键条款；该法于 9 月通过，拟以关税与经济手段削弱俄战争资金。\n\n特朗普以降低美国能源价格、推动和谈等「国家利益」为由，议员则认为在莫斯科未作实质让步、仍持续攻乌之际放松压力。反应分化：有人赞赏批评声音，有人更看重国内议题，凸显中期选举前共和党内在挺乌与能源成本上的张力。", "url": "https://x.com/i/trending/2112302146825949613", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-19T22:08:39.000Z"}, {"id": "2112660061600309523", "domain": "国际", "title_en": "National Security Officials Quietly Prep States for Potential Midterm Interference", "title_zh": "美安全官员低调向多州通报中期选举风险", "hook_en": "A handful of U.S. national security veterans have spent months huddling with governors and lawmakers, mapping out responses to possible federal moves at polling places.", "hook_zh": "一小群国防部相关官员数月来悄然咨询约 10 个州的州长与议员，为投票站出现联邦部队等情景做准备。", "summary_en": "About 10 current and former Defense Department officials, some with experience countering authoritarianism abroad, have consulted with leaders in roughly 10 states on scenarios like federal troops or immigration agents at polls or fraud challenges. Speaking anonymously to avoid retaliation, they stress their nonpartisan work stems from concerns over federal overreach, targeting states with tight races that could decide Congress. The Washington Post report has drawn accusations of 'deep state' plotting from critics, while supporters see it as prudent election planning amid rising distrust between the Trump administration and parts of the security community.", "summary_zh": "约 10 名现任与前任官员，向两党选举官员与国会议员通报特朗普政府可能采取的行动，例如移民执法人员出现在投票站，或借舞弊指控试图否定结果。重点放在可能左右国会控制权的摇摆州；参与者称关切选举完整性，并因担心报复而匿名发声。反应尖锐对立：有人视之为必要预案，也有人质疑这群非选举产生人士的秘密角色，以及联邦与州权之间的紧张。", "body_en": "National Security Officials Quietly Prep States for Potential Midterm Interference.\n\nA handful of U.S. national security veterans have spent months huddling with governors and lawmakers, mapping out responses to possible federal moves at polling places.\n\nAbout 10 current and former Defense Department officials, some with experience countering authoritarianism abroad, have consulted with leaders in roughly 10 states on scenarios like federal troops or immigration agents at polls or fraud challenges.\n\nSpeaking anonymously to avoid retaliation, they stress their nonpartisan work stems from concerns over federal overreach, targeting states with tight races that could decide Congress. The Washington Post report has drawn accusations of 'deep state' plotting from critics, while supporters see it as prudent election planning amid rising distrust between the Trump administration and parts of the security community.", "body_zh": "美安全官员低调向多州通报中期选举风险。\n\n一小群国防部相关官员数月来悄然咨询约 10 个州的州长与议员，为投票站出现联邦部队等情景做准备。\n\n约 10 名现任与前任官员，向两党选举官员与国会议员通报特朗普政府可能采取的行动，例如移民执法人员出现在投票站，或借舞弊指控试图否定结果。\n\n重点放在可能左右国会控制权的摇摆州；参与者称关切选举完整性，并因担心报复而匿名发声。反应尖锐对立：有人视之为必要预案，也有人质疑这群非选举产生人士的秘密角色，以及联邦与州权之间的紧张。", "url": "https://x.com/i/trending/2112660061600309523", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T17:07:44.000Z"}, {"id": "2112460842902151394", "domain": "国际", "title_en": "Lawmakers Back Ukraine Aid Amid Online Backlash from Trump Supporters", "title_zh": "两党议员力挺援乌，遭特朗普支持者网上猛烈抨击", "hook_en": "U.S. lawmakers from both parties rallied behind Zelensky on calls about sanctions waivers and restricted weapons access, only to face fierce online accusations of treason from Trump backers pushing for peace talks with Russia.", "hook_zh": "美国两党议员就制裁豁免与武器受限与泽连斯基通话力挺，却遭主张对俄和谈的特朗普支持者网上痛批为「叛国」。", "summary_en": "Rep. Brad Schneider, a Democrat, joined a bipartisan call where Zelensky raised alarms over waived U.S. sanctions on Russia and limits on Starlink and Patriot missiles, urging steady defense support. Rep. Brian Fitzpatrick, a Republican, plans his own talk with Zelensky on Starshield, sanctions, and aid, promising probes into any restrictions. Critics online branded the lawmakers traitors for prioritizing Ukraine over Trump's negotiation push, calling the country corrupt and demanding an America First end to involvement. The clash highlights deep divides over U.S. policy shifts like energy deals with Russia and Starlink curbs.", "summary_zh": "民主党众议员布拉德·施奈德参加两党通话，泽连斯基对美豁免对俄制裁及限制星链、爱国者导弹表示警惕，敦促稳定防务支持。共和党众议员布赖恩·菲茨帕特里克计划另与泽连斯基谈星盾、制裁与援助，并承诺调查任何限制。网上批评者称议员「叛国」、优先乌克兰而非特朗普谈判路线，指乌腐败并要求「美国优先」结束介入。争执凸显能源交易、星链限制等政策转向下的深刻分裂。", "body_en": "Lawmakers Back Ukraine Aid Amid Online Backlash from Trump Supporters.\n\nU.S. lawmakers from both parties rallied behind Zelensky on calls about sanctions waivers and restricted weapons access, only to face fierce online accusations of treason from Trump backers pushing for peace talks with Russia.\n\nRep. Brad Schneider, a Democrat, joined a bipartisan call where Zelensky raised alarms over waived U.S. sanctions on Russia and limits on Starlink and Patriot missiles, urging steady defense support. Rep.\n\nBrian Fitzpatrick, a Republican, plans his own talk with Zelensky on Starshield, sanctions, and aid, promising probes into any restrictions. Critics online branded the lawmakers traitors for prioritizing Ukraine over Trump's negotiation push, calling the country corrupt and demanding an America First end to involvement. The clash highlights deep divides over U.S. policy shifts like energy deals with Russia and Starlink curbs.", "body_zh": "两党议员力挺援乌，遭特朗普支持者网上猛烈抨击。\n\n美国两党议员就制裁豁免与武器受限与泽连斯基通话力挺，却遭主张对俄和谈的特朗普支持者网上痛批为「叛国」。\n\n民主党众议员布拉德·施奈德参加两党通话，泽连斯基对美豁免对俄制裁及限制星链、爱国者导弹表示警惕，敦促稳定防务支持。共和党众议员布赖恩·菲茨帕特里克计划另与泽连斯基谈星盾、制裁与援助，并承诺调查任何限制。\n\n网上批评者称议员「叛国」、优先乌克兰而非特朗普谈判路线，指乌腐败并要求「美国优先」结束介入。争执凸显能源交易、星链限制等政策转向下的深刻分裂。", "url": "https://x.com/i/trending/2112460842902151394", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T08:32:59.000Z"}, {"id": "2112773061082767722", "domain": "国际", "title_en": "Merz Rejects Ukraine Surrender as Threat to All Europe", "title_zh": "美情报称普京下令加大对北约欧洲的破坏行动", "hook_en": "German Chancellor Friedrich Merz drew a firm line: Ukraine's surrender would mean Europe's own capitulation. He shared this view at the Berlin Global Dialogue, amid rising Russian sabotage fears.", "hook_zh": "今年 8 月一架装有爆炸物的无人机袭击德国莱比锡机场一架乌克兰货机但未起爆，被指属于更广泛隐蔽行动的一部分。", "summary_en": "Merz declared that any surrender by Ukraine to Russia is off the table, as it would surrender Europe's security too. His words followed U.S. intelligence reports of Putin ordering stepped-up sabotage against NATO nations, including a foiled drone attack on Leipzig-Halle Airport targeting a Ukrainian aid plane. A Kremlin back-channel warning hinted at more strikes to come, prompting Germany to boost security and consider NATO's Article 5 if casualties had occurred. Merz called Russia's hybrid operations and societal influence Germany's top concern, framing Ukraine aid as vital to protecting the post-1990 European order.", "summary_zh": "美方情报称，因乌克兰和谈停滞及基辅深远打击，普京直接下令显著加强对欧洲北约国家的破坏活动。莱比锡事件被指向经塞尔维亚运送爆炸物的俄军情报单位，目标涉及军援；克里姆林宫后据称通过后门警告德国还将有更多袭击。德国已将军事破坏威胁调至“显著”，并讨论若造成伤亡是否触及北约第五条。俄方否认，北约仍在评估应对。", "body_en": "Putin Ordered Sabotage Campaign Against NATO, U.S. Intel Assesses.\n\nA drone packed with explosives struck a cargo plane at Germany's Leipzig-Halle Airport in August, but mercifully failed to detonate. U.S. intelligence now pins it on a personal order from Putin to ramp up covert attacks on NATO nations.\n\nThe Wall Street Journal investigation reveals Russian President Vladimir Putin directed the GRU military intelligence unit to intensify sabotage against NATO countries, targeting military aid shipments to Ukraine, infrastructure, and shipping to weaken European support. The Leipzig plot involved three drones aimed at an Antonov aircraft; one hit but didn't explode, averting disaster.\n\nGerman Chancellor Friedrich Merz warned of Russia's societal threat, noting mass casualties there could have triggered NATO's Article 5. Berlin blamed Moscow publicly, raised sabotage alerts, while Russia denies involvement.", "body_zh": "美情报称普京下令加大对北约欧洲的破坏行动。\n\n今年 8 月一架装有爆炸物的无人机袭击德国莱比锡机场一架乌克兰货机但未起爆，被指属于更广泛隐蔽行动的一部分。\n\n美方情报称，因乌克兰和谈停滞及基辅深远打击，普京直接下令显著加强对欧洲北约国家的破坏活动。莱比锡事件被指向经塞尔维亚运送爆炸物的俄军情报单位，目标涉及军援；克里姆林宫后据称通过后门警告德国还将有更多袭击。\n\n德国已将军事破坏威胁调至“显著”，并讨论若造成伤亡是否触及北约第五条。俄方否认，北约仍在评估应对。", "url": "https://x.com/i/trending/2112773061082767722", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-21T17:08:27.000Z"}, {"id": "2112501506905710732", "domain": "国际", "title_en": "UK and Poland Rebuke US Defense Secretary Over Afghanistan Ally Claims", "title_zh": "英波就美防长阿富汗盟友言论提出严正回应", "hook_en": "Pete Hegseth recalled seeing dozens of flags in Kabul but claimed only a handful of nations truly fought alongside Americans. British and Polish leaders quickly pushed back, honoring the lives lost by their troops.", "hook_zh": "赫格塞思称喀布尔可见多国旗帜，但真正并肩作战者寥寥；英国与波兰领导人迅速反驳并缅怀本国阵亡者。", "summary_en": "During a speech at the University of Tennessee, US Defense Secretary Pete Hegseth said few NATO allies contributed meaningfully to combat in Afghanistan, joking that the ISAF patch meant 'I Saw Americans Fighting.' Downing Street responded firmly, noting 457 British deaths—the second-highest after the US—and thousands of families who sacrificed for collective security after the 2001 attacks. Poland's Foreign Minister Radosław Sikorski highlighted 44 Polish soldiers killed in Ghazni province, while records show over 1,100 non-US coalition deaths overall, underscoring the broad sacrifices in the 20-year conflict.", "summary_zh": "美防长 Pete Hegseth 在田纳西大学演讲称，鲜有北约盟友在阿富汗真正投入战斗，并调侃 ISAF 补丁意为“我看见美国人在打仗”。唐宁街强调英军阵亡 457 人，仅次于美国；波兰外长指出 44 名波军在加兹尼省牺牲。数据显示非美联军阵亡逾 1100 人。言论引发对盟友牺牲被低估的强烈不满。", "body_en": "UK and Poland Rebuke US Defense Secretary Over Afghanistan Ally Claims.\n\nPete Hegseth recalled seeing dozens of flags in Kabul but claimed only a handful of nations truly fought alongside Americans. British and Polish leaders quickly pushed back, honoring the lives lost by their troops.\n\nDuring a speech at the University of Tennessee, US Defense Secretary Pete Hegseth said few NATO allies contributed meaningfully to combat in Afghanistan, joking that the ISAF patch meant 'I Saw Americans Fighting.' Downing Street responded firmly, noting 457 British deaths—the second-highest after the US—and thousands of families who sacrificed for collective security after the 2001 attacks. Poland's Foreign Minister Radosław Sikorski highlighted 44 Polish soldiers killed in Ghazni province, while records show over 1,100 non-US coalition deaths overall, underscoring the broad sacrifices in the 20-year conflict.", "body_zh": "英波就美防长阿富汗盟友言论提出严正回应。\n\n赫格塞思称喀布尔可见多国旗帜，但真正并肩作战者寥寥；英国与波兰领导人迅速反驳并缅怀本国阵亡者。\n\n美防长 Pete Hegseth 在田纳西大学演讲称，鲜有北约盟友在阿富汗真正投入战斗，并调侃 ISAF 补丁意为“我看见美国人在打仗”。唐宁街强调英军阵亡 457 人，仅次于美国；波兰外长指出 44 名波军在加兹尼省牺牲。\n\n数据显示非美联军阵亡逾 1100 人。言论引发对盟友牺牲被低估的强烈不满。", "url": "https://x.com/i/trending/2112501506905710732", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T14:10:22.000Z"}, {"id": "2112533926879125584", "domain": "国际", "title_en": "Zelenskyy Warns of Russia's Propaganda Push Across Europe", "title_zh": "泽连斯基警告俄罗斯在欧洲的宣传攻势", "hook_en": "In a candid interview, Ukraine's president laid out Russia's quiet strategy to sway opinions through media and social platforms.", "hook_zh": "乌克兰总统在采访中勾勒俄罗斯通过媒体与社交平台悄然影响舆论的策略。", "summary_en": "Volodymyr Zelenskyy described Russia's decades-long hybrid war as heavily funded efforts targeting media, internet, and social platforms in countries like Italy, France, Britain, and Germany. He highlighted exploitation of issues such as migration, religion, far-right movements, and gender to influence public opinion. Social media responses pointed to Britain's £25 billion in aid to Ukraine—including £16 billion in weapons—and framed dissent as legitimate debate over spending rather than manipulation. The exchange underscores tensions between hybrid threat warnings and fatigue over war aid costs.", "summary_zh": "泽连斯基称俄罗斯数十年混合战投入大量资金，针对意大利、法国、英国、德国等国的媒体、互联网与社交平台，并利用移民、宗教、极右与性别等议题影响民意。社交平台回应中有人指出英国对乌援助约 250 亿英镑（含约 160 亿武器），并将异议视为对开支的正当辩论而非被操纵。交流凸显混合威胁警示与战争援助疲劳之间的张力。", "body_en": "Zelenskyy Warns of Russia's Propaganda Push Across Europe.\n\nIn a candid interview, Ukraine's president laid out Russia's quiet strategy to sway opinions through media and social platforms.\n\nVolodymyr Zelenskyy described Russia's decades-long hybrid war as heavily funded efforts targeting media, internet, and social platforms in countries like Italy, France, Britain, and Germany. He highlighted exploitation of issues such as migration, religion, far-right movements, and gender to influence public opinion.\n\nSocial media responses pointed to Britain's £25 billion in aid to Ukraine—including £16 billion in weapons—and framed dissent as legitimate debate over spending rather than manipulation. The exchange underscores tensions between hybrid threat warnings and fatigue over war aid costs.", "body_zh": "泽连斯基警告俄罗斯在欧洲的宣传攻势。\n\n乌克兰总统在采访中勾勒俄罗斯通过媒体与社交平台悄然影响舆论的策略。\n\n泽连斯基称俄罗斯数十年混合战投入大量资金，针对意大利、法国、英国、德国等国的媒体、互联网与社交平台，并利用移民、宗教、极右与性别等议题影响民意。\n\n社交平台回应中有人指出英国对乌援助约 250 亿英镑（含约 160 亿武器），并将异议视为对开支的正当辩论而非被操纵。交流凸显混合威胁警示与战争援助疲劳之间的张力。", "url": "https://x.com/i/trending/2112533926879125584", "category": "News", "topics": ["News", "Politics"], "updated_at": "2026-10-20T13:26:36.000Z"}, {"id": "2112749239679820040", "domain": "国际", "title_en": "CNN Reports Intense Internal Struggles in Trump's White House Ahead of Midterms", "title_zh": "CNN：中期选举前特朗普白宫内斗激烈", "hook_en": "A Trump ally described the White House atmosphere as brutally distrustful, saying 'You can't trust anybody here' amid fears of midterm losses.", "hook_zh": "一名特朗普盟友形容白宫氛围极度缺乏信任，称「这里谁都不能信」，并担忧中期选举失利。", "summary_en": "A CNN report cites administration officials and allies detailing power jockeying, blame-shifting, and toxicity inside the White House as Republicans brace for November's midterms. Recent signs include Kimberly Guilfoyle's ouster as ambassador to Greece and probes into disputes over Kennedy Center funding involving Alina Habba Mildon and Ric Grenell. White House spokesman Davis Ingle dismissed the claims as baseless speculation, insisting Trump stays focused on securing congressional majorities. Other outlets like The Washington Post echo themes of aides positioning for post-election roles.", "summary_zh": "CNN 援引政府官员与盟友，描述共和党备战 11 月中期之际白宫内权力争斗、甩锅与紧张气氛。近期迹象包括金伯利·吉尔福伊勒被免去驻希腊大使，以及围绕肯尼迪中心资金、牵涉阿丽娜·哈巴·米尔登与里克·格内尔的争议调查。白宫发言人戴维斯·英格尔称相关说法为无根据猜测，并称特朗普专注于保住国会多数。《华盛顿邮报》等亦提到助手们为选后角色卡位。", "body_en": "CNN Reports Intense Internal Struggles in Trump's White House Ahead of Midterms.\n\nA Trump ally described the White House atmosphere as brutally distrustful, saying 'You can't trust anybody here' amid fears of midterm losses.\n\nA CNN report cites administration officials and allies detailing power jockeying, blame-shifting, and toxicity inside the White House as Republicans brace for November's midterms. Recent signs include Kimberly Guilfoyle's ouster as ambassador to Greece and probes into disputes over Kennedy Center funding involving Alina Habba Mildon and Ric Grenell.\n\nWhite House spokesman Davis Ingle dismissed the claims as baseless speculation, insisting Trump stays focused on securing congressional majorities. Other outlets like The Washington Post echo themes of aides positioning for post-election roles.", "body_zh": "CNN：中期选举前特朗普白宫内斗激烈。\n\n一名特朗普盟友形容白宫氛围极度缺乏信任，称「这里谁都不能信」，并担忧中期选举失利。\n\nCNN 援引政府官员与盟友，描述共和党备战 11 月中期之际白宫内权力争斗、甩锅与紧张气氛。近期迹象包括金伯利·吉尔福伊勒被免去驻希腊大使，以及围绕肯尼迪中心资金、牵涉阿丽娜·哈巴·米尔登与里克·格内尔的争议调查。\n\n白宫发言人戴维斯·英格尔称相关说法为无根据猜测，并称特朗普专注于保住国会多数。《华盛顿邮报》等亦提到助手们为选后角色卡位。", "url": "https://x.com/i/trending/2112749239679820040", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T03:38:52.000Z"}, {"id": "2112384299999850805", "domain": "国际", "title_en": "Trump Warns of NATO Exit, Cites France at Kansas Rally", "title_zh": "特朗普在堪萨斯集会警告或退出北约", "hook_en": "Thousands packed an arena in Park City, Kansas, cheering as President Trump warned that Europe’s troubles could force America to pull back from NATO.", "hook_zh": "数万人聚集堪萨斯帕克城会场，特朗普总统警告欧洲乱局可能迫使美国从北约后退。", "summary_en": "At a rally supporting Sen. Roger Marshall ahead of the November 3 midterms, Trump described France as a once-great nation overwhelmed by migrants, jihadists, and communists, urging stronger U.S. borders to avoid a similar fate. He criticized heavy U.S. spending on NATO and Ukraine aid, saying allies must step up or face withdrawal, and expressed willingness for direct talks with Putin and Xi to end the Ukraine conflict. Protesters briefly interrupted but were quickly drowned out by the supportive crowd, as Trump pushed America First priorities alongside pledges for farmers and the economy.", "summary_zh": "在为参议员罗杰·马歇尔助选、迎接 11 月 3 日中期选举的集会上，特朗普称法国曾是伟大国家，如今被移民、圣战分子与共产主义者淹没，并敦促加强美国边境以免重蹈覆辙。他批评美国在北约与援乌上支出过高，称盟友必须加码否则可能面临美方退出，并表示愿与普京、习近平直接会谈以结束乌克兰冲突。抗议者短暂打断，但被支持者声浪盖过；他同时推销「美国优先」及对农民与经济的承诺。", "body_en": "Trump Warns of NATO Exit, Cites France at Kansas Rally.\n\nThousands packed an arena in Park City, Kansas, cheering as President Trump warned that Europe’s troubles could force America to pull back from NATO.\n\nAt a rally supporting Sen. Roger Marshall ahead of the November 3 midterms, Trump described France as a once-great nation overwhelmed by migrants, jihadists, and communists, urging stronger U.S. borders to avoid a similar fate.\n\nHe criticized heavy U.S. spending on NATO and Ukraine aid, saying allies must step up or face withdrawal, and expressed willingness for direct talks with Putin and Xi to end the Ukraine conflict. Protesters briefly interrupted but were quickly drowned out by the supportive crowd, as Trump pushed America First priorities alongside pledges for farmers and the economy.", "body_zh": "特朗普在堪萨斯集会警告或退出北约。\n\n数万人聚集堪萨斯帕克城会场，特朗普总统警告欧洲乱局可能迫使美国从北约后退。\n\n在为参议员罗杰·马歇尔助选、迎接 11 月 3 日中期选举的集会上，特朗普称法国曾是伟大国家，如今被移民、圣战分子与共产主义者淹没，并敦促加强美国边境以免重蹈覆辙。\n\n他批评美国在北约与援乌上支出过高，称盟友必须加码否则可能面临美方退出，并表示愿与普京、习近平直接会谈以结束乌克兰冲突。抗议者短暂打断，但被支持者声浪盖过；他同时推销「美国优先」及对农民与经济的承诺。", "url": "https://x.com/i/trending/2112384299999850805", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T21:20:55.000Z"}, {"id": "2111568548271440224", "domain": "国际", "title_en": "Putin Proposes Trump-Xi Summit to End Ukraine War, Excluding Zelenskyy", "title_zh": "普京提议特朗普—习近平三方峰会谈乌克兰，排除泽连斯基", "hook_en": "Vladimir Putin reached out to Donald Trump with a bold idea: a three-way summit with Xi Jinping to halt the Ukraine war, leaving Zelenskyy on the outside.", "hook_zh": "弗拉基米尔·普京向唐纳德·特朗普抛出大胆构想：与习近平举行三方峰会以停止乌克兰战争，把泽连斯基排除在外。", "summary_en": "The proposal came from an October 9 phone call between Putin and Trump, which also led to a deal for U.S. purchases of Russian diesel fuel. Trump expressed openness, criticizing Zelenskyy for prolonging the conflict amid heavy funding from Europe and past U.S. aid, while noting Ukrainian strikes on Russian refineries hurt global energy and American interests. Supporters see it as a path to peace; critics, including Ukrainian officials and experts like Michael McFaul, warn it rewards aggression and sidelines Kyiv. The potential meeting could happen at the APEC summit in Shenzhen next month.", "summary_zh": "提议源自 10 月 9 日普京与特朗普通话，同一次通话还促成美方采购俄柴油的交易。特朗普表示开放，批评泽连斯基在欧洲与过去美援大量投入背景下拖延冲突，并称乌方打击俄炼油厂损害全球能源与美国利益。支持者视其为和平路径；批评者包括乌克兰官员与迈克尔·麦克福尔等专家，警告这会奖励侵略并边缘化基辅。潜在会面或于下月深圳 APEC 峰会期间举行。", "body_en": "Putin Proposes Trump-Xi Summit to End Ukraine War, Excluding Zelenskyy.\n\nVladimir Putin reached out to Donald Trump with a bold idea: a three-way summit with Xi Jinping to halt the Ukraine war, leaving Zelenskyy on the outside.\n\nThe proposal came from an October 9 phone call between Putin and Trump, which also led to a deal for U.S. purchases of Russian diesel fuel. Trump expressed openness, criticizing Zelenskyy for prolonging the conflict amid heavy funding from Europe and past U.S.\n\naid, while noting Ukrainian strikes on Russian refineries hurt global energy and American interests. Supporters see it as a path to peace; critics, including Ukrainian officials and experts like Michael McFaul, warn it rewards aggression and sidelines Kyiv. The potential meeting could happen at the APEC summit in Shenzhen next month.", "body_zh": "普京提议特朗普—习近平三方峰会谈乌克兰，排除泽连斯基。\n\n弗拉基米尔·普京向唐纳德·特朗普抛出大胆构想：与习近平举行三方峰会以停止乌克兰战争，把泽连斯基排除在外。\n\n提议源自 10 月 9 日普京与特朗普通话，同一次通话还促成美方采购俄柴油的交易。特朗普表示开放，批评泽连斯基在欧洲与过去美援大量投入背景下拖延冲突，并称乌方打击俄炼油厂损害全球能源与美国利益。\n\n支持者视其为和平路径；批评者包括乌克兰官员与迈克尔·麦克福尔等专家，警告这会奖励侵略并边缘化基辅。潜在会面或于下月深圳 APEC 峰会期间举行。", "url": "https://x.com/i/trending/2111568548271440224", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-19T19:30:26.000Z"}, {"id": "2112893265104007427", "domain": "国际", "title_en": "Thread Reveals Groups Planning Responses to Potential Federal Actions Before Midterms", "title_zh": "帖文曝光组织在中期选举前讨论应对联邦行动", "hook_en": "A detailed X thread uncovered audio and video from democracy groups discussing when the federal government might cross into illegitimacy, raising eyebrows just before the November midterms.", "hook_zh": "一篇详尽的 X 帖文披露民主团体讨论联邦政府何时可能「越界」的音视频，临近 11 月中期选举引发关注。", "summary_en": "X user DataRepublican, real name Jennica Pounds, shared materials from the Renew to Thrive group and the United Democracy Alliance, which links with NGOs like Indivisible. The recordings outline 'redlines' such as invoking the Insurrection Act against peaceful protesters, with governors potentially refusing federal troops and networks stepping in. This coincides with a Washington Post report on current and former Pentagon officials advising 10 states on resisting possible federal moves near polling places. Reactions split between calls for investigation and defenses of the work as protecting elections, though the materials await independent verification.", "summary_zh": "X 用户 DataRepublican（真名 Jennica Pounds）分享了 Renew to Thrive 团体与联合民主联盟（关联 Indivisible 等 NGO）的材料。录音勾勒「红线」场景，例如对和平抗议者动用《叛乱法》，州长或拒绝联邦部队、网络介入响应。同期《华盛顿邮报》报道现任与前任五角大楼官员正为约 10 个州提供建议，以防范投票点附近可能的联邦举动。舆论分裂为要求调查与辩称属保卫选举，材料尚待独立核实。", "body_en": "Thread Reveals Groups Planning Responses to Potential Federal Actions Before Midterms.\n\nA detailed X thread uncovered audio and video from democracy groups discussing when the federal government might cross into illegitimacy, raising eyebrows just before the November midterms.\n\nX user DataRepublican, real name Jennica Pounds, shared materials from the Renew to Thrive group and the United Democracy Alliance, which links with NGOs like Indivisible. The recordings outline 'redlines' such as invoking the Insurrection Act against peaceful protesters, with governors potentially refusing federal troops and networks stepping in.\n\nThis coincides with a Washington Post report on current and former Pentagon officials advising 10 states on resisting possible federal moves near polling places. Reactions split between calls for investigation and defenses of the work as protecting elections, though the materials await independent verification.", "body_zh": "帖文曝光组织在中期选举前讨论应对联邦行动。\n\n一篇详尽的 X 帖文披露民主团体讨论联邦政府何时可能「越界」的音视频，临近 11 月中期选举引发关注。\n\nX 用户 DataRepublican（真名 Jennica Pounds）分享了 Renew to Thrive 团体与联合民主联盟（关联 Indivisible 等 NGO）的材料。录音勾勒「红线」场景，例如对和平抗议者动用《叛乱法》，州长或拒绝联邦部队、网络介入响应。\n\n同期《华盛顿邮报》报道现任与前任五角大楼官员正为约 10 个州提供建议，以防范投票点附近可能的联邦举动。舆论分裂为要求调查与辩称属保卫选举，材料尚待独立核实。", "url": "https://x.com/i/trending/2112893265104007427", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T17:32:37.000Z"}, {"id": "2112592169139855608", "domain": "国际", "title_en": "Hungary Blocks Ukraine and Moldova EU Accession Steps", "title_zh": "匈牙利阻挠乌克兰与摩尔多瓦入盟谈判下一步", "hook_en": "Just days after Ukraine passed a law protecting its Hungarian-speaking minority, Hungary halted the next phase of EU talks for both Ukraine and Moldova, leaving diplomats puzzled by the silence.", "hook_zh": "乌克兰刚通过保护匈裔少数群体的法律数日，匈牙利却叫停乌、摩两国欧盟谈判下一阶段，外交官对沉默感到困惑。", "summary_en": "At a meeting of EU technical experts on October 20, Hungary objected to advancing the final two negotiating clusters on green agenda, sustainable connectivity, resources, agriculture, and cohesion, while the other 26 member states supported the move. This follows recent progress, including Ukraine's minority protections law on October 12 and a meeting between Prime Minister Péter Magyar and President Volodymyr Zelenskyy to reset ties, which allowed earlier clusters to open. The block revives questions about Hungary's stance on EU enlargement, as unanimity is required, and observers note frustration over the unexplained decision despite outreach efforts.", "summary_zh": "10 月 20 日欧盟技术专家会上，匈牙利反对推进绿色议程、可持续联通、资源、农业与凝聚等最后两个谈判集群，其余 26 国支持。此前乌克兰 10 月 12 日通过少数群体保护法，总理 Péter Magyar 与泽连斯基会面试图重置关系，曾使更早集群得以开启。因入盟需全体一致，此次阻拦再次引发对匈牙利扩盟立场的质疑；观察人士指出，尽管已有沟通，决定仍未说明理由，各方感到沮丧。", "body_en": "Hungary Blocks Ukraine and Moldova EU Accession Steps.\n\nJust days after Ukraine passed a law protecting its Hungarian-speaking minority, Hungary halted the next phase of EU talks for both Ukraine and Moldova, leaving diplomats puzzled by the silence.\n\nAt a meeting of EU technical experts on October 20, Hungary objected to advancing the final two negotiating clusters on green agenda, sustainable connectivity, resources, agriculture, and cohesion, while the other 26 member states supported the move.\n\nThis follows recent progress, including Ukraine's minority protections law on October 12 and a meeting between Prime Minister Péter Magyar and President Volodymyr Zelenskyy to reset ties, which allowed earlier clusters to open. The block revives questions about Hungary's stance on EU enlargement, as unanimity is required, and observers note frustration over the unexplained decision despite outreach efforts.", "body_zh": "匈牙利阻挠乌克兰与摩尔多瓦入盟谈判下一步。\n\n乌克兰刚通过保护匈裔少数群体的法律数日，匈牙利却叫停乌、摩两国欧盟谈判下一阶段，外交官对沉默感到困惑。\n\n10 月 20 日欧盟技术专家会上，匈牙利反对推进绿色议程、可持续联通、资源、农业与凝聚等最后两个谈判集群，其余 26 国支持。\n\n此前乌克兰 10 月 12 日通过少数群体保护法，总理 Péter Magyar 与泽连斯基会面试图重置关系，曾使更早集群得以开启。因入盟需全体一致，此次阻拦再次引发对匈牙利扩盟立场的质疑；观察人士指出，尽管已有沟通，决定仍未说明理由，各方感到沮丧。", "url": "https://x.com/i/trending/2112592169139855608", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-20T17:18:54.000Z"}, {"id": "2112964655136354409", "domain": "国际", "title_en": "Poland Halts Ukraine Aid Over Lviv's Nationalist Figures Resolution", "title_zh": "因利沃夫纪念二战民族主义人物决议，波兰暂停对乌援助", "hook_en": "A regional council in Lviv declared 2027 a year to honor WWII nationalist leaders, just as Poland prepared a major aid shipment to Ukraine.", "hook_zh": "利沃夫地区议会宣布 2027 年为纪念二战民族主义领袖之年，正值波兰准备向乌克兰运送大批援助。", "summary_en": "The Lviv Regional Council voted on October 20 to commemorate Ukrainian Insurgent Army commander Roman Shukhevych and poet Oleh Olzhych, figures tied to Ukraine's independence struggle but also implicated in wartime mass killings of Poles, Jews, and others. Polish leaders, including Prime Minister Donald Tusk who called it unwise and harmful to Ukraine's EU path, responded by halting the aid package and banning the resolution's author from Poland and the Schengen area. Ukraine's Foreign Ministry distanced itself from the vote, urging dialogue to preserve wartime cooperation, as both nations work through back channels amid historical tensions.", "summary_zh": "利沃夫州议会 10 月 20 日表决纪念乌克兰起义军指挥官罗曼·舒赫维奇与诗人奥列赫·奥利日奇——二人既与独立斗争相关，也被指卷入战时对波兰人、犹太人等的屠杀。波兰总理图斯克等称此举不明智且有损乌克兰入欧路径，随即叫停援助包，并禁止决议推动者进入波兰与申根区。乌克兰外交部与表决保持距离，呼吁对话以维护战时合作；双方正通过幕后渠道处理历史张力。", "body_en": "Poland Halts Ukraine Aid Over Lviv's Nationalist Figures Resolution.\n\nA regional council in Lviv declared 2027 a year to honor WWII nationalist leaders, just as Poland prepared a major aid shipment to Ukraine.\n\nThe Lviv Regional Council voted on October 20 to commemorate Ukrainian Insurgent Army commander Roman Shukhevych and poet Oleh Olzhych, figures tied to Ukraine's independence struggle but also implicated in wartime mass killings of Poles, Jews, and others.\n\nPolish leaders, including Prime Minister Donald Tusk who called it unwise and harmful to Ukraine's EU path, responded by halting the aid package and banning the resolution's author from Poland and the Schengen area. Ukraine's Foreign Ministry distanced itself from the vote, urging dialogue to preserve wartime cooperation, as both nations work through back channels amid historical tensions.", "body_zh": "因利沃夫纪念二战民族主义人物决议，波兰暂停对乌援助。\n\n利沃夫地区议会宣布 2027 年为纪念二战民族主义领袖之年，正值波兰准备向乌克兰运送大批援助。\n\n利沃夫州议会 10 月 20 日表决纪念乌克兰起义军指挥官罗曼·舒赫维奇与诗人奥列赫·奥利日奇——二人既与独立斗争相关，也被指卷入战时对波兰人、犹太人等的屠杀。\n\n波兰总理图斯克等称此举不明智且有损乌克兰入欧路径，随即叫停援助包，并禁止决议推动者进入波兰与申根区。乌克兰外交部与表决保持距离，呼吁对话以维护战时合作；双方正通过幕后渠道处理历史张力。", "url": "https://x.com/i/trending/2112964655136354409", "category": "News", "topics": ["Politics"], "updated_at": "2026-10-21T17:57:58.000Z"}, {"id": "2112637280108335380", "domain": "体育", "title_en": "NFL Umpire Larry Smith Tears Quadriceps in Rare Non-Contact Injury at Wembley", "title_zh": "NFL 裁判拉里·史密斯温布利湿草滑倒撕裂股四头肌", "hook_en": "Larry Smith slipped on wet grass between plays, stood briefly, then collapsed clutching his leg—a shocking moment that sidelined the umpire for good this season.", "hook_zh": "拉里·史密斯在死球间隙湿草上滑倒，短暂站起后又捂腿倒下——这一幕令他本赛季提前告别。", "summary_en": "During the Houston Texans-Jacksonville Jaguars game at Wembley Stadium, second-year NFL umpire Larry Smith tore his right quadriceps in a non-contact slip early in the first quarter. Trainers from both teams helped him off the field on a cart, and his crew finished with six officials while splitting his duties. A middle school principal from Kansas City, Kansas, in his full-time job, Smith won't return until 2027, prompting the NFL to seek a replacement like swing official Tab Slaughter or Ian Malepeai for referee Shawn Hochuli’s crew. Veteran line judge Carl Johnson knelt by his side, hat off in what looked like a prayer, as fans shared surprised laughs about refs joining the injury list.", "summary_zh": "休斯顿德州人队对阵杰克逊维尔美洲虎队的温布利比赛中，入行第二年的 NFL 裁判拉里·史密斯在第一节早段非对抗滑倒，右股四头肌撕裂。双方训练人员用球车将其抬离，执法组以六人完赛并分摊其职责。史密斯全职是堪萨斯城一名中学校长，预计要到 2027 年才能复出；联盟将为裁判肖恩·霍楚利组寻找替补，如轮换裁判 Tab Slaughter 或 Ian Malepeai。资深边线裁判卡尔·约翰逊跪其身旁、脱帽似在祈祷；球迷则半开玩笑「连裁判也进伤病名单了」。", "body_en": "NFL Umpire Larry Smith Tears Quadriceps in Rare Non-Contact Injury at Wembley.\n\nLarry Smith slipped on wet grass between plays, stood briefly, then collapsed clutching his leg—a shocking moment that sidelined the umpire for good this season.\n\nDuring the Houston Texans-Jacksonville Jaguars game at Wembley Stadium, second-year NFL umpire Larry Smith tore his right quadriceps in a non-contact slip early in the first quarter. Trainers from both teams helped him off the field on a cart, and his crew finished with six officials while splitting his duties.\n\nA middle school principal from Kansas City, Kansas, in his full-time job, Smith won't return until 2027, prompting the NFL to seek a replacement like swing official Tab Slaughter or Ian Malepeai for referee Shawn Hochuli’s crew. Veteran line judge Carl Johnson knelt by his side, hat off in what looked like a prayer, as fans shared surprised laughs about refs joining the injury list.", "body_zh": "NFL 裁判拉里·史密斯温布利湿草滑倒撕裂股四头肌。\n\n拉里·史密斯在死球间隙湿草上滑倒，短暂站起后又捂腿倒下——这一幕令他本赛季提前告别。\n\n休斯顿德州人队对阵杰克逊维尔美洲虎队的温布利比赛中，入行第二年的 NFL 裁判拉里·史密斯在第一节早段非对抗滑倒，右股四头肌撕裂。双方训练人员用球车将其抬离，执法组以六人完赛并分摊其职责。\n\n史密斯全职是堪萨斯城一名中学校长，预计要到 2027 年才能复出；联盟将为裁判肖恩·霍楚利组寻找替补，如轮换裁判 Tab Slaughter 或 Ian Malepeai。资深边线裁判卡尔·约翰逊跪其身旁、脱帽似在祈祷；球迷则半开玩笑「连裁判也进伤病名单了」。", "url": "https://x.com/i/trending/2112637280108335380", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-20T20:16:29.000Z"}, {"id": "2112363184577191956", "domain": "体育", "title_en": "NFL Pushes Ahead with Paris Game Amid French Protests", "title_zh": "巴黎动荡中 NFL 仍推进法国首场常规赛", "hook_en": "As riots flare across parts of France, the NFL stays committed to its first regular-season game in Paris, with Steelers linebacker TJ Watt's wife openly questioning the call.", "hook_zh": "巴黎因生活成本与公共服务爆发骚乱，NFL 仍坚持法兰西体育场历史性比赛。钢人球星 T.J. 瓦特妻子发帖质问「这怎么说得通」。", "summary_en": "The Pittsburgh Steelers face the New Orleans Saints this Sunday at Stade de France in Saint-Denis, a key step in the league's international push, despite weeks of protests over school conditions and living costs that turned violent with fires, looting, and over 1,000 arrests. Commissioner Roger Goodell insists the matchup is safe, with protests mostly peaceful and the stadium outside central hotspots, while the league ramps up security in coordination with French authorities and the U.S. State Department. Fans mix excitement with worry, as Dani Watt posted on Instagram, 'Tell me how this makes sense???', but executives confirm no plans to cancel the historic event.", "summary_zh": "匹兹堡钢人与新奥尔良圣徒定于 10 月 25 日在圣但尼法兰西体育场进行 NFL 法国首场常规赛，尽管 10 月 17–18 日暴力抗议导致逮捕、纵火与宵禁。包括罗杰·古德尔在内的联盟官员称动荡「大体和平」，并与地方警察、国家当局及美国国务院加强安保，暂无延期计划。圣徒已抵达、钢人在途，高管强调安全优先，部分球员家属仍表担忧。", "body_en": "NFL Pushes Ahead with First France Game Amid Paris Unrest.\n\nAs riots rage in Paris over rising costs and public services, the NFL stands firm on its historic game at Stade de France. Steelers star T.J. Watt's wife posted a headline questioning the decision with 'Tell me how this one make sense???'.\n\nThe Pittsburgh Steelers and New Orleans Saints are set to play the NFL's first regular-season game in France on October 25 at Stade de France in Saint-Denis, despite violent protests that erupted October 17-18, leading to arrests, fires, and curfews. League officials, including Roger Goodell, call the unrest 'mostly peaceful' and have ramped up security with local police, national authorities, and the U.S.\n\nState Department, confirming no plans to postpone. The Saints have arrived, Steelers are en route, and executives like Peter O’Reilly stress safety as the top priority, even as some players' families voice concerns.", "body_zh": "巴黎动荡中 NFL 仍推进法国首场常规赛。\n\n巴黎因生活成本与公共服务爆发骚乱，NFL 仍坚持法兰西体育场历史性比赛。钢人球星 T.J. 瓦特妻子发帖质问「这怎么说得通」。\n\n匹兹堡钢人与新奥尔良圣徒定于 10 月 25 日在圣但尼法兰西体育场进行 NFL 法国首场常规赛，尽管 10 月 17–18 日暴力抗议导致逮捕、纵火与宵禁。包括罗杰·古德尔在内的联盟官员称动荡「大体和平」，并与地方警察、国家当局及美国国务院加强安保，暂无延期计划。\n\n圣徒已抵达、钢人在途，高管强调安全优先，部分球员家属仍表担忧。", "url": "https://x.com/i/trending/2112363184577191956", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-21T16:57:57.000Z"}, {"id": "2112695496611692714", "domain": "体育", "title_en": "Knicks Raise Banner and Rings in Title Celebration, Fall to Sixers on Opening Night", "title_zh": "尼克斯升冠军旗帜发钻戒，揭幕战却负于76人", "hook_en": "After 53 years, Knicks players slipped on diamond-studded rings as their 2025-26 championship banner rose to the rafters amid roaring fans at Madison Square Garden.", "hook_zh": "时隔 53 年，尼克斯球员戴上镶钻冠军戒指，2025-26 赛季总冠军旗帜在麦迪逊广场花园升上天花板，现场轰鸣。", "summary_en": "The New York Knicks marked their first NBA title in over five decades with a pregame ceremony on Tuesday, unveiling a 'World Champions' banner next to their 1970 and 1973 honors and distributing rings featuring nearly 800 diamonds, sapphires, and a twist mechanism revealing a mini Madison Square Garden. Fans received 'Champions Night' shirts, and the team donned white-and-gold uniforms, but Philadelphia spoiled the evening with a 106-100 win led by Tyrese Maxey's 28 points, LeBron James' 14 points, nine rebounds and seven assists in his Sixers debut, and Jaylen Brown's 19 points. LeBron traded words with courtside Knicks fans, quipping 'Ain’t nothing soft in the Midwest' before noting his Ohio roots, while the loss underscored the challenges of defending the title in a competitive East.", "summary_zh": "纽约尼克斯在周二赛前仪式上庆祝五十余年来首座 NBA 总冠军，将「世界冠军」旗帜挂在 1970、1973 年荣誉旁，并发放近 800 颗钻石与蓝宝石、可旋开露出迷你花园球场的戒指。球迷获「冠军之夜」衫，球队穿白金配色球衣，但费城以 106-100 扫兴：Tyrese Maxey 28 分，勒布朗·詹姆斯首秀 14 分 9 篮板 7 助攻，Jaylen Brown 19 分。勒布朗与场边尼克斯球迷互呛，调侃「中西部可不软」，并强调俄亥俄出身；失利凸显东区卫冕难度。", "body_en": "Knicks Raise Banner and Rings in Title Celebration, Fall to Sixers on Opening Night.\n\nAfter 53 years, Knicks players slipped on diamond-studded rings as their 2025-26 championship banner rose to the rafters amid roaring fans at Madison Square Garden.\n\nThe New York Knicks marked their first NBA title in over five decades with a pregame ceremony on Tuesday, unveiling a 'World Champions' banner next to their 1970 and 1973 honors and distributing rings featuring nearly 800 diamonds, sapphires, and a twist mechanism revealing a mini Madison Square Garden.\n\nFans received 'Champions Night' shirts, and the team donned white-and-gold uniforms, but Philadelphia spoiled the evening with a 106-100 win led by Tyrese Maxey's 28 points, LeBron James' 14 points, nine rebounds and seven assists in his Sixers debut, and Jaylen Brown's 19 points. LeBron traded words with courtside Knicks fans, quipping 'Ain’t nothing soft in the Midwest' before noting his Ohio roots, while the loss underscored the challenges of defending the title in a competitive East.", "body_zh": "尼克斯升冠军旗帜发钻戒，揭幕战却负于76人。\n\n时隔 53 年，尼克斯球员戴上镶钻冠军戒指，2025-26 赛季总冠军旗帜在麦迪逊广场花园升上天花板，现场轰鸣。\n\n纽约尼克斯在周二赛前仪式上庆祝五十余年来首座 NBA 总冠军，将「世界冠军」旗帜挂在 1970、1973 年荣誉旁，并发放近 800 颗钻石与蓝宝石、可旋开露出迷你花园球场的戒指。\n\n球迷获「冠军之夜」衫，球队穿白金配色球衣，但费城以 106-100 扫兴：Tyrese Maxey 28 分，勒布朗·詹姆斯首秀 14 分 9 篮板 7 助攻，Jaylen Brown 19 分。勒布朗与场边尼克斯球迷互呛，调侃「中西部可不软」，并强调俄亥俄出身；失利凸显东区卫冕难度。", "url": "https://x.com/i/trending/2112695496611692714", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T17:21:47.000Z"}, {"id": "2112933588320878832", "domain": "体育", "title_en": "Carlton Fisk Waves Home Run Fair in Epic 1975 World Series Game 6", "title_zh": "卡尔顿·菲斯克挥臂「助攻」本垒打：1975 年世界大赛经典第六战", "hook_en": "Carlton Fisk leaped into the night air at Fenway Park, waving his arms wildly to coax his deep fly ball fair off the foul pole. That raw, joyous moment in the 12th inning sealed a 7-6 walk-off win for the Red Sox.", "hook_zh": "卡尔顿·菲斯克在芬威球场跃起，双手狂挥，把深远飞球「招」进界内击中标杆；第十二局这一幕定格红袜 7–6 再见胜。", "summary_en": "On October 21, 1975, Boston catcher Carlton Fisk led off the bottom of the 12th in Game 6 of the World Series against the Cincinnati Reds. He smashed a 1-0 sinker from Pat Darcy that hugged the left-field foul pole after Fisk's frantic urging, forcing a Game 7. Earlier, pinch-hitter Bernie Carbo's three-run homer in the eighth had tied it at 6-6. The NBC camera inside the Green Monster captured Fisk's emotion thanks to a cameraman distracted by a rat—creating footage that forever changed how we see athletes' big moments. Though the Reds won the title the next night, the game remains one of baseball's all-time classics.", "summary_zh": "1975 年 10 月 21 日，波士顿捕手卡尔顿·菲斯克在世界大赛对辛辛那提红人的第六战第十二局下半率先击球。他对帕特·达西一记 1-0 下坠球挥棒，球贴着左外野界外杆飞出，经他拼命挥臂「引导」后判为界内，逼出第七战。稍早替补打击伯尼·卡博第八局三垒打将比分追成 6–6。NBC 藏在「绿色怪物」内的摄像机因摄影师被老鼠分心而拍下菲斯克情绪——这段画面永久改变了人们观看运动员高光的方式。尽管红人次日夺冠，此役仍是棒球史上经典之一。", "body_en": "Carlton Fisk Waves Home Run Fair in Epic 1975 World Series Game 6.\n\nCarlton Fisk leaped into the night air at Fenway Park, waving his arms wildly to coax his deep fly ball fair off the foul pole. That raw, joyous moment in the 12th inning sealed a 7-6 walk-off win for the Red Sox.\n\nOn October 21, 1975, Boston catcher Carlton Fisk led off the bottom of the 12th in Game 6 of the World Series against the Cincinnati Reds. He smashed a 1-0 sinker from Pat Darcy that hugged the left-field foul pole after Fisk's frantic urging, forcing a Game 7.\n\nEarlier, pinch-hitter Bernie Carbo's three-run homer in the eighth had tied it at 6-6. The NBC camera inside the Green Monster captured Fisk's emotion thanks to a cameraman distracted by a rat—creating footage that forever changed how we see athletes' big moments. Though the Reds won the title the next night, the game remains one of baseball's all-time classics.", "body_zh": "卡尔顿·菲斯克挥臂「助攻」本垒打：1975 年世界大赛经典第六战。\n\n卡尔顿·菲斯克在芬威球场跃起，双手狂挥，把深远飞球「招」进界内击中标杆；第十二局这一幕定格红袜 7–6 再见胜。\n\n1975 年 10 月 21 日，波士顿捕手卡尔顿·菲斯克在世界大赛对辛辛那提红人的第六战第十二局下半率先击球。他对帕特·达西一记 1-0 下坠球挥棒，球贴着左外野界外杆飞出，经他拼命挥臂「引导」后判为界内，逼出第七战。\n\n稍早替补打击伯尼·卡博第八局三垒打将比分追成 6–6。NBC 藏在「绿色怪物」内的摄像机因摄影师被老鼠分心而拍下菲斯克情绪——这段画面永久改变了人们观看运动员高光的方式。尽管红人次日夺冠，此役仍是棒球史上经典之一。", "url": "https://x.com/i/trending/2112933588320878832", "category": "Sports", "topics": ["Baseball"], "updated_at": "2026-10-21T15:54:59.000Z"}, {"id": "2112930908437426481", "domain": "体育", "title_en": "LeBron James Questions Knicks' Championship Whistle in Hot Mic Moment", "title_zh": "勒布朗热麦吐槽尼克斯「冠军哨」", "hook_en": "As the Knicks celebrated their first title in 53 years with rings and a banner, LeBron James muttered into a hot mic: 'They win one chip they get a championship whistle.' The comment lit up reactions right away.", "hook_zh": "尼克斯庆祝 53 年来首冠、颁发戒指与升起横幅之际，勒布朗·詹姆斯对着热麦嘀咕：「他们赢一个冠军就拿到冠军哨了。」评论立刻引爆讨论。", "summary_en": "During the Knicks' season opener at Madison Square Garden, the Philadelphia 76ers beat the defending champs 106-100, with James—noted as a new 76ers forward after leaving the Lakers—posting 14 points, nine rebounds, and six assists. His remark, caught on a hot mic amid the Knicks' ceremony, sparked fans to debate officiating favoritism, with some calling out hypocrisy given LeBron's foul-drawing history and others defending the 'championship whistle' idea. Knicks fans chanted 'We don’t want you' at him during free throws, while the 76ers pulled ahead in the third quarter behind James, Embiid, Maxey, and Brown.", "summary_zh": "尼克斯赛季揭幕战在麦迪逊广场花园进行，费城 76 人以 106-100 击败卫冕冠军；离开湖人、加盟 76 人的勒布朗贡献 14 分、9 篮板、6 助攻。他的热麦言论夹在尼克斯庆典中被捕捉到，球迷随即争论裁判是否偏袒——有人批评勒布朗造犯规「双标」，也有人认同「冠军哨」说法。尼克斯球迷在他罚球时高喊「我们不要你」，第三节 76 人在詹姆斯、恩比德、马克西与布朗带领下拉开比分。", "body_en": "LeBron James Questions Knicks' Championship Whistle in Hot Mic Moment.\n\nAs the Knicks celebrated their first title in 53 years with rings and a banner, LeBron James muttered into a hot mic: 'They win one chip they get a championship whistle.' The comment lit up reactions right away.\n\nDuring the Knicks' season opener at Madison Square Garden, the Philadelphia 76ers beat the defending champs 106-100, with James—noted as a new 76ers forward after leaving the Lakers—posting 14 points, nine rebounds, and six assists.\n\nHis remark, caught on a hot mic amid the Knicks' ceremony, sparked fans to debate officiating favoritism, with some calling out hypocrisy given LeBron's foul-drawing history and others defending the 'championship whistle' idea. Knicks fans chanted 'We don’t want you' at him during free throws, while the 76ers pulled ahead in the third quarter behind James, Embiid, Maxey, and Brown.", "body_zh": "勒布朗热麦吐槽尼克斯「冠军哨」。\n\n尼克斯庆祝 53 年来首冠、颁发戒指与升起横幅之际，勒布朗·詹姆斯对着热麦嘀咕：「他们赢一个冠军就拿到冠军哨了。」评论立刻引爆讨论。\n\n尼克斯赛季揭幕战在麦迪逊广场花园进行，费城 76 人以 106-100 击败卫冕冠军；离开湖人、加盟 76 人的勒布朗贡献 14 分、9 篮板、6 助攻。\n\n他的热麦言论夹在尼克斯庆典中被捕捉到，球迷随即争论裁判是否偏袒——有人批评勒布朗造犯规「双标」，也有人认同「冠军哨」说法。尼克斯球迷在他罚球时高喊「我们不要你」，第三节 76 人在詹姆斯、恩比德、马克西与布朗带领下拉开比分。", "url": "https://x.com/i/trending/2112930908437426481", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T15:43:54.000Z"}, {"id": "2112281281501528167", "domain": "体育", "title_en": "Kyrie Irving Doubts Playing into His Early 40s as NBA Evolves", "title_zh": "凯里·欧文质疑自己能否像勒布朗一样打到四十出头", "hook_en": "Kyrie Irving paused during media day to reflect on a league that's changed since his childhood dreams. At 34, he loves the game but sees modern pressures making a long career like LeBron's unlikely for him.", "hook_zh": "凯里·欧文在媒体日反思：联盟已非儿时梦想中的模样。34 岁的他仍爱篮球，但觉现代压力让勒布朗式超长生涯对己不太可能。", "summary_en": "The Mavericks guard shared honest thoughts after practice Monday, saying he can't envision suiting up at 42 or 43 amid social media, gambling, and a more 'robotic' NBA far from the one he fell in love with as a kid. Irving praised LeBron James, Stephen Curry, and Kevin Durant for their longevity while noting shifts like mental health talks and tipping meetings that weren't around when he entered as the 2011 No. 1 pick. Preparing for his 2026-27 return after missing last season with a torn ACL, he's focused on enjoying competition and personal growth as Dallas opens Wednesday against Houston.", "summary_zh": "这名独行侠后卫周一训练后坦诚，在社交媒体、博彩与更「机械」的 NBA 中，难以想象自己 42、43 岁还穿球衣——那与儿时爱上的篮球相去甚远。他称赞勒布朗、库里与杜兰特的长寿，同时提到心理健康讨论、赛前提示会等入行时（2011 年状元秀）尚不存在的变化。在因 ACL 撕裂缺席上赛季后，他备战 2026–27 回归，专注享受竞争与成长，达拉斯周三对休斯敦揭幕。", "body_en": "Kyrie Irving Doubts Playing into His Early 40s as NBA Evolves.\n\nKyrie Irving paused during media day to reflect on a league that's changed since his childhood dreams. At 34, he loves the game but sees modern pressures making a long career like LeBron's unlikely for him.\n\nThe Mavericks guard shared honest thoughts after practice Monday, saying he can't envision suiting up at 42 or 43 amid social media, gambling, and a more 'robotic' NBA far from the one he fell in love with as a kid. Irving praised LeBron James, Stephen Curry, and Kevin Durant for their longevity while noting shifts like mental health talks and tipping meetings that weren't around when he entered as the 2011 No.\n\n1 pick. Preparing for his 2026-27 return after missing last season with a torn ACL, he's focused on enjoying competition and personal growth as Dallas opens Wednesday against Houston.", "body_zh": "凯里·欧文质疑自己能否像勒布朗一样打到四十出头。\n\n凯里·欧文在媒体日反思：联盟已非儿时梦想中的模样。34 岁的他仍爱篮球，但觉现代压力让勒布朗式超长生涯对己不太可能。\n\n这名独行侠后卫周一训练后坦诚，在社交媒体、博彩与更「机械」的 NBA 中，难以想象自己 42、43 岁还穿球衣——那与儿时爱上的篮球相去甚远。他称赞勒布朗、库里与杜兰特的长寿，同时提到心理健康讨论、赛前提示会等入行时（2011 年状元秀）尚不存在的变化。\n\n在因 ACL 撕裂缺席上赛季后，他备战 2026–27 回归，专注享受竞争与成长，达拉斯周三对休斯敦揭幕。", "url": "https://x.com/i/trending/2112281281501528167", "category": "Sports", "topics": [], "updated_at": "2026-10-20T15:54:00.000Z"}, {"id": "2112804232634187907", "domain": "体育", "title_en": "NBA Season Tips Off with Thunder Victory and Fan Joy", "title_zh": "NBA 新季揭幕：雷霆取胜，球迷欢腾", "hook_en": "Fans lit up with pure excitement as the 2026-27 NBA season returned, comparing it to Christmas and loving the team rivalries packed with popcorn drama.", "hook_zh": "2026–27 赛季回归，球迷兴奋如过圣诞，津津乐道火药味十足的对档戏码。", "summary_en": "The season kicked off on October 20 with a tripleheader, highlighted by the Oklahoma City Thunder beating the San Antonio Spurs 116-104 in a Western Conference Finals rematch. Shai Gilgeous-Alexander scored 32 points to lead OKC, fueling the tension between teams with physical histories and stars like Chet Holmgren and Victor Wembanyama. Other games saw the Knicks drop their banner night to the 76ers, while the Pistons rallied past the Celtics. Supporters shared heartfelt posts calling it the best time of year, with real hate between teams making every matchup thrilling.", "summary_zh": "赛季 10 月 20 日以三场连赛揭幕，焦点之一是西决重演：俄克拉荷马城雷霆 116–104 击败圣安东尼奥马刺。谢伊·吉尔杰斯-亚历山大砍下 32 分领军，两队身体对抗史与霍姆格伦、文班亚马等球星令火药味十足。另场尼克斯主场横幅夜不敌 76 人，活塞逆转凯尔特人。球迷发帖称一年中最美好时光，真实「恨意」让每场都刺激。", "body_en": "NBA Season Tips Off with Thunder Victory and Fan Joy.\n\nFans lit up with pure excitement as the 2026-27 NBA season returned, comparing it to Christmas and loving the team rivalries packed with popcorn drama.\n\nThe season kicked off on October 20 with a tripleheader, highlighted by the Oklahoma City Thunder beating the San Antonio Spurs 116-104 in a Western Conference Finals rematch. Shai Gilgeous-Alexander scored 32 points to lead OKC, fueling the tension between teams with physical histories and stars like Chet Holmgren and Victor Wembanyama.\n\nOther games saw the Knicks drop their banner night to the 76ers, while the Pistons rallied past the Celtics. Supporters shared heartfelt posts calling it the best time of year, with real hate between teams making every matchup thrilling.", "body_zh": "NBA 新季揭幕：雷霆取胜，球迷欢腾。\n\n2026–27 赛季回归，球迷兴奋如过圣诞，津津乐道火药味十足的对档戏码。\n\n赛季 10 月 20 日以三场连赛揭幕，焦点之一是西决重演：俄克拉荷马城雷霆 116–104 击败圣安东尼奥马刺。谢伊·吉尔杰斯-亚历山大砍下 32 分领军，两队身体对抗史与霍姆格伦、文班亚马等球星令火药味十足。\n\n另场尼克斯主场横幅夜不敌 76 人，活塞逆转凯尔特人。球迷发帖称一年中最美好时光，真实「恨意」让每场都刺激。", "url": "https://x.com/i/trending/2112804232634187907", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T07:17:07.000Z"}, {"id": "2112801176995467757", "domain": "体育", "title_en": "Sixers Upset Knicks on Ring Night with LeBron and Brown Debuts", "title_zh": "76 人队揭幕战客场击败尼克斯，詹姆斯与布朗亮相", "hook_en": "LeBron James stepped onto Madison Square Garden's floor for his Sixers debut, and the team quickly turned a pre-game doubter's tweet into prime ammo for fans.", "hook_zh": "勒布朗·詹姆斯身披 76 人队服登陆麦迪逊广场花园，揭幕战即成粉丝话题。", "summary_en": "The Philadelphia 76ers kicked off the 2026-27 NBA season with a 106-100 road win over the defending champion New York Knicks, spoiling their ring night celebration. Tyrese Maxey led with 28 points in the second-half rally, while new additions LeBron James tallied 14 points, nine rebounds, and seven assists, and Jaylen Brown added 19 points, eight rebounds, and six assists alongside Joel Embiid and Maxey. Fans immediately called out a pre-game tweet dismissing the Sixers as non-contenders, though many noted it's just the first of 82 games and true tests lie ahead.", "summary_zh": "费城 76 人队以 106-100 客场击败卫冕冠军纽约尼克斯，扫了对方戒指之夜的兴。马克西砍下 28 分带领下半场逆转；新援詹姆斯得到 14 分 9 篮板 7 助攻，杰伦·布朗贡献 19 分 8 篮板 6 助攻，恩比德亦在阵中。赛前有人发帖否认 76 人争冠资格，赛后被粉丝翻出调侃；不过多数人提醒赛季漫长，真正考验还在后头。", "body_en": "Sixers Upset Knicks on Ring Night with LeBron and Brown Debuts.\n\nLeBron James stepped onto Madison Square Garden's floor for his Sixers debut, and the team quickly turned a pre-game doubter's tweet into prime ammo for fans.\n\nThe Philadelphia 76ers kicked off the 2026-27 NBA season with a 106-100 road win over the defending champion New York Knicks, spoiling their ring night celebration.\n\nTyrese Maxey led with 28 points in the second-half rally, while new additions LeBron James tallied 14 points, nine rebounds, and seven assists, and Jaylen Brown added 19 points, eight rebounds, and six assists alongside Joel Embiid and Maxey. Fans immediately called out a pre-game tweet dismissing the Sixers as non-contenders, though many noted it's just the first of 82 games and true tests lie ahead.", "body_zh": "76 人队揭幕战客场击败尼克斯，詹姆斯与布朗亮相。\n\n勒布朗·詹姆斯身披 76 人队服登陆麦迪逊广场花园，揭幕战即成粉丝话题。\n\n费城 76 人队以 106-100 客场击败卫冕冠军纽约尼克斯，扫了对方戒指之夜的兴。马克西砍下 28 分带领下半场逆转；新援詹姆斯得到 14 分 9 篮板 7 助攻，杰伦·布朗贡献 19 分 8 篮板 6 助攻，恩比德亦在阵中。\n\n赛前有人发帖否认 76 人争冠资格，赛后被粉丝翻出调侃；不过多数人提醒赛季漫长，真正考验还在后头。", "url": "https://x.com/i/trending/2112801176995467757", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T07:06:29.000Z"}, {"id": "2112718297158332458", "domain": "体育", "title_en": "Pistons Upset Celtics in NBA's Rare Afternoon Opener", "title_zh": "活塞下午赛爆冷击败凯尔特人，NBA 试水日间开赛", "hook_en": "On a Tuesday afternoon, the Detroit Pistons stunned the Boston Celtics 121-113 in the NBA's bold 3 p.m. tip-off experiment. Fans lit up with cheers and questions about daytime hoops during work hours.", "hook_zh": "底特律活塞 121–113 击败波士顿凯尔特人，NBA 罕见的下午 3 点揭幕战引发热议。", "summary_en": "The league kicked off its 2026-27 season with a tripleheader on NBC and Peacock, starting with Detroit's win over Boston to dodge overlap with the Knicks' banner ceremony in New York. Officials pitched the early slot as a test to mimic MLB's big opening days and catch European prime time viewers. While some fans loved the fresh vibe and called for more weekday matinees, others puzzled over the timing and griped about games often starting late anyway. Detroit grabbed its first opening-night win in years, spotlighting Boston's new-look team with Paul George.", "summary_zh": "2026–27 赛季在 NBC 与 Peacock 以三场连播揭幕，活塞战胜凯尔特人，以避免与尼克斯横幅仪式撞车。联盟称早场旨在对标大联盟开幕氛围并覆盖欧洲黄金时段。部分球迷呼吁更多工作日日场，也有人质疑时机。活塞取得多年来首场揭幕战胜利，凯尔特人新阵容（含保罗·乔治）亦受关注。", "body_en": "Pistons Upset Celtics in NBA's Rare Afternoon Opener.\n\nOn a Tuesday afternoon, the Detroit Pistons stunned the Boston Celtics 121-113 in the NBA's bold 3 p.m. tip-off experiment. Fans lit up with cheers and questions about daytime hoops during work hours.\n\nThe league kicked off its 2026-27 season with a tripleheader on NBC and Peacock, starting with Detroit's win over Boston to dodge overlap with the Knicks' banner ceremony in New York. Officials pitched the early slot as a test to mimic MLB's big opening days and catch European prime time viewers.\n\nWhile some fans loved the fresh vibe and called for more weekday matinees, others puzzled over the timing and griped about games often starting late anyway. Detroit grabbed its first opening-night win in years, spotlighting Boston's new-look team with Paul George.", "body_zh": "活塞下午赛爆冷击败凯尔特人，NBA 试水日间开赛。\n\n底特律活塞 121–113 击败波士顿凯尔特人，NBA 罕见的下午 3 点揭幕战引发热议。\n\n2026–27 赛季在 NBC 与 Peacock 以三场连播揭幕，活塞战胜凯尔特人，以避免与尼克斯横幅仪式撞车。联盟称早场旨在对标大联盟开幕氛围并覆盖欧洲黄金时段。\n\n部分球迷呼吁更多工作日日场，也有人质疑时机。活塞取得多年来首场揭幕战胜利，凯尔特人新阵容（含保罗·乔治）亦受关注。", "url": "https://x.com/i/trending/2112718297158332458", "category": "Sports", "topics": ["NBA"], "updated_at": "2026-10-21T01:36:46.000Z"}, {"id": "2112138759433252907", "domain": "体育", "title_en": "Kimi Antonelli Poised to Clinch F1 Title in Texas", "title_zh": "安东内利有望在得州锁定 F1 车手冠军", "hook_en": "At just 20 years old, Kimi Antonelli stands on the brink of F1 history in Austin, where a strong finish could crown him the youngest champion ever.", "hook_zh": "年仅 20 岁的基米·安东内利站在 F1 史册门口：在奥斯汀一场强势完赛，就可能成为史上最年轻世界冠军。", "summary_en": "The Mercedes driver leads the 2026 championship by 102 points over George Russell after 17 races, with Lewis Hamilton, Max Verstappen, Charles Leclerc, and Lando Norris still mathematically alive but far behind. He can seal the title at the United States Grand Prix if he wins while Russell places ninth or worse and Hamilton fifth or lower, shattering Sebastian Vettel's record set at 23 years and 134 days. Track data shows Antonelli's top race pace this season, though Mercedes boss Toto Wolff calls the math tough, and fans buzz with excitement and jinx worries ahead of the Americas triple-header.", "summary_zh": "这位梅赛德斯车手在 17 站后领先队友乔治·拉塞尔 102 分；汉密尔顿、维斯塔潘、勒克莱尔、诺里斯数学上仍有机会但差距巨大。若他在美国大奖赛夺冠，且拉塞尔第九或更差、汉密尔顿第五或更低，即可提前夺冠，打破维特尔 23 岁零 134 天的最年轻纪录。赛道数据显示其本季赛季圈速顶尖，梅赛德斯老板托托·沃尔夫称计算仍艰难；粉丝既兴奋又怕「乌鸦嘴」，美洲三连站即将开始。", "body_en": "Kimi Antonelli Poised to Clinch F1 Title in Texas.\n\nAt just 20 years old, Kimi Antonelli stands on the brink of F1 history in Austin, where a strong finish could crown him the youngest champion ever.\n\nThe Mercedes driver leads the 2026 championship by 102 points over George Russell after 17 races, with Lewis Hamilton, Max Verstappen, Charles Leclerc, and Lando Norris still mathematically alive but far behind.\n\nHe can seal the title at the United States Grand Prix if he wins while Russell places ninth or worse and Hamilton fifth or lower, shattering Sebastian Vettel's record set at 23 years and 134 days. Track data shows Antonelli's top race pace this season, though Mercedes boss Toto Wolff calls the math tough, and fans buzz with excitement and jinx worries ahead of the Americas triple-header.", "body_zh": "安东内利有望在得州锁定 F1 车手冠军。\n\n年仅 20 岁的基米·安东内利站在 F1 史册门口：在奥斯汀一场强势完赛，就可能成为史上最年轻世界冠军。\n\n这位梅赛德斯车手在 17 站后领先队友乔治·拉塞尔 102 分；汉密尔顿、维斯塔潘、勒克莱尔、诺里斯数学上仍有机会但差距巨大。\n\n若他在美国大奖赛夺冠，且拉塞尔第九或更差、汉密尔顿第五或更低，即可提前夺冠，打破维特尔 23 岁零 134 天的最年轻纪录。赛道数据显示其本季赛季圈速顶尖，梅赛德斯老板托托·沃尔夫称计算仍艰难；粉丝既兴奋又怕「乌鸦嘴」，美洲三连站即将开始。", "url": "https://x.com/i/trending/2112138759433252907", "category": "Sports", "topics": ["Formula 1"], "updated_at": "2026-10-20T23:48:55.000Z"}, {"id": "2112527510105919970", "domain": "体育", "title_en": "Ex-NFL Player Accuses Refs of Rigging Games for Chiefs", "title_zh": "前 NFL 球员指控裁判偏袒酋长队操控比赛", "hook_en": "Breiden Fehoko leaned into the mic on a podcast and called out what he saw as late-game favoritism for the Chiefs. His words tapped into frustrations many rival fans have felt for years.", "hook_zh": "Breiden Fehoko 在播客上直指他认为的酋长队末节「照顾球」，戳中多年对手球迷的积怨。", "summary_en": "Former Chargers defensive tackle Breiden Fehoko claimed on Jason Whitlock's podcast that officials give Kansas City 'ghost calls' in the fourth quarter to swing tight games. He pointed to a pattern where penalties bail out the Chiefs when trailing, calling it a 'mockery,' and challenged refs to stay impartial in the playoffs. Critics noted his limited experience—just one game against Kansas City and 19 career appearances—while fans referenced moments like the 2022 AFC Championship as supposed proof. The debate highlights ongoing gripes about NFL officiating but lacks hard evidence of rigging.", "summary_zh": "前闪电队防守截锋 Breiden Fehoko 在 Jason Whitlock 播客上声称，官员会在第四节给堪萨斯城「幽灵判罚」扳动胶着比赛。他称落后时点球常救酋长，是「嘲弄」，并要求季后赛裁判保持中立。批评者指出其样本极小——仅打过一场对酋长、生涯 19 场出场——粉丝则搬出 2022 年 AFC 冠军赛等作为「证据」。争论凸显对 NFL 执法的持续不满，但缺乏操纵的硬证据。", "body_en": "Ex-NFL Player Accuses Refs of Rigging Games for Chiefs.\n\nBreiden Fehoko leaned into the mic on a podcast and called out what he saw as late-game favoritism for the Chiefs. His words tapped into frustrations many rival fans have felt for years.\n\nFormer Chargers defensive tackle Breiden Fehoko claimed on Jason Whitlock's podcast that officials give Kansas City 'ghost calls' in the fourth quarter to swing tight games. He pointed to a pattern where penalties bail out the Chiefs when trailing, calling it a 'mockery,' and challenged refs to stay impartial in the playoffs.\n\nCritics noted his limited experience—just one game against Kansas City and 19 career appearances—while fans referenced moments like the 2022 AFC Championship as supposed proof. The debate highlights ongoing gripes about NFL officiating but lacks hard evidence of rigging.", "body_zh": "前 NFL 球员指控裁判偏袒酋长队操控比赛。\n\nBreiden Fehoko 在播客上直指他认为的酋长队末节「照顾球」，戳中多年对手球迷的积怨。\n\n前闪电队防守截锋 Breiden Fehoko 在 Jason Whitlock 播客上声称，官员会在第四节给堪萨斯城「幽灵判罚」扳动胶着比赛。他称落后时点球常救酋长，是「嘲弄」，并要求季后赛裁判保持中立。\n\n批评者指出其样本极小——仅打过一场对酋长、生涯 19 场出场——粉丝则搬出 2022 年 AFC 冠军赛等作为「证据」。争论凸显对 NFL 执法的持续不满，但缺乏操纵的硬证据。", "url": "https://x.com/i/trending/2112527510105919970", "category": "Sports", "topics": ["NFL"], "updated_at": "2026-10-21T02:52:40.000Z"}, {"id": "2112256411413492225", "domain": "体育", "title_en": "Manchester City Tops Both Premier League and Women's Super League Tables", "title_zh": "曼城男足与女足双双领跑英超与女超", "hook_en": "Jubilant players from Manchester City's men's and women's squads grinned together in a club graphic celebrating their dual dominance at the top of the tables.", "hook_zh": "曼城男女足球员在俱乐部海报上一起微笑，庆祝双线榜首的统治力。", "summary_en": "The men's team leads the Premier League with seven straight wins and 21 points, including a 3-2 victory over Ipswich Town where Erling Haaland scored twice and Phil Foden opened the scoring. Manager Enzo Maresca made history as the first to win his opening seven top-flight games. The women's side sits atop the Women's Super League with six wins from six matches and 18 points, boosted by Bunny Shaw's double in a 3-2 win against Brighton. City fans beamed with pride while rivals like Chelsea and Arsenal supporters predicted a short stay at the summit amid the club's financial proceedings.", "summary_zh": "男足七连胜积 21 分领跑英超，其中包括 3-2 战胜伊普斯维奇，哈兰德梅开二度、福登先拔头筹。主帅恩佐·马雷斯卡成为首位开局七场全胜顶级联赛的教练。女足六战全胜积 18 分领跑女超，Bunny Shaw 双响助队 3-2 胜布莱顿。蓝月亮球迷自豪，切尔西、阿森纳等对手则预测榜首不会太久，同时俱乐部仍处财务程序之中。", "body_en": "Manchester City Tops Both Premier League and Women's Super League Tables.\n\nJubilant players from Manchester City's men's and women's squads grinned together in a club graphic celebrating their dual dominance at the top of the tables.\n\nThe men's team leads the Premier League with seven straight wins and 21 points, including a 3-2 victory over Ipswich Town where Erling Haaland scored twice and Phil Foden opened the scoring. Manager Enzo Maresca made history as the first to win his opening seven top-flight games.\n\nThe women's side sits atop the Women's Super League with six wins from six matches and 18 points, boosted by Bunny Shaw's double in a 3-2 win against Brighton. City fans beamed with pride while rivals like Chelsea and Arsenal supporters predicted a short stay at the summit amid the club's financial proceedings.", "body_zh": "曼城男足与女足双双领跑英超与女超。\n\n曼城男女足球员在俱乐部海报上一起微笑，庆祝双线榜首的统治力。\n\n男足七连胜积 21 分领跑英超，其中包括 3-2 战胜伊普斯维奇，哈兰德梅开二度、福登先拔头筹。主帅恩佐·马雷斯卡成为首位开局七场全胜顶级联赛的教练。\n\n女足六战全胜积 18 分领跑女超，Bunny Shaw 双响助队 3-2 胜布莱顿。蓝月亮球迷自豪，切尔西、阿森纳等对手则预测榜首不会太久，同时俱乐部仍处财务程序之中。", "url": "https://x.com/i/trending/2112256411413492225", "category": "Sports", "topics": ["Premier League"], "updated_at": "2026-10-19T19:03:30.000Z"}, {"id": "2111900672748564914", "domain": "体育", "title_en": "Tyler Reddick Wins Phoenix Thriller, Post-Race Clash Erupts", "title_zh": "雷迪克惊险赢凤凰城，赛后爆发冲突", "hook_en": "Tyler Reddick grabbed the lead on fresh tires and held off Ryan Blaney by under a second, but tempers boiled over on the cooldown lap.", "hook_zh": "泰勒·雷迪克靠新胎抢下领先，以不足一秒压住瑞恩·布莱尼，冷却圈上却火药味十足。", "summary_en": "Driving for 23XI Racing, Reddick scored his sixth victory of the season at Phoenix Raceway, beating polesitter Blaney by 0.801 seconds with Chase Elliott third. Zane Smith rammed Carson Hocevar's car after the checkered flag amid their heated rivalry, sparked by earlier on-track contact where Hocevar's No. 77 got shoved into Smith's No. 38. Kyle Larson's late crash dropped him to a slim five-point playoff lead, while Reddick stays 56 points back in the tight championship fight heading to Talladega. Toyota locked up the manufacturer's title, and post-race checks confirmed the results.", "summary_zh": "效力 23XI Racing 的雷迪克在凤凰城赛道拿下本季第六胜，以 0.801 秒力压杆位布莱尼，蔡斯·艾略特第三。方格旗后 Zane Smith 撞击 Carson Hocevar 赛车，两人宿怨因赛道接触而起——Hocevar 的 77 号曾被推撞 Smith 的 38 号。凯尔·拉森末段撞车，季后赛积分仅领先 5 分；雷迪克落后 56 分，冠军争夺仍紧，下一站塔拉迪加。丰田锁定厂商冠军，赛后检查确认成绩有效。", "body_en": "Tyler Reddick Wins Phoenix Thriller, Post-Race Clash Erupts.\n\nTyler Reddick grabbed the lead on fresh tires and held off Ryan Blaney by under a second, but tempers boiled over on the cooldown lap.\n\nDriving for 23XI Racing, Reddick scored his sixth victory of the season at Phoenix Raceway, beating polesitter Blaney by 0.801 seconds with Chase Elliott third. Zane Smith rammed Carson Hocevar's car after the checkered flag amid their heated rivalry, sparked by earlier on-track contact where Hocevar's No. 77 got shoved into Smith's No.\n\n38. Kyle Larson's late crash dropped him to a slim five-point playoff lead, while Reddick stays 56 points back in the tight championship fight heading to Talladega. Toyota locked up the manufacturer's title, and post-race checks confirmed the results.", "body_zh": "雷迪克惊险赢凤凰城，赛后爆发冲突。\n\n泰勒·雷迪克靠新胎抢下领先，以不足一秒压住瑞恩·布莱尼，冷却圈上却火药味十足。\n\n效力 23XI Racing 的雷迪克在凤凰城赛道拿下本季第六胜，以 0.801 秒力压杆位布莱尼，蔡斯·艾略特第三。方格旗后 Zane Smith 撞击 Carson Hocevar 赛车，两人宿怨因赛道接触而起——Hocevar 的 77 号曾被推撞 Smith 的 38 号。\n\n凯尔·拉森末段撞车，季后赛积分仅领先 5 分；雷迪克落后 56 分，冠军争夺仍紧，下一站塔拉迪加。丰田锁定厂商冠军，赛后检查确认成绩有效。", "url": "https://x.com/i/trending/2111900672748564914", "category": "Sports", "topics": ["NASCAR"], "updated_at": "2026-10-19T16:45:58.000Z"}, {"id": "2112826877455053262", "domain": "娱乐", "title_en": "India Adds Three Sites to UNESCO World Heritage Tentative List", "title_zh": "印度新增三处遗址进入联合国教科文组织世界遗产预备名单", "hook_en": "From bubbling mud volcanoes in the Andamans to ancient temples along the Mahanadi River, three Indian treasures now stand closer to global recognition.", "hook_zh": "从安达曼冒泡的泥火山，到马哈纳迪河沿岸古寺，三处印度遗产向全球认可又近一步。", "summary_en": "India's Permanent Delegation to UNESCO announced on October 20, 2026, the addition of the Karst-mud-volcano Complex of Baratang and Andaman Subduction Volcanoes in the Andaman and Nicobar Islands, plus the Sirpur Cultural and Archaeological Landscape in Chhattisgarh. These sites highlight unique geology like active volcanoes and limestone caves, alongside historic temples reflecting Hindu, Buddhist, and Jain heritage with evidence of multi-faith harmony. Union Minister Gajendra Singh Shekhawat praised Sirpur for its traditions in art, architecture, spirituality, and learning, as India builds on its 45 inscribed World Heritage Sites.", "summary_zh": "印度常驻联合国教科文组织代表团于 2026 年 10 月 20 日宣布，将安达曼-尼科巴群岛的巴拉唐岩溶泥火山综合体与安达曼俯冲火山，以及恰蒂斯加尔邦的希尔普尔文化考古景观列入预备名单。这些地点既有活火山、石灰岩洞穴等独特地质，也有体现印度教、佛教与耆那教遗产及多信仰共处的历史寺庙。联邦部长 Gajendra Singh Shekhawat 称赞希尔普尔在艺术、建筑、灵性与学问上的传统；印度目前已有 45 处列入世界遗产名录。", "body_en": "India Adds Three Sites to UNESCO World Heritage Tentative List.\n\nFrom bubbling mud volcanoes in the Andamans to ancient temples along the Mahanadi River, three Indian treasures now stand closer to global recognition.\n\nIndia's Permanent Delegation to UNESCO announced on October 20, 2026, the addition of the Karst-mud-volcano Complex of Baratang and Andaman Subduction Volcanoes in the Andaman and Nicobar Islands, plus the Sirpur Cultural and Archaeological Landscape in Chhattisgarh.\n\nThese sites highlight unique geology like active volcanoes and limestone caves, alongside historic temples reflecting Hindu, Buddhist, and Jain heritage with evidence of multi-faith harmony. Union Minister Gajendra Singh Shekhawat praised Sirpur for its traditions in art, architecture, spirituality, and learning, as India builds on its 45 inscribed World Heritage Sites.", "body_zh": "印度新增三处遗址进入联合国教科文组织世界遗产预备名单。\n\n从安达曼冒泡的泥火山，到马哈纳迪河沿岸古寺，三处印度遗产向全球认可又近一步。\n\n印度常驻联合国教科文组织代表团于 2026 年 10 月 20 日宣布，将安达曼-尼科巴群岛的巴拉唐岩溶泥火山综合体与安达曼俯冲火山，以及恰蒂斯加尔邦的希尔普尔文化考古景观列入预备名单。\n\n这些地点既有活火山、石灰岩洞穴等独特地质，也有体现印度教、佛教与耆那教遗产及多信仰共处的历史寺庙。联邦部长 Gajendra Singh Shekhawat 称赞希尔普尔在艺术、建筑、灵性与学问上的传统；印度目前已有 45 处列入世界遗产名录。", "url": "https://x.com/i/trending/2112826877455053262", "category": "News", "topics": ["Travel"], "updated_at": "2026-10-21T11:43:52.000Z"}, {"id": "2112918023249989711", "domain": "娱乐", "title_en": "Sunshine Benzi Shares Notebook-to-Studio Process for 'Forbes List'", "title_zh": "Sunshine Benzi 分享《Forbes List》从笔记本到录音棚的创作过程", "hook_en": "Sunshine Benzi flips through her notebook in the studio, pen flying as she crafts lyrics for her new track. Fans can't get enough of her hands-on hustle.", "hook_zh": "Sunshine Benzi 在录音棚翻着笔记本奋笔写词，粉丝为她亲力亲为的创作节奏着迷。", "summary_en": "The 24-year-old Chicago-area rapper, born Sunshine Kathleen Holt in Pontiac, Illinois, posted behind-the-scenes clips of writing and recording 'Forbes List,' produced by Bangladesh of Nicki Minaj fame and Chinoo.xo. Viewers praise her raw talent, work ethic, and poetry-rooted approach, with comments like 'this chick can rap' and 'RAW talent' flooding in. She first gained notice in late 2025 with her TikTok freestyle 'Trump the Bill,' followed by singles like 'Barracuda' and a December 2026 Miss Bellum Tour. While some note her background as a white artist in hip-hop, the buzz focuses on her focused craft and building momentum.", "summary_zh": "这位 24 岁、生于伊利诺伊州庞蒂亚克的芝加哥地区说唱歌手 Sunshine Kathleen Holt，晒出创作与录制《Forbes List》的幕后片段，制作人包括曾与 Nicki Minaj 合作的 Bangladesh 以及 Chinoo.xo。观众称赞其原始才华、工作态度与诗歌根底，评论区常见「这姑娘会说唱」「真正的天赋」等话。她 2025 年末因 TikTok 自由说唱《Trump the Bill》走红，随后发行《Barracuda》等单曲，并计划 2026 年 12 月 Miss Bellum 巡演。虽有人提到她作为白人艺人进入嘻哈圈的背景，讨论焦点仍在其专注打磨与持续升温的势头。", "body_en": "Sunshine Benzi Shares Notebook-to-Studio Process for 'Forbes List'.\n\nSunshine Benzi flips through her notebook in the studio, pen flying as she crafts lyrics for her new track. Fans can't get enough of her hands-on hustle.\n\nThe 24-year-old Chicago-area rapper, born Sunshine Kathleen Holt in Pontiac, Illinois, posted behind-the-scenes clips of writing and recording 'Forbes List,' produced by Bangladesh of Nicki Minaj fame and Chinoo.xo. Viewers praise her raw talent, work ethic, and poetry-rooted approach, with comments like 'this chick can rap' and 'RAW talent' flooding in.\n\nShe first gained notice in late 2025 with her TikTok freestyle 'Trump the Bill,' followed by singles like 'Barracuda' and a December 2026 Miss Bellum Tour. While some note her background as a white artist in hip-hop, the buzz focuses on her focused craft and building momentum.", "body_zh": "Sunshine Benzi 分享《Forbes List》从笔记本到录音棚的创作过程。\n\nSunshine Benzi 在录音棚翻着笔记本奋笔写词，粉丝为她亲力亲为的创作节奏着迷。\n\n这位 24 岁、生于伊利诺伊州庞蒂亚克的芝加哥地区说唱歌手 Sunshine Kathleen Holt，晒出创作与录制《Forbes List》的幕后片段，制作人包括曾与 Nicki Minaj 合作的 Bangladesh 以及 Chinoo.xo。观众称赞其原始才华、工作态度与诗歌根底，评论区常见「这姑娘会说唱」「真正的天赋」等话。\n\n她 2025 年末因 TikTok 自由说唱《Trump the Bill》走红，随后发行《Barracuda》等单曲，并计划 2026 年 12 月 Miss Bellum 巡演。虽有人提到她作为白人艺人进入嘻哈圈的背景，讨论焦点仍在其专注打磨与持续升温的势头。", "url": "https://x.com/i/trending/2112918023249989711", "category": "Entertainment", "topics": ["Music"], "updated_at": "2026-10-21T14:50:09.000Z"}, {"id": "2112078869360726394", "domain": "娱乐", "title_en": "Lingling Kwong Shines at Cartier’s Into The Wild Event in Singapore", "title_zh": "Kwong Lingling 亮相新加坡卡地亚「Into The Wild」活动", "hook_en": "Lingling Kwong turned heads in a shimmering black sequined gown and dramatic floral gloves, posing confidently amid jungle-inspired backdrops at Cartier’s elegant gathering.", "hook_zh": "Kwong Lingling 身着闪亮黑色亮片礼服、搭配戏剧感花卉手套，在丛林灵感布景前自信亮相，成为卡地亚雅集焦点。", "summary_en": "On October 19, Thai actress Lingling Kwong brought her sophisticated style to Cartier’s “Into The Wild” event in Singapore, celebrating the brand’s iconic panther motifs and animal-inspired jewelry. She stunned in multiple looks, from a strapless grey dress to a flowing black gown, accessorized with bold silver chains, sparkling bracelets, and statement earrings. Fans raved about her radiant smile and glamour, with one calling her “Elegance has a name.” The immersive experience opens to the public at 17 Rochester Park from October 21 to 25, with elements lingering at ION Orchard through early November.", "summary_zh": "10 月 19 日，泰国女演员 Kwong Lingling 以精致造型出席新加坡卡地亚「Into The Wild」活动，庆祝品牌标志性豹纹与动物灵感珠宝。她多次换装，从抹胸灰裙到飘逸黑礼服，搭配粗银链、闪亮手镯与夸张耳环。粉丝盛赞其笑容与气场，有人写道「优雅有了名字」。沉浸式体验 10 月 21 日至 25 日在 17 Rochester Park 对公众开放，部分元素将在 ION Orchard 延续至 11 月初。", "body_en": "Lingling Kwong Shines at Cartier’s Into The Wild Event in Singapore.\n\nLingling Kwong turned heads in a shimmering black sequined gown and dramatic floral gloves, posing confidently amid jungle-inspired backdrops at Cartier’s elegant gathering.\n\nOn October 19, Thai actress Lingling Kwong brought her sophisticated style to Cartier’s “Into The Wild” event in Singapore, celebrating the brand’s iconic panther motifs and animal-inspired jewelry.\n\nShe stunned in multiple looks, from a strapless grey dress to a flowing black gown, accessorized with bold silver chains, sparkling bracelets, and statement earrings. Fans raved about her radiant smile and glamour, with one calling her “Elegance has a name.” The immersive experience opens to the public at 17 Rochester Park from October 21 to 25, with elements lingering at ION Orchard through early November.", "body_zh": "Kwong Lingling 亮相新加坡卡地亚「Into The Wild」活动。\n\nKwong Lingling 身着闪亮黑色亮片礼服、搭配戏剧感花卉手套，在丛林灵感布景前自信亮相，成为卡地亚雅集焦点。\n\n10 月 19 日，泰国女演员 Kwong Lingling 以精致造型出席新加坡卡地亚「Into The Wild」活动，庆祝品牌标志性豹纹与动物灵感珠宝。她多次换装，从抹胸灰裙到飘逸黑礼服，搭配粗银链、闪亮手镯与夸张耳环。\n\n粉丝盛赞其笑容与气场，有人写道「优雅有了名字」。沉浸式体验 10 月 21 日至 25 日在 17 Rochester Park 对公众开放，部分元素将在 ION Orchard 延续至 11 月初。", "url": "https://x.com/i/trending/2112078869360726394", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-21T06:02:16.000Z"}, {"id": "2112801173090587112", "domain": "娱乐", "title_en": "Thai Actress Lingling Kwong Shines at Cartier’s Into the Wild Event in Singapore", "title_zh": "Lingling Kwong 亮相新加坡卡地亚活动", "hook_en": "Lingling Kwong stepped into a lush garden paradise in Singapore, her shimmering black sequined gown and dramatic gloves catching every light amid animal-inspired jewelry.", "hook_zh": "Lingling Kwong 身着黑色亮片长裙、配戏剧性手套，走进卡地亚丛林主题场景，以经典优雅吸引目光。", "summary_en": "Thai actress Lingling Kwong attended Cartier’s “Into the Wild” celebration at Rochester Park as a special guest, wearing striking ensembles from the Faune & Flore collection that blended sequins, floral details, and signature motifs. The event transformed heritage houses and gardens into immersive spaces with illuminated designs, artisan demos, dance performances, and sensory highlights of Cartier’s jewelry, watches, fragrances, and leather goods. Fans and media praised her elegant presence, with the experience open to the public through October 25 at 17 Rochester Park via advance registration.", "summary_zh": "10 月 21 日在罗切斯特公园举行的「Into the Wild」沉浸式体验中，她佩戴卡地亚全新 Faune & Flore 系列，搭配缟玛瑙、蓝宝石与钻石，被粉丝称为「女王范」。活动展出品牌动物灵感设计，持续至 10 月 25 日。同日她还在曼谷大型粉丝活动上推广 Her Hyness 防晒产品，凸显其在奢侈品与美妆领域的上升势头。", "body_en": "Lingling Kwong Shines at Cartier Event in Singapore.\n\nLingling Kwong stepped into Cartier’s wild jungle-themed world in a sleek black sequined gown and dramatic gloves, turning heads with her timeless elegance.\n\nAt the 'Into the Wild' immersive experience in Rochester Park on October 21, Kwong wore pieces from Cartier’s new Faune & Flore collection, featuring onyx, sapphires, and diamonds that fans called striking and queenly.\n\nThe event celebrates the brand’s animal-inspired designs through October 25. That same day, she promoted Her Hyness sunscreen at a big fan event in Bangkok, highlighting her rising star in luxury and beauty.", "body_zh": "Lingling Kwong 亮相新加坡卡地亚活动。\n\nLingling Kwong 身着黑色亮片长裙、配戏剧性手套，走进卡地亚丛林主题场景，以经典优雅吸引目光。\n\n10 月 21 日在罗切斯特公园举行的「Into the Wild」沉浸式体验中，她佩戴卡地亚全新 Faune & Flore 系列，搭配缟玛瑙、蓝宝石与钻石，被粉丝称为「女王范」。\n\n活动展出品牌动物灵感设计，持续至 10 月 25 日。同日她还在曼谷大型粉丝活动上推广 Her Hyness 防晒产品，凸显其在奢侈品与美妆领域的上升势头。", "url": "https://x.com/i/trending/2112801173090587112", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-21T17:57:44.000Z"}, {"id": "2112653365356433717", "domain": "娱乐", "title_en": "Fans Defend Ariana Grande as Glinda Against Amanda Seyfried Casting Talk", "title_zh": "粉丝力挺格兰德饰演格琳达，回应赛弗里德「本可更好」论", "hook_en": "A post wondering if Amanda Seyfried would have topped Ariana Grande as Glinda in Wicked quickly met pushback from fans who love the film's magic just as it is.", "hook_zh": "有人猜测若由阿曼达·赛弗里德演《魔法坏女巫》格琳达会否更佳，粉丝迅速反驳：电影本身已够魔力。", "summary_en": "Ariana Grande shines as the bubbly Glinda opposite Cynthia Erivo's Elphaba in Jon M. Chu's hit musical films, which have pulled in hundreds of millions at the box office. Seyfried auditioned multiple times, even carving out time during The Dropout shoots, but later said Grande was meant for the role and called the movie fantastic. Fans highlight Grande's vocal range, her chemistry with Erivo, and director Chu's praise for her unique audition energy, shutting down the recurring what-if debate. The back-and-forth underscores fans' strong bond with Wicked's tale of friendship and ambition.", "summary_zh": "爱莉安娜·格兰德在朱浩伟执导的音乐电影中饰演活泼的格琳达，与辛西娅·埃里沃的艾尔法巴对手戏，票房累计数亿美元。赛弗里德曾多次试镜，后称角色本就属于格兰德并盛赞影片。粉丝强调其音域、与埃里沃的化学反应以及导演对其试镜能量的肯定，终结反复出现的「假如」争论。", "body_en": "Fans Defend Ariana Grande as Glinda Against Amanda Seyfried Casting Talk.\n\nA post wondering if Amanda Seyfried would have topped Ariana Grande as Glinda in Wicked quickly met pushback from fans who love the film's magic just as it is.\n\nAriana Grande shines as the bubbly Glinda opposite Cynthia Erivo's Elphaba in Jon M. Chu's hit musical films, which have pulled in hundreds of millions at the box office.\n\nSeyfried auditioned multiple times, even carving out time during The Dropout shoots, but later said Grande was meant for the role and called the movie fantastic. Fans highlight Grande's vocal range, her chemistry with Erivo, and director Chu's praise for her unique audition energy, shutting down the recurring what-if debate. The back-and-forth underscores fans' strong bond with Wicked's tale of friendship and ambition.", "body_zh": "粉丝力挺格兰德饰演格琳达，回应赛弗里德「本可更好」论。\n\n有人猜测若由阿曼达·赛弗里德演《魔法坏女巫》格琳达会否更佳，粉丝迅速反驳：电影本身已够魔力。\n\n爱莉安娜·格兰德在朱浩伟执导的音乐电影中饰演活泼的格琳达，与辛西娅·埃里沃的艾尔法巴对手戏，票房累计数亿美元。赛弗里德曾多次试镜，后称角色本就属于格兰德并盛赞影片。\n\n粉丝强调其音域、与埃里沃的化学反应以及导演对其试镜能量的肯定，终结反复出现的「假如」争论。", "url": "https://x.com/i/trending/2112653365356433717", "category": "Entertainment", "topics": ["Movies & TV", "Celebrity"], "updated_at": "2026-10-21T00:31:26.000Z"}, {"id": "2112605676610478278", "domain": "娱乐", "title_en": "Jaafar Jackson Wins Actor Award for Michael Jackson Role in 'Michael'", "title_zh": "贾法尔·杰克逊凭《Michael》迈克尔·杰克逊一角获演员奖", "hook_en": "Jaafar Jackson, nephew of the King of Pop, steps into the spotlight with a Critics Choice honor for his feature debut as Michael Jackson.", "hook_zh": "「流行之王」侄子贾法尔·杰克逊凭长片处女作饰演迈克尔·杰克逊，获评论选择荣誉，站上聚光灯。", "summary_en": "The Critics Choice Association named Jaafar Jackson the Actor Award – Film recipient at the 9th Annual Celebration of Black Cinema & Television for his portrayal in Lionsgate's 'Michael,' the first biopic to top $1 billion worldwide and Lionsgate's biggest release ever. Directed by Antoine Fuqua, the film traces Michael Jackson's rise and drew strong box-office success since opening in April. The ceremony happens November 16, 2026, at Fairmont Century Plaza in Los Angeles, with others like Debbie Allen receiving honors too. Fans celebrated the news, praising his acclaimed performance.", "summary_zh": "评论选择协会将第 9 届黑人电影与电视庆典「电影演员奖」授予贾法尔·杰克逊，表彰其在狮门《Michael》中的演绎——该片为全球票房破 10 亿美元的首部传记片，亦是狮门史上最大发行。安东尼·福奎阿执导，追溯杰克逊崛起，4 月上映后票房强劲。典礼 2026 年 11 月 16 日在洛杉矶 Fairmont Century Plaza 举行，黛比·艾伦等亦获表彰。粉丝庆祝并称赞其获好评的表演。", "body_en": "Jaafar Jackson Wins Actor Award for Michael Jackson Role in 'Michael'.\n\nJaafar Jackson, nephew of the King of Pop, steps into the spotlight with a Critics Choice honor for his feature debut as Michael Jackson.\n\nThe Critics Choice Association named Jaafar Jackson the Actor Award – Film recipient at the 9th Annual Celebration of Black Cinema & Television for his portrayal in Lionsgate's 'Michael,' the first biopic to top $1 billion worldwide and Lionsgate's biggest release ever. Directed by Antoine Fuqua, the film traces Michael Jackson's rise and drew strong box-office success since opening in April.\n\nThe ceremony happens November 16, 2026, at Fairmont Century Plaza in Los Angeles, with others like Debbie Allen receiving honors too. Fans celebrated the news, praising his acclaimed performance.", "body_zh": "贾法尔·杰克逊凭《Michael》迈克尔·杰克逊一角获演员奖。\n\n「流行之王」侄子贾法尔·杰克逊凭长片处女作饰演迈克尔·杰克逊，获评论选择荣誉，站上聚光灯。\n\n评论选择协会将第 9 届黑人电影与电视庆典「电影演员奖」授予贾法尔·杰克逊，表彰其在狮门《Michael》中的演绎——该片为全球票房破 10 亿美元的首部传记片，亦是狮门史上最大发行。安东尼·福奎阿执导，追溯杰克逊崛起，4 月上映后票房强劲。\n\n典礼 2026 年 11 月 16 日在洛杉矶 Fairmont Century Plaza 举行，黛比·艾伦等亦获表彰。粉丝庆祝并称赞其获好评的表演。", "url": "https://x.com/i/trending/2112605676610478278", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-20T18:15:13.000Z"}, {"id": "2112468483736834436", "domain": "娱乐", "title_en": "Tate McRae's 'Housewife' Races for First Solo Hot 100 No. 1", "title_zh": "Tate McRae《Housewife》冲击个人首支 Hot 100 冠军", "hook_en": "Tate McRae owned the Victoria’s Secret Fashion Show stage in a bold red lingerie set, belting 'Housewife' amid dancers and introducing Gigi Hadid—now the track is charging up the charts.", "hook_zh": "Tate McRae 身着大胆红色内衣套装登维多利亚的秘密秀台，边唱《Housewife》边介绍 Gigi Hadid——如今这首歌正狂飙榜单。", "summary_en": "Released October 15, Tate McRae’s 'Housewife' kicked off with huge streams, holding global Apple Music's top spot for three days and racking up 6.5 million Spotify streams on October 19 alone. Her October 18 fashion show performance in Los Angeles, plus a live version dropped October 21 and an iTunes price cut to $0.69, have early forecasts eyeing a No. 1 debut on the Hot 100 dated around October 31—her first solo chart-topper. Olivia Rodrigo’s 'expectations' remix with Chappell Roan, featuring a fun retro game show video with David Byrne, is also surging toward a strong new peak in a tight race with Taylor Swift and others.", "summary_zh": "10 月 15 日发行的《Housewife》开局流媒体强劲，登顶全球苹果音乐三日，10 月 19 日单日 Spotify 流播约 650 万。10 月 18 日洛杉矶维密秀演出、10 月 21 日现场版上线，以及 iTunes 降至 0.69 美元，早期预测看好约 10 月 31 日当周 Hot 100 冠军首秀——将是其首支个人榜首。Olivia Rodrigo 与 Chappell Roan 的《expectations》混音（复古游戏秀风 MV 有 David Byrne）也冲向高位，与泰勒·斯威夫特等人缠斗。", "body_en": "Tate McRae's 'Housewife' Races for First Solo Hot 100 No. 1.\n\nTate McRae owned the Victoria’s Secret Fashion Show stage in a bold red lingerie set, belting 'Housewife' amid dancers and introducing Gigi Hadid—now the track is charging up the charts.\n\nReleased October 15, Tate McRae’s 'Housewife' kicked off with huge streams, holding global Apple Music's top spot for three days and racking up 6.5 million Spotify streams on October 19 alone. Her October 18 fashion show performance in Los Angeles, plus a live version dropped October 21 and an iTunes price cut to $0.69, have early forecasts eyeing a No.\n\n1 debut on the Hot 100 dated around October 31—her first solo chart-topper. Olivia Rodrigo’s 'expectations' remix with Chappell Roan, featuring a fun retro game show video with David Byrne, is also surging toward a strong new peak in a tight race with Taylor Swift and others.", "body_zh": "Tate McRae《Housewife》冲击个人首支 Hot 100 冠军。\n\nTate McRae 身着大胆红色内衣套装登维多利亚的秘密秀台，边唱《Housewife》边介绍 Gigi Hadid——如今这首歌正狂飙榜单。\n\n10 月 15 日发行的《Housewife》开局流媒体强劲，登顶全球苹果音乐三日，10 月 19 日单日 Spotify 流播约 650 万。\n\n10 月 18 日洛杉矶维密秀演出、10 月 21 日现场版上线，以及 iTunes 降至 0.69 美元，早期预测看好约 10 月 31 日当周 Hot 100 冠军首秀——将是其首支个人榜首。Olivia Rodrigo 与 Chappell Roan 的《expectations》混音（复古游戏秀风 MV 有 David Byrne）也冲向高位，与泰勒·斯威夫特等人缠斗。", "url": "https://x.com/i/trending/2112468483736834436", "category": "Entertainment", "topics": ["Music"], "updated_at": "2026-10-21T16:45:22.000Z"}, {"id": "2111675291110088931", "domain": "娱乐", "title_en": "Taylor Swift Shines in Custom Dior at 2026 Academy Museum Gala", "title_zh": "泰勒·斯威夫特着定制迪奥亮相 2026 学院博物馆晚会", "hook_en": "Taylor Swift stepped onto the red carpet in a custom icy-blue Dior gown, its soft pleats and sparkling bow catching every eye under the lights.", "hook_zh": "泰勒·斯威夫特身着定制冰蓝迪奥礼服走上红毯，柔和褶皱与闪亮蝴蝶结在灯光下抢尽目光。", "summary_en": "The 2026 Academy Museum Gala on October 17 in Los Angeles raised over $14 million, honoring Charlize Theron, Colman Domingo, and John Carpenter. Swift performed hits like “Blank Space” and “Love Story” in her first full-band show since the Eras Tour, while Sabrina Carpenter and Rosé wowed in ruffled corsets and fringed gowns. Hannah Waddingham shared a warm selfie with Swift, praising her talent, as British Vogue called her the evening's belle in Chopard diamonds topping 40 carats. The horror-themed décor tied into the museum's new exhibition, blending fashion, music, and tributes into a standout night.", "summary_zh": "10 月 17 日洛杉矶举行的 2026 学院博物馆晚会筹得逾 1400 万美元，致敬 Charlize Theron、Colman Domingo 与 John Carpenter。斯威夫特自 Eras 巡演后首次全乐队演出，演唱《Blank Space》《Love Story》等；Sabrina Carpenter 与 Rosé 以褶皱胸衣、流苏礼服惊艳。Hannah Waddingham 晒出与斯威夫特自拍并盛赞其才华；英国版 Vogue 称她是当晚焦点，萧邦钻石逾 40 克拉。恐怖主题装饰呼应博物馆新展，时尚、音乐与致敬融为一夜高光。", "body_en": "Taylor Swift Shines in Custom Dior at 2026 Academy Museum Gala.\n\nTaylor Swift stepped onto the red carpet in a custom icy-blue Dior gown, its soft pleats and sparkling bow catching every eye under the lights.\n\nThe 2026 Academy Museum Gala on October 17 in Los Angeles raised over $14 million, honoring Charlize Theron, Colman Domingo, and John Carpenter. Swift performed hits like “Blank Space” and “Love Story” in her first full-band show since the Eras Tour, while Sabrina Carpenter and Rosé wowed in ruffled corsets and fringed gowns.\n\nHannah Waddingham shared a warm selfie with Swift, praising her talent, as British Vogue called her the evening's belle in Chopard diamonds topping 40 carats. The horror-themed décor tied into the museum's new exhibition, blending fashion, music, and tributes into a standout night.", "body_zh": "泰勒·斯威夫特着定制迪奥亮相 2026 学院博物馆晚会。\n\n泰勒·斯威夫特身着定制冰蓝迪奥礼服走上红毯，柔和褶皱与闪亮蝴蝶结在灯光下抢尽目光。\n\n10 月 17 日洛杉矶举行的 2026 学院博物馆晚会筹得逾 1400 万美元，致敬 Charlize Theron、Colman Domingo 与 John Carpenter。斯威夫特自 Eras 巡演后首次全乐队演出，演唱《Blank Space》《Love Story》等；Sabrina Carpenter 与 Rosé 以褶皱胸衣、流苏礼服惊艳。\n\nHannah Waddingham 晒出与斯威夫特自拍并盛赞其才华；英国版 Vogue 称她是当晚焦点，萧邦钻石逾 40 克拉。恐怖主题装饰呼应博物馆新展，时尚、音乐与致敬融为一夜高光。", "url": "https://x.com/i/trending/2111675291110088931", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-20T03:07:04.000Z"}, {"id": "2112506238923608157", "domain": "娱乐", "title_en": "Fans Adore Pooh Krittin and Pavel Naret's Grim Reaper Promo Photos", "title_zh": "粉丝热捧 Pooh Krittin 与 Pavel Naret 死神题材宣传照", "hook_en": "Pooh Krittin channels a brooding grim reaper with flowing dark hair and moody blue lighting, while Pavel Naret contrasts in a crisp white shirt—their chemistry already leaping off the screen.", "hook_zh": "Pooh Krittin 以飘逸黑发与冷调蓝光演绎阴郁死神，Pavel Naret 一身利落白衬衫形成反差——搭档化学反应已跃然纸上。", "summary_en": "The promotional images for the upcoming fantasy romance series 'The Grim Lover' showcase Pooh as the grim reaper Sibsi (aka Fourteen or Rafah) and Pavel as grieving anesthesiologist Vivorn Assarak (Won), adapted from a web novel blending boys' love, fantasy, romance, and drama. Fans rave about the 'lethal visuals' and 'insane' pairing chemistry, with one calling Pooh 'the handsomest Reaper' ever. Produced by Change2561, the series airs on One 31 and streams globally on Netflix, with a fan event 'ROAD TO THE GRIM LOVER' set for November 18, 2026, at ICONSIAM Hall in Bangkok—tickets on sale October 30.", "summary_zh": "奇幻爱情剧《The Grim Lover》宣传照中，Pooh 饰死神 Sibsi（又称 Fourteen / Rafah），Pavel 饰丧亲麻醉医生 Vivorn Assarak（Won），改编自融合 BL、奇幻、爱情与剧情的网络小说。粉丝狂赞「杀伤力视觉」与「疯狂」配对，有人直呼 Pooh「史上最帅死神」。Change2561 出品，One 31 播出并全球 Netflix 上线；粉丝活动「ROAD TO THE GRIM LOVER」定于 2026 年 11 月 18 日曼谷 ICONSIAM Hall，门票 10 月 30 日开售。", "body_en": "Fans Adore Pooh Krittin and Pavel Naret's Grim Reaper Promo Photos.\n\nPooh Krittin channels a brooding grim reaper with flowing dark hair and moody blue lighting, while Pavel Naret contrasts in a crisp white shirt—their chemistry already leaping off the screen.\n\nThe promotional images for the upcoming fantasy romance series 'The Grim Lover' showcase Pooh as the grim reaper Sibsi (aka Fourteen or Rafah) and Pavel as grieving anesthesiologist Vivorn Assarak (Won), adapted from a web novel blending boys' love, fantasy, romance, and drama.\n\nFans rave about the 'lethal visuals' and 'insane' pairing chemistry, with one calling Pooh 'the handsomest Reaper' ever. Produced by Change2561, the series airs on One 31 and streams globally on Netflix, with a fan event 'ROAD TO THE GRIM LOVER' set for November 18, 2026, at ICONSIAM Hall in Bangkok—tickets on sale October 30.", "body_zh": "粉丝热捧 Pooh Krittin 与 Pavel Naret 死神题材宣传照。\n\nPooh Krittin 以飘逸黑发与冷调蓝光演绎阴郁死神，Pavel Naret 一身利落白衬衫形成反差——搭档化学反应已跃然纸上。\n\n奇幻爱情剧《The Grim Lover》宣传照中，Pooh 饰死神 Sibsi（又称 Fourteen / Rafah），Pavel 饰丧亲麻醉医生 Vivorn Assarak（Won），改编自融合 BL、奇幻、爱情与剧情的网络小说。\n\n粉丝狂赞「杀伤力视觉」与「疯狂」配对，有人直呼 Pooh「史上最帅死神」。Change2561 出品，One 31 播出并全球 Netflix 上线；粉丝活动「ROAD TO THE GRIM LOVER」定于 2026 年 11 月 18 日曼谷 ICONSIAM Hall，门票 10 月 30 日开售。", "url": "https://x.com/i/trending/2112506238923608157", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-20T11:32:52.000Z"}, {"id": "2112867591127793782", "domain": "娱乐", "title_en": "Fans Celebrate Glen Powell's 38th Birthday with Warm Tributes", "title_zh": "粉丝暖心祝贺 Glen Powell 38 岁生日", "hook_en": "Glen Powell woke up to a flood of birthday love on his 38th, with fans sharing photos from his suited-up red carpets to early Spy Kids days.", "hook_zh": "Glen Powell 38 岁生日醒来收获海量祝福，粉丝从红毯西装照晒到早年《特工小孩》时期。", "summary_en": "Born October 21, 1988, in Austin, Texas, Powell kicked off his career as a teen in Spy Kids 3-D: Game Over and rose to leading roles in Top Gun: Maverick, Anyone But You, Hit Man—which he co-wrote and produced—and Twisters. Entertainment accounts like Pop Base and Film Updates led the cheers, calling him talented and charming, while fans posted appreciative snaps of his versatile looks and declared it International Glen Powell Day. The outpouring highlights his journey from bit parts in The Dark Knight Rises and Hidden Figures to Hollywood's most watchable stars, with more projects ahead.", "summary_zh": "Powell 1988 年 10 月 21 日生于得州奥斯汀，少年出演《特工小孩 3D》起步，后主演《壮志凌云：独行侠》《爱你，不爱你》《Hit Man》（兼编剧制作）与《龙卷风》。Pop Base、Film Updates 等娱乐账号带头叫好，称其才华与魅力；粉丝晒出多变造型照，并宣称「国际 Glen Powell 日」。从《黑暗骑士崛起》《隐藏人物》龙套到好莱坞最吸睛之一的旅程被再度提起，后续项目仍在路上。", "body_en": "Fans Celebrate Glen Powell's 38th Birthday with Warm Tributes.\n\nGlen Powell woke up to a flood of birthday love on his 38th, with fans sharing photos from his suited-up red carpets to early Spy Kids days.\n\nBorn October 21, 1988, in Austin, Texas, Powell kicked off his career as a teen in Spy Kids 3-D: Game Over and rose to leading roles in Top Gun: Maverick, Anyone But You, Hit Man—which he co-wrote and produced—and Twisters.\n\nEntertainment accounts like Pop Base and Film Updates led the cheers, calling him talented and charming, while fans posted appreciative snaps of his versatile looks and declared it International Glen Powell Day. The outpouring highlights his journey from bit parts in The Dark Knight Rises and Hidden Figures to Hollywood's most watchable stars, with more projects ahead.", "body_zh": "粉丝暖心祝贺 Glen Powell 38 岁生日。\n\nGlen Powell 38 岁生日醒来收获海量祝福，粉丝从红毯西装照晒到早年《特工小孩》时期。\n\nPowell 1988 年 10 月 21 日生于得州奥斯汀，少年出演《特工小孩 3D》起步，后主演《壮志凌云：独行侠》《爱你，不爱你》《Hit Man》（兼编剧制作）与《龙卷风》。\n\nPop Base、Film Updates 等娱乐账号带头叫好，称其才华与魅力；粉丝晒出多变造型照，并宣称「国际 Glen Powell 日」。从《黑暗骑士崛起》《隐藏人物》龙套到好莱坞最吸睛之一的旅程被再度提起，后续项目仍在路上。", "url": "https://x.com/i/trending/2112867591127793782", "category": "Entertainment", "topics": ["Celebrity"], "updated_at": "2026-10-21T11:29:11.000Z"}, {"id": "2112958289831231910", "domain": "娱乐", "title_en": "Ted Live-Action Series Hits Blu-ray and DVD November 24", "title_zh": "真人版《Ted》全集蓝光与 DVD 11 月 24 日发售", "hook_en": "Fans of the foul-mouthed teddy bear can now grab the full live-action Ted series on disc, marking the end of John and Ted's high school antics in a working-class Boston home.", "hook_zh": "爱看满嘴脏话泰迪熊的观众终于能买到真人剧全集碟片，标志着 John 与 Ted 在波士顿工薪家庭高中岁月的落幕。", "summary_en": "Universal Pictures is releasing 'Ted: The Complete Series (2024-2026)' on Blu-ray and DVD on November 24, collecting all 15 episodes from the two-season Peacock prequel created by Seth MacFarlane. The set follows teenager John Bennett and his profanity-spewing bear buddy Ted through school, family life with parents Matty and Susan, and cousin Blaire. With no plans for a third season due to high CGI costs, fans are preordering the physical collection, mixing excitement over owning the thunder buddies with bittersweet finality—though some hold out hope like Family Guy's DVD-fueled revival.", "summary_zh": "环球影业将于 11 月 24 日发行《Ted: The Complete Series (2024-2026)》蓝光与 DVD，收录 Seth MacFarlane 打造、Peacock 两季共 15 集前传。故事跟随少年 John Bennett 与脏话连篇的熊伙伴 Ted，写学校生活、父母 Matty 与 Susan、表妹 Blaire。因 CGI 成本高昂暂无第三季计划，粉丝已预购实体套装，既兴奋拥有「雷霆搭档」又感苦乐交加——也有人寄望像《家庭环》那样靠碟片销量复活。", "body_en": "Ted Live-Action Series Hits Blu-ray and DVD November 24.\n\nFans of the foul-mouthed teddy bear can now grab the full live-action Ted series on disc, marking the end of John and Ted's high school antics in a working-class Boston home.\n\nUniversal Pictures is releasing 'Ted: The Complete Series (2024-2026)' on Blu-ray and DVD on November 24, collecting all 15 episodes from the two-season Peacock prequel created by Seth MacFarlane.\n\nThe set follows teenager John Bennett and his profanity-spewing bear buddy Ted through school, family life with parents Matty and Susan, and cousin Blaire. With no plans for a third season due to high CGI costs, fans are preordering the physical collection, mixing excitement over owning the thunder buddies with bittersweet finality—though some hold out hope like Family Guy's DVD-fueled revival.", "body_zh": "真人版《Ted》全集蓝光与 DVD 11 月 24 日发售。\n\n爱看满嘴脏话泰迪熊的观众终于能买到真人剧全集碟片，标志着 John 与 Ted 在波士顿工薪家庭高中岁月的落幕。\n\n环球影业将于 11 月 24 日发行《Ted: The Complete Series (2024-2026)》蓝光与 DVD，收录 Seth MacFarlane 打造、Peacock 两季共 15 集前传。\n\n故事跟随少年 John Bennett 与脏话连篇的熊伙伴 Ted，写学校生活、父母 Matty 与 Susan、表妹 Blaire。因 CGI 成本高昂暂无第三季计划，粉丝已预购实体套装，既兴奋拥有「雷霆搭档」又感苦乐交加——也有人寄望像《家庭环》那样靠碟片销量复活。", "url": "https://x.com/i/trending/2112958289831231910", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T17:31:28.000Z"}, {"id": "2112958289512419416", "domain": "娱乐", "title_en": "The Ringer Ranks All 270 Taylor Swift Songs for Debut Anniversary", "title_zh": "The Ringer 为出道二十周年给泰勒·斯威夫特全部 270 首歌排名", "hook_en": "Two decades after Taylor Swift's first album dropped, The Ringer ranked her entire catalog from 270 to 1, kicking off lively fan debates over picks like 'The Alchemy' at the very bottom.", "hook_zh": "泰勒首专发行二十年后，The Ringer 把其曲库从 270 排到 1，粉丝因《The Alchemy》垫底等选择吵翻天。", "summary_en": "Nora Princiotti put together the list, covering studio albums, vault tracks, soundtracks, and more, while tracing Swift's journey from country roots to pop stardom with critiques along the way. Fans reacted strongly to low spots for 'The Alchemy'—called dreary with weak sports metaphors—'Timeless' at 258, and 'Carolina' at 257, with some dismissing the whole ranking. Midlist entries like the charming 'I Forgot That You Existed' at 130 and surprises such as 'Dear Reader' at 243 fueled more chatter, reminding everyone how personal these hierarchies can be amid Swift's ongoing releases.", "summary_zh": "Nora Princiotti 编列涵盖录音室专辑、保险箱曲、原声等，并梳理其从乡村到流行的路径与点评。粉丝对《The Alchemy》低位（被批沉闷、体育隐喻弱）、《Timeless》第 258、《Carolina》第 257 反应强烈，有人直接否定整份榜。中段如《I Forgot That You Existed》第 130 的可爱、《Dear Reader》第 243 的意外等继续点燃讨论，提醒众人在斯威夫特持续发片之际，这类排名有多主观。", "body_en": "The Ringer Ranks All 270 Taylor Swift Songs for Debut Anniversary.\n\nTwo decades after Taylor Swift's first album dropped, The Ringer ranked her entire catalog from 270 to 1, kicking off lively fan debates over picks like 'The Alchemy' at the very bottom.\n\nNora Princiotti put together the list, covering studio albums, vault tracks, soundtracks, and more, while tracing Swift's journey from country roots to pop stardom with critiques along the way.\n\nFans reacted strongly to low spots for 'The Alchemy'—called dreary with weak sports metaphors—'Timeless' at 258, and 'Carolina' at 257, with some dismissing the whole ranking. Midlist entries like the charming 'I Forgot That You Existed' at 130 and surprises such as 'Dear Reader' at 243 fueled more chatter, reminding everyone how personal these hierarchies can be amid Swift's ongoing releases.", "body_zh": "The Ringer 为出道二十周年给泰勒·斯威夫特全部 270 首歌排名。\n\n泰勒首专发行二十年后，The Ringer 把其曲库从 270 排到 1，粉丝因《The Alchemy》垫底等选择吵翻天。\n\nNora Princiotti 编列涵盖录音室专辑、保险箱曲、原声等，并梳理其从乡村到流行的路径与点评。\n\n粉丝对《The Alchemy》低位（被批沉闷、体育隐喻弱）、《Timeless》第 258、《Carolina》第 257 反应强烈，有人直接否定整份榜。中段如《I Forgot That You Existed》第 130 的可爱、《Dear Reader》第 243 的意外等继续点燃讨论，提醒众人在斯威夫特持续发片之际，这类排名有多主观。", "url": "https://x.com/i/trending/2112958289512419416", "category": "Entertainment", "topics": ["Music"], "updated_at": "2026-10-21T17:31:37.000Z"}, {"id": "2112630069361570032", "domain": "娱乐", "title_en": "Golden Globes Place Michael Jackson Biopic in Drama Categories", "title_zh": "金球奖将迈克尔·杰克逊传记片划入剧情类", "hook_en": "Jaafar Jackson steps into his uncle's shoes in the Michael Jackson biopic, but the Golden Globes just shifted its awards path to a tougher drama field.", "hook_zh": "Jaafar Jackson 出演叔叔迈克尔·杰克逊传记片，金球奖却把其奖项路径改到竞争更激烈的剧情单元。", "summary_en": "Lionsgate hoped to enter 'Michael' in the comedy or musical categories for the 2027 Golden Globes, but organizers ruled it fits drama instead, pitting Jaafar Jackson against stars from Christopher Nolan’s 'The Odyssey' and 'La Bola Negra.' The decision follows tightened rules for music biopics like 'Elvis' and 'Bohemian Rhapsody,' which no longer qualify as musicals unless songs drive the plot. Fans debate the call, with Taj Jackson questioning the logic, while Jaafar's praised performance keeps eyes on his drama actor chances; Lionsgate may appeal by October 31 but likely won't.", "summary_zh": "狮门本希望《Michael》冲刺 2027 金球奖喜剧或音乐类，但主办方裁定属剧情片，使 Jaafar Jackson 将对阵克里斯托弗·诺兰《The Odyssey》与《La Bola Negra》等片明星。裁定呼应了对《Elvis》《波西米亚狂想曲》等音乐传记片收紧的规则：除非歌曲推动情节，否则不再算音乐片。粉丝争论不一，Taj Jackson 质疑逻辑；Jaafar 演技获赞，仍受关注冲击剧情男主角。狮门或于 10 月 31 日前上诉，但成功希望不大。", "body_en": "Golden Globes Place Michael Jackson Biopic in Drama Categories.\n\nJaafar Jackson steps into his uncle's shoes in the Michael Jackson biopic, but the Golden Globes just shifted its awards path to a tougher drama field.\n\nLionsgate hoped to enter 'Michael' in the comedy or musical categories for the 2027 Golden Globes, but organizers ruled it fits drama instead, pitting Jaafar Jackson against stars from Christopher Nolan’s 'The Odyssey' and 'La Bola Negra.' The decision follows tightened rules for music biopics like 'Elvis' and 'Bohemian Rhapsody,' which no longer qualify as musicals unless songs drive the plot. Fans debate the call, with Taj Jackson questioning the logic, while Jaafar's praised performance keeps eyes on his drama actor chances; Lionsgate may appeal by October 31 but likely won't.", "body_zh": "金球奖将迈克尔·杰克逊传记片划入剧情类。\n\nJaafar Jackson 出演叔叔迈克尔·杰克逊传记片，金球奖却把其奖项路径改到竞争更激烈的剧情单元。\n\n狮门本希望《Michael》冲刺 2027 金球奖喜剧或音乐类，但主办方裁定属剧情片，使 Jaafar Jackson 将对阵克里斯托弗·诺兰《The Odyssey》与《La Bola Negra》等片明星。裁定呼应了对《Elvis》《波西米亚狂想曲》等音乐传记片收紧的规则：除非歌曲推动情节，否则不再算音乐片。\n\n粉丝争论不一，Taj Jackson 质疑逻辑；Jaafar 演技获赞，仍受关注冲击剧情男主角。狮门或于 10 月 31 日前上诉，但成功希望不大。", "url": "https://x.com/i/trending/2112630069361570032", "category": "Entertainment", "topics": ["Movies & TV"], "updated_at": "2026-10-21T17:48:00.000Z"}, {"id": "2112552619117891920", "domain": "科学", "title_en": "Review Details Antiparasitic Drugs' Potential Cancer Mechanisms", "title_zh": "综述：伊维菌素与甲苯咪唑联用现 37 种抗癌机制", "hook_en": "Imagine affordable drugs already on pharmacy shelves quietly targeting cancer in lab studies. A new review compiles dozens of ways ivermectin and mebendazole might disrupt tumor growth.", "hook_zh": "详细科学综述梳理逾 100 项实验室与动物研究，归纳两种药物在 25 种人类癌症中协同对抗癌细胞的 37 种方式。", "summary_en": "Researchers, including Nicolas Hulscher of the McCullough Foundation, released a 44-page paper this week outlining 29 anticancer mechanisms for ivermectin across 20 cancer types and 26 for mebendazole across 17 types. These include halting cell division, triggering cell death, blocking tumor blood vessels, and boosting immune responses, with both drugs showing decades of safety data and low costs. Patient stories highlight hope, like a Polish woman with multiple myeloma seeing no disease markers after six months on ivermectin, fenbendazole, and mebendazole, while an observational group of 197 patients reported an 84.4% clinical benefit rate. Proponents call for clinical trials, but experts stress the need for randomized studies to confirm benefits alongside standard care.", "summary_zh": "McCullough 基金会 Nicolas Hulscher、Peter A. McCullough、Harvey Risch 等综合临床前证据，显示药物可干扰癌细胞分裂、诱导死亡、阻断能量与血管生成等。44 页论文强调其成本低、已过专利、人类长期用药安全记录，以及对关键癌症过程有重叠作用。作者呼吁大型临床试验，并提及波兰一病例用药后指标正常化等有限人体报告；专家仍强调需随机试验，且部分研究曾遭撤稿。", "body_en": "Review Identifies 37 Anticancer Mechanisms for Ivermectin and Mebendazole Combo.\n\nA detailed scientific review uncovers 37 ways ivermectin and mebendazole team up against cancer cells across 25 human types, drawing from over 100 lab and animal studies.\n\nResearchers at the McCullough Foundation, including Nicolas Hulscher, Peter A. McCullough, and Harvey Risch, synthesized preclinical evidence showing the drugs disrupt cancer cell division, trigger cell death, block energy and blood vessel growth, and more.\n\nThe 44-page paper notes their low cost, off-patent status, and long safety record in humans, with overlapping effects on key cancer processes. While calling for large clinical trials, it references limited human reports like a Polish woman's normalized markers after using the combo, though experts stress the need for randomized trials amid some study retractions.", "body_zh": "综述：伊维菌素与甲苯咪唑联用现 37 种抗癌机制。\n\n详细科学综述梳理逾 100 项实验室与动物研究，归纳两种药物在 25 种人类癌症中协同对抗癌细胞的 37 种方式。\n\nMcCullough 基金会 Nicolas Hulscher、Peter A. McCullough、Harvey Risch 等综合临床前证据，显示药物可干扰癌细胞分裂、诱导死亡、阻断能量与血管生成等。44 页论文强调其成本低、已过专利、人类长期用药安全记录，以及对关键癌症过程有重叠作用。\n\n作者呼吁大型临床试验，并提及波兰一病例用药后指标正常化等有限人体报告；专家仍强调需随机试验，且部分研究曾遭撤稿。", "url": "https://x.com/i/trending/2112552619117891920", "category": "News", "topics": ["Health & Fitness"], "updated_at": "2026-10-21T17:22:35.000Z"}, {"id": "2112433199888679267", "domain": "科学", "title_en": "AI Predicts Cancer Survival from Face Photos", "title_zh": "AI 凭面部照片预测癌症生存风险", "hook_en": "Doctors have always glanced at a patient's face to sense how sick they might be. Now AI makes that gut feel precise, spotting survival odds from a single snapshot.", "hook_zh": "医生一向会扫一眼患者面容判断病情轻重；如今 AI 把这种直觉量化，单张快照即可估计生存概率。", "summary_en": "Researchers from Mass General Brigham, Dana-Farber, Harvard, and Dutch partners unveiled FAHR-Face, two AI tools trained on millions of images that estimate biological age and forecast mortality risk for cancer patients. In tests with over 34,000 patients, the survival model showed those in the highest-risk group faced three times the death risk of the lowest, even after accounting for clinical factors, with strong results in an independent validation. While promising for low-cost checks using just a phone photo, the tools—mostly trained on white Boston patients—need more diverse testing and aren't ready for clinics yet. Lead researchers see it as a complement to doctor judgment, with the model now public on Hugging Face.", "summary_zh": "麻省总医院布莱根、丹娜法伯、哈佛与荷兰合作方发布 FAHR-Face：两款在海量图像上训练的 AI，可估计生物学年龄并预测癌症患者死亡风险。逾 3.4 万名患者测试显示，最高风险组死亡风险约为最低组三倍，即使校正临床因素后仍成立，独立验证表现稳健。工具有望用手机照片做低成本筛查，但主要在波士顿白人患者上训练，需更多元验证，尚不能进诊所。负责人视其为医生判断的补充，模型已在 Hugging Face 公开。", "body_en": "AI Predicts Cancer Survival from Face Photos.\n\nDoctors have always glanced at a patient's face to sense how sick they might be. Now AI makes that gut feel precise, spotting survival odds from a single snapshot.\n\nResearchers from Mass General Brigham, Dana-Farber, Harvard, and Dutch partners unveiled FAHR-Face, two AI tools trained on millions of images that estimate biological age and forecast mortality risk for cancer patients. In tests with over 34,000 patients, the survival model showed those in the highest-risk group faced three times the death risk of the lowest, even after accounting for clinical factors, with strong results in an independent validation.\n\nWhile promising for low-cost checks using just a phone photo, the tools—mostly trained on white Boston patients—need more diverse testing and aren't ready for clinics yet. Lead researchers see it as a complement to doctor judgment, with the model now public on Hugging Face.", "body_zh": "AI 凭面部照片预测癌症生存风险。\n\n医生一向会扫一眼患者面容判断病情轻重；如今 AI 把这种直觉量化，单张快照即可估计生存概率。\n\n麻省总医院布莱根、丹娜法伯、哈佛与荷兰合作方发布 FAHR-Face：两款在海量图像上训练的 AI，可估计生物学年龄并预测癌症患者死亡风险。逾 3.4 万名患者测试显示，最高风险组死亡风险约为最低组三倍，即使校正临床因素后仍成立，独立验证表现稳健。\n\n工具有望用手机照片做低成本筛查，但主要在波士顿白人患者上训练，需更多元验证，尚不能进诊所。负责人视其为医生判断的补充，模型已在 Hugging Face 公开。", "url": "https://x.com/i/trending/2112433199888679267", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-20T21:07:35.000Z"}, {"id": "2112771430316404992", "domain": "科学", "title_en": "Biosphere 2 Experiment Revives Debates on Self-Sustaining Living", "title_zh": "生物圈 2 号实验再引「自给生存」讨论", "hook_en": "Eight people stepped into a glass dome in the Arizona desert in 1991, aiming to create a sealed world with its own rainforest, ocean, and farm. Two years later, they emerged thinner but alive, sparking lessons that echo today.", "hook_zh": "1991 年八人走进亚利桑那沙漠玻璃穹顶，试图建造含雨林、海洋与农场的密封世界；两年后消瘦但存活走出，启示至今回响。", "summary_en": "The $150 million Biosphere 2 project tested if humans could thrive in a three-acre sealed ecosystem, growing 80 percent of their calories from crops like sweet potatoes and bananas, with goats providing key milk and a few pigs and chickens for scraps. Challenges hit hard: oxygen levels dropped to 14 percent from soil microbes outpacing plants, crew lost 10-20 percent body weight, and animals like pigs were slaughtered early amid calorie shortages. A popular thread recaps these struggles, with some calling it a warning against plant-heavy diets while others note fixes like added oxygen could work for space or Earth setups. The dome near Tucson now serves as a University of Arizona research site for ecology.", "summary_zh": "耗资约 1.5 亿美元的生物圈 2 号检验人类能否在三英亩密封生态中生存：约 80% 热量来自红薯、香蕉等作物，山羊供奶，少量猪鸡处理厨余。挑战严峻：土壤微生物耗氧快于植物，氧气降至 14%，成员减重 10–20%，猪等动物因热量不足提前宰杀。热门讨论有人视之为植物为主饮食的警示，也有人认为补氧等修正可用于太空或地球方案。图森附近穹顶现为亚利桑那大学生态研究站。", "body_en": "Biosphere 2 Experiment Revives Debates on Self-Sustaining Living.\n\nEight people stepped into a glass dome in the Arizona desert in 1991, aiming to create a sealed world with its own rainforest, ocean, and farm. Two years later, they emerged thinner but alive, sparking lessons that echo today.\n\nThe $150 million Biosphere 2 project tested if humans could thrive in a three-acre sealed ecosystem, growing 80 percent of their calories from crops like sweet potatoes and bananas, with goats providing key milk and a few pigs and chickens for scraps. Challenges hit hard: oxygen levels dropped to 14 percent from soil microbes outpacing plants, crew lost 10-20 percent body weight, and animals like pigs were slaughtered early amid calorie shortages.\n\nA popular thread recaps these struggles, with some calling it a warning against plant-heavy diets while others note fixes like added oxygen could work for space or Earth setups. The dome near Tucson now serves as a University of Arizona research site for ecology.", "body_zh": "生物圈 2 号实验再引「自给生存」讨论。\n\n1991 年八人走进亚利桑那沙漠玻璃穹顶，试图建造含雨林、海洋与农场的密封世界；两年后消瘦但存活走出，启示至今回响。\n\n耗资约 1.5 亿美元的生物圈 2 号检验人类能否在三英亩密封生态中生存：约 80% 热量来自红薯、香蕉等作物，山羊供奶，少量猪鸡处理厨余。挑战严峻：土壤微生物耗氧快于植物，氧气降至 14%，成员减重 10–20%，猪等动物因热量不足提前宰杀。\n\n热门讨论有人视之为植物为主饮食的警示，也有人认为补氧等修正可用于太空或地球方案。图森附近穹顶现为亚利桑那大学生态研究站。", "url": "https://x.com/i/trending/2112771430316404992", "category": "News", "topics": ["Science"], "updated_at": "2026-10-21T07:36:09.000Z"}, {"id": "2112244933029761280", "domain": "科学", "title_en": "Dr. Priti Adani Outlines National Expansion of Healthcare Education and Research", "title_zh": "普里蒂·阿达尼勾勒医疗教育与科研全国扩张", "hook_en": "At the Adani Institute's 17th convocation in Wardha, Dr. Priti Adani spoke directly to graduates about blending compassion with cutting-edge care.", "hook_zh": "在瓦尔达第 17 届毕业典礼上，她勉励毕业生把关怀与尖端医疗结合。", "summary_en": "Dr. Priti Adani, Chancellor of the Adani Institute of Higher Education and Research, announced plans to strengthen Wardha and Nagpur campuses with modern medical equipment, advanced research, and super-specialty services over the next two years. The institute aims to build additional campuses across India, tailored to regional needs while upholding consistent standards and the principle of 'Seva hi sadhana hai'—service as devotion. Guided by UN Sustainable Development Goals, efforts will focus on preventive care, disease prevention, affordable treatments, and support for disadvantaged students, with Dr. Adani urging graduates to prioritize patients' dignity and lifelong learning alongside technical skills.", "summary_zh": "阿达尼高等教育与研究院院长普里蒂·阿达尼宣布，未来两年将加强瓦尔达与那格浦尔校区的现代医疗设备、前沿科研与超专科服务，并按地区需求在全国增设校区，坚持“服务即修行”。计划对标联合国可持续发展目标，聚焦预防、可负担治疗与弱势学生支持，她呼吁毕业生在技术之外守护患者尊严与终身学习。", "body_en": "Dr. Priti Adani Outlines National Expansion of Healthcare Education and Research.\n\nAt the Adani Institute's 17th convocation in Wardha, Dr. Priti Adani spoke directly to graduates about blending compassion with cutting-edge care.\n\nDr. Priti Adani, Chancellor of the Adani Institute of Higher Education and Research, announced plans to strengthen Wardha and Nagpur campuses with modern medical equipment, advanced research, and super-specialty services over the next two years.\n\nThe institute aims to build additional campuses across India, tailored to regional needs while upholding consistent standards and the principle of 'Seva hi sadhana hai'—service as devotion. Guided by UN Sustainable Development Goals, efforts will focus on preventive care, disease prevention, affordable treatments, and support for disadvantaged students, with Dr. Adani urging graduates to prioritize patients' dignity and lifelong learning alongside technical skills.", "body_zh": "普里蒂·阿达尼勾勒医疗教育与科研全国扩张。\n\n在瓦尔达第 17 届毕业典礼上，她勉励毕业生把关怀与尖端医疗结合。\n\n阿达尼高等教育与研究院院长普里蒂·阿达尼宣布，未来两年将加强瓦尔达与那格浦尔校区的现代医疗设备、前沿科研与超专科服务，并按地区需求在全国增设校区，坚持“服务即修行”。计划对标联合国可持续发展目标，聚焦预防、可负担治疗与弱势学生支持，她呼吁毕业生在技术之外守护患者尊严与终身学习。", "url": "https://x.com/i/trending/2112244933029761280", "category": "News", "topics": ["Business & Finance"], "updated_at": "2026-10-19T18:19:21.000Z"}, {"id": "2112514540671730138", "domain": "科学", "title_en": "Reuters Reveals Heat Storms Blanketing Earth for 18 Years Straight", "title_zh": "路透调查：热风暴已连续 18 年覆盖全球某处", "hook_en": "Imagine heat waves so massive they cover nearly 85% of the planet for over a year—Reuters' investigation uncovers this new reality reshaping daily life worldwide.", "hook_zh": "路透调查呈现新现实：热浪规模大到可覆盖近 85% 地球表面并持续逾一年，正重塑全球日常生活。", "summary_en": "Reuters analyzed over 600 billion temperature readings since 1960 and found heat storms—vast heat waves spanning at least 1% of Earth's surface—now strike 102 times a year on average, up from five in the 1960s. Since July 6, 2008, at least one has raged somewhere every single day, an unbroken 18-year cascade. People share struggles with the relentless heat, which kills nearly half a million annually and damages ecosystems, while the outlet launched a live tracker to monitor these events like hurricanes. Meteorologist Ryan Maue questions the framing, noting a shift in average temperatures explains much of the rise, but Reuters argues naming them helps the public grasp the scale.", "summary_zh": "路透分析自 1960 年以来逾 6000 亿条气温读数，发现「热风暴」——覆盖地球表面至少 1% 的巨大热浪——如今年均约 102 次，1960 年代仅约 5 次。自 2008 年 7 月 6 日起，全球每天至少有一处在经历热风暴，连续 18 年未断。人们分享酷热下的困境；此类事件每年致死近 50 万并损害生态。路透上线类似飓风的实时追踪器。气象学家 Ryan Maue 质疑表述，认为平均气温抬升可解释大部分增加；路透则称命名有助于公众理解规模。", "body_en": "Reuters Reveals Heat Storms Blanketing Earth for 18 Years Straight.\n\nImagine heat waves so massive they cover nearly 85% of the planet for over a year—Reuters' investigation uncovers this new reality reshaping daily life worldwide.\n\nReuters analyzed over 600 billion temperature readings since 1960 and found heat storms—vast heat waves spanning at least 1% of Earth's surface—now strike 102 times a year on average, up from five in the 1960s. Since July 6, 2008, at least one has raged somewhere every single day, an unbroken 18-year cascade.\n\nPeople share struggles with the relentless heat, which kills nearly half a million annually and damages ecosystems, while the outlet launched a live tracker to monitor these events like hurricanes. Meteorologist Ryan Maue questions the framing, noting a shift in average temperatures explains much of the rise, but Reuters argues naming them helps the public grasp the scale.", "body_zh": "路透调查：热风暴已连续 18 年覆盖全球某处。\n\n路透调查呈现新现实：热浪规模大到可覆盖近 85% 地球表面并持续逾一年，正重塑全球日常生活。\n\n路透分析自 1960 年以来逾 6000 亿条气温读数，发现「热风暴」——覆盖地球表面至少 1% 的巨大热浪——如今年均约 102 次，1960 年代仅约 5 次。自 2008 年 7 月 6 日起，全球每天至少有一处在经历热风暴，连续 18 年未断。\n\n人们分享酷热下的困境；此类事件每年致死近 50 万并损害生态。路透上线类似飓风的实时追踪器。气象学家 Ryan Maue 质疑表述，认为平均气温抬升可解释大部分增加；路透则称命名有助于公众理解规模。", "url": "https://x.com/i/trending/2112514540671730138", "category": "News", "topics": ["Science"], "updated_at": "2026-10-20T17:06:35.000Z"}, {"id": "2112620323275485557", "domain": "科学", "title_en": "SophontAI Launches Holon-S1 to Predict Tumor Biology from Routine Slides", "title_zh": "SophontAI 发布 Holon-S1：从常规病理切片预测肿瘤生物学", "hook_en": "Cancer patients often share the same diagnosis but have wildly different tumor behaviors. SophontAI's new Holon-S1 changes that by unlocking molecular insights straight from everyday pathology slides.", "hook_zh": "同样诊断的癌症患者肿瘤行为可能迥异；Holon-S1 从日常病理片直接读出分子线索。", "summary_en": "Holon-S1 predicts genes, biomarkers, and biological pathways directly from standard H&E slides that most patients already get, skipping slow and costly molecular tests. In tests, it beat leading models across 16 organ types, spotted novel breast and colon cancer biomarkers, and even analyzed a rare osteosarcoma case—matching a patient's real treatment findings on fibroblast genes like FAP. Co-founder Paul Scotti and CEO Tanishq Mathew Abraham stressed its interpretable biology, with shoutouts from Google's Jeff Dean and investor José Maria Macedo highlighting its promise for broader access to personalized tumor insights.", "summary_zh": "Holon-S1 可从多数患者已有的标准 H&E 切片预测基因、生物标志物与通路，跳过缓慢昂贵的分子检测。测试中其在 16 种器官上优于领先模型，发现乳腺与结肠癌新标志物，并分析罕见骨肉瘤病例——在 FAP 等成纤维基因上与患者真实治疗发现吻合。联合创始人与 CEO 强调可解释生物学；谷歌 Jeff Dean 与投资人等点赞其扩大个性化肿瘤洞察可及性。", "body_en": "SophontAI Launches Holon-S1 to Predict Tumor Biology from Routine Slides.\n\nCancer patients often share the same diagnosis but have wildly different tumor behaviors. SophontAI's new Holon-S1 changes that by unlocking molecular insights straight from everyday pathology slides.\n\nHolon-S1 predicts genes, biomarkers, and biological pathways directly from standard H&E slides that most patients already get, skipping slow and costly molecular tests.\n\nIn tests, it beat leading models across 16 organ types, spotted novel breast and colon cancer biomarkers, and even analyzed a rare osteosarcoma case—matching a patient's real treatment findings on fibroblast genes like FAP. Co-founder Paul Scotti and CEO Tanishq Mathew Abraham stressed its interpretable biology, with shoutouts from Google's Jeff Dean and investor José Maria Macedo highlighting its promise for broader access to personalized tumor insights.", "body_zh": "SophontAI 发布 Holon-S1：从常规病理切片预测肿瘤生物学。\n\n同样诊断的癌症患者肿瘤行为可能迥异；Holon-S1 从日常病理片直接读出分子线索。\n\nHolon-S1 可从多数患者已有的标准 H&E 切片预测基因、生物标志物与通路，跳过缓慢昂贵的分子检测。测试中其在 16 种器官上优于领先模型，发现乳腺与结肠癌新标志物，并分析罕见骨肉瘤病例——在 FAP 等成纤维基因上与患者真实治疗发现吻合。\n\n联合创始人与 CEO 强调可解释生物学；谷歌 Jeff Dean 与投资人等点赞其扩大个性化肿瘤洞察可及性。", "url": "https://x.com/i/trending/2112620323275485557", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T01:29:19.000Z"}, {"id": "2112623559876952326", "domain": "科学", "title_en": "Reflect Orbital Simulates Orbital Sunlight in California Desert Test", "title_zh": "Reflect Orbital 在加州模拟轨道阳光", "hook_en": "In a dark desert near Mount Whitney, powerful spotlights turned night into a moonlit glow, mimicking future satellites beaming sunlight to Earth.", "hook_zh": "惠特尼山附近暗夜沙漠中，强光把夜色照成月色，预演未来阳光卫星。", "summary_en": "On October 10, California startup Reflect Orbital tested ground-based lights along Horseshoe Meadows Road near Lone Pine, illuminating three miles of terrain to aid nighttime search-and-rescue exercises with China Lake Mountain Rescue teams. The demo previews a satellite constellation with reflective mirrors to deliver targeted sunlight for emergencies or solar farms. While supporters highlight rescue benefits, astronomers worry about light pollution harming stargazing and wildlife, and skeptics question economics and environmental impacts as the company plans launches with India's Skyroot Aerospace.", "summary_zh": "10 月 10 日，加州初创公司 Reflect Orbital 在孤松镇附近 Horseshoe Meadows Road 沿线用地面灯具试验，照亮约三英里地形，协助 China Lake 山地救援队开展夜间搜救演练。演示预示将以反射镜卫星星座向应急场景或太阳能电站投送定向阳光。支持者强调救援价值，天文学家担忧光污染影响观星与野生动物，亦有人质疑经济性与环境影响；公司计划与印度 Skyroot Aerospace 合作发射。", "body_en": "Reflect Orbital Simulates Orbital Sunlight in California Desert Test.\n\nIn a dark desert near Mount Whitney, powerful spotlights turned night into a moonlit glow, mimicking future satellites beaming sunlight to Earth.\n\nOn October 10, California startup Reflect Orbital tested ground-based lights along Horseshoe Meadows Road near Lone Pine, illuminating three miles of terrain to aid nighttime search-and-rescue exercises with China Lake Mountain Rescue teams.\n\nThe demo previews a satellite constellation with reflective mirrors to deliver targeted sunlight for emergencies or solar farms. While supporters highlight rescue benefits, astronomers worry about light pollution harming stargazing and wildlife, and skeptics question economics and environmental impacts as the company plans launches with India's Skyroot Aerospace.", "body_zh": "Reflect Orbital 在加州模拟轨道阳光。\n\n惠特尼山附近暗夜沙漠中，强光把夜色照成月色，预演未来阳光卫星。\n\n10 月 10 日，加州初创公司 Reflect Orbital 在孤松镇附近 Horseshoe Meadows Road 沿线用地面灯具试验，照亮约三英里地形，协助 China Lake 山地救援队开展夜间搜救演练。\n\n演示预示将以反射镜卫星星座向应急场景或太阳能电站投送定向阳光。支持者强调救援价值，天文学家担忧光污染影响观星与野生动物，亦有人质疑经济性与环境影响；公司计划与印度 Skyroot Aerospace 合作发射。", "url": "https://x.com/i/trending/2112623559876952326", "category": "News", "topics": ["Technology", "Space"], "updated_at": "2026-10-21T00:18:52.000Z"}, {"id": "2112820742060495085", "domain": "科学", "title_en": "Rizhao Residents Watch Rocket Launch from Home Windows", "title_zh": "日照市民在家门口「看火箭」升空", "hook_en": "People in Rizhao, China, peered out their bedroom windows to see a rocket soar into the sky over the Yellow Sea. It was a stunning, everyday view of space history unfolding right outside.", "hook_zh": "中国日照居民透过卧室窗户，便能看见火箭从黄海上空腾起——航天发射成了海边日常景观。", "summary_en": "On October 21, 2026, Galactic Energy’s Ceres-1S Y8 rocket lifted off at 11:39 a.m. Beijing Time from an offshore platform near Rizhao in Shandong Province, successfully placing the XiGuang-4-01 Earth-observation satellite into a 541-kilometer orbit. The satellite features high-resolution cameras and sensors to support monitoring in areas like the Guangdong-Hong Kong-Macao Greater Bay Area and along the Maritime Silk Road. This seventh sea-based mission for the Ceres-1 series used a new shore-based command center, giving coastal residents a clear, front-row view of the liftoff from their homes.", "summary_zh": "2026 年 10 月 21 日北京时间 11:39，银河动力（Galactic Energy）的朱雀一号（Ceres-1S）Y8 运载火箭在山东日照附近海上平台升空，成功将「羲光四号 01」对地观测卫星送入约 541 公里轨道。卫星搭载高分相机与传感器，服务粤港澳大湾区及海上丝绸之路等监测需求。这是朱雀一号系列第七次海上发射，并启用新的岸基指挥中心，让沿海居民能在家清晰目睹发射。", "body_en": "Rizhao Residents Watch Rocket Launch from Home Windows.\n\nPeople in Rizhao, China, peered out their bedroom windows to see a rocket soar into the sky over the Yellow Sea. It was a stunning, everyday view of space history unfolding right outside.\n\nOn October 21, 2026, Galactic Energy’s Ceres-1S Y8 rocket lifted off at 11:39 a.m. Beijing Time from an offshore platform near Rizhao in Shandong Province, successfully placing the XiGuang-4-01 Earth-observation satellite into a 541-kilometer orbit.\n\nThe satellite features high-resolution cameras and sensors to support monitoring in areas like the Guangdong-Hong Kong-Macao Greater Bay Area and along the Maritime Silk Road. This seventh sea-based mission for the Ceres-1 series used a new shore-based command center, giving coastal residents a clear, front-row view of the liftoff from their homes.", "body_zh": "日照市民在家门口「看火箭」升空。\n\n中国日照居民透过卧室窗户，便能看见火箭从黄海上空腾起——航天发射成了海边日常景观。\n\n2026 年 10 月 21 日北京时间 11:39，银河动力（Galactic Energy）的朱雀一号（Ceres-1S）Y8 运载火箭在山东日照附近海上平台升空，成功将「羲光四号 01」对地观测卫星送入约 541 公里轨道。\n\n卫星搭载高分相机与传感器，服务粤港澳大湾区及海上丝绸之路等监测需求。这是朱雀一号系列第七次海上发射，并启用新的岸基指挥中心，让沿海居民能在家清晰目睹发射。", "url": "https://x.com/i/trending/2112820742060495085", "category": "News", "topics": ["Space"], "updated_at": "2026-10-21T08:24:00.000Z"}, {"id": "2111892089000915435", "domain": "科学", "title_en": "President Ruto Launches Key Projects in Kapsabet Amid Huge Crowds", "title_zh": "鲁托总统在卡普萨贝特启动多项民生工程，万人夹道", "hook_en": "Thousands of residents in yellow caps lined Kapsabet's streets on October 18, cheering as President William Ruto arrived to unveil projects boosting healthcare, roads, and more.", "hook_zh": "10 月 18 日数千戴黄帽居民列队卡普萨贝特街头，欢呼威廉·鲁托总统到访揭幕医疗、道路等项目。", "summary_en": "Ruto opened the new Mother and Child Health Complex at Kapsabet County Referral Hospital, equipped with KSh392 million in modern tools and new intensive care units. He inspected the half-complete 10,000-seater stadium, laid a foundation for another hospital, commissioned the county headquarters, and committed to 12 km of local roads plus a four-lane highway upgrade. The visits also included flagging off a Sh351 million electricity project for thousands of homes and issuing Women Enterprise Fund cheques, with Governor Stephen Sang noting direct benefits to daily lives.", "summary_zh": "鲁托为卡普萨贝特县转诊医院新建母婴健康综合楼剪彩，配备价值约 3.92 亿肯先令的现代设备与新重症监护室。他视察半完工的万人体育场、为另一医院奠基、启用县总部，并承诺 12 公里地方道路与四车道公路升级。行程还包括启动约 3.51 亿肯先令电力项目惠及数千户，以及发放妇女企业基金支票；州长 Stephen Sang 称举措直接惠及日常生活。", "body_en": "President Ruto Launches Key Projects in Kapsabet Amid Huge Crowds.\n\nThousands of residents in yellow caps lined Kapsabet's streets on October 18, cheering as President William Ruto arrived to unveil projects boosting healthcare, roads, and more.\n\nRuto opened the new Mother and Child Health Complex at Kapsabet County Referral Hospital, equipped with KSh392 million in modern tools and new intensive care units.\n\nHe inspected the half-complete 10,000-seater stadium, laid a foundation for another hospital, commissioned the county headquarters, and committed to 12 km of local roads plus a four-lane highway upgrade. The visits also included flagging off a Sh351 million electricity project for thousands of homes and issuing Women Enterprise Fund cheques, with Governor Stephen Sang noting direct benefits to daily lives.", "body_zh": "鲁托总统在卡普萨贝特启动多项民生工程，万人夹道。\n\n10 月 18 日数千戴黄帽居民列队卡普萨贝特街头，欢呼威廉·鲁托总统到访揭幕医疗、道路等项目。\n\n鲁托为卡普萨贝特县转诊医院新建母婴健康综合楼剪彩，配备价值约 3.92 亿肯先令的现代设备与新重症监护室。他视察半完工的万人体育场、为另一医院奠基、启用县总部，并承诺 12 公里地方道路与四车道公路升级。\n\n行程还包括启动约 3.51 亿肯先令电力项目惠及数千户，以及发放妇女企业基金支票；州长 Stephen Sang 称举措直接惠及日常生活。", "url": "https://x.com/i/trending/2111892089000915435", "category": "News", "topics": ["Health & Fitness"], "updated_at": "2026-10-20T06:36:12.000Z"}, {"id": "2112650189492072480", "domain": "科学", "title_en": "Blockchain Projects Form Quantum Alliance and Launch Unified Compute Platform", "title_zh": "区块链项目组建量子联盟并推出统一算力平台", "hook_en": "Blockchain teams are teaming up to shield networks from quantum threats while making quantum hardware easier for developers to use.", "hook_zh": "区块链团队联手抵御量子威胁，同时让开发者更易使用量子硬件。", "summary_en": "American Fortress joined eight other organizations to launch the Quantum Alliance, which sets open standards for post-quantum security in blockchains, wallets, and cross-chain systems. Meanwhile, Quip Network released its Quip Virtual Machine on the Aglais testnet around October 20, 2026, letting developers write one program that runs on quantum annealers like D-Wave, future gate-based systems like IonQ, and classical CPUs or GPUs. The platform verifies results on-chain and offers upfront cost quotes, with early demos showing quantum edges in portfolio optimization. Community members highlight the need for full security upgrades, transparent benchmarks, and real-world testing as these tools advance.", "summary_zh": "American Fortress 联合另外八家机构发起 Quantum Alliance，为区块链、钱包与跨链系统制定后量子安全开放标准。与此同时，Quip Network 约于 2026 年 10 月 20 日在 Aglais 测试网发布 Quip 虚拟机，开发者可写一套程序，运行于 D-Wave 等量子退火机、未来 IonQ 等门电路系统，以及经典 CPU/GPU。平台链上校验结果并提供预估报价，早期演示显示投资组合优化等场景有量子优势。社区强调需全面安全升级、透明基准与真实场景验证。", "body_en": "Blockchain Projects Form Quantum Alliance and Launch Unified Compute Platform.\n\nBlockchain teams are teaming up to shield networks from quantum threats while making quantum hardware easier for developers to use.\n\nAmerican Fortress joined eight other organizations to launch the Quantum Alliance, which sets open standards for post-quantum security in blockchains, wallets, and cross-chain systems. Meanwhile, Quip Network released its Quip Virtual Machine on the Aglais testnet around October 20, 2026, letting developers write one program that runs on quantum annealers like D-Wave, future gate-based systems like IonQ, and classical CPUs or GPUs.\n\nThe platform verifies results on-chain and offers upfront cost quotes, with early demos showing quantum edges in portfolio optimization. Community members highlight the need for full security upgrades, transparent benchmarks, and real-world testing as these tools advance.", "body_zh": "区块链项目组建量子联盟并推出统一算力平台。\n\n区块链团队联手抵御量子威胁，同时让开发者更易使用量子硬件。\n\nAmerican Fortress 联合另外八家机构发起 Quantum Alliance，为区块链、钱包与跨链系统制定后量子安全开放标准。与此同时，Quip Network 约于 2026 年 10 月 20 日在 Aglais 测试网发布 Quip 虚拟机，开发者可写一套程序，运行于 D-Wave 等量子退火机、未来 IonQ 等门电路系统，以及经典 CPU/GPU。\n\n平台链上校验结果并提供预估报价，早期演示显示投资组合优化等场景有量子优势。社区强调需全面安全升级、透明基准与真实场景验证。", "url": "https://x.com/i/trending/2112650189492072480", "category": "News", "topics": ["Technology", "Cryptocurrency"], "updated_at": "2026-10-21T17:33:03.000Z"}, {"id": "2112905930044317939", "domain": "科学", "title_en": "NVIDIA and University of Washington Release RFD4-Proteina for Protein Design", "title_zh": "英伟达与华盛顿大学发布 RFD4-Proteina，加速蛋白质设计", "hook_en": "Imagine designing proteins—from enzymes to antibodies—in one seamless step, 13 times faster than before. That's the breakthrough from NVIDIA and the University of Washington's Baker Lab.", "hook_zh": "英伟达与华盛顿大学科学家推出新的 AI 工具，可更快、更好地设计蛋白质，已被寄望加速药物发现。", "summary_en": "RFD4-Proteina, a new open AI model, reasons across amino acids, sugars, DNA, and RNA to co-design a protein's sequence and 3D structure together. Born from a year-long collaboration with Nobel laureate David Baker's team, it excels on benchmarks, speeds up generation for 200-residue proteins, and has produced real-world successes like an enzyme for the HIV drug lenacapavir. Available now on GitHub, Hugging Face, and as an NVIDIA service, it's already drawing excitement from scientists for accelerating drug discovery and enzyme engineering.", "summary_zh": "RFD4-Proteina 由英伟达 GenAIR 团队与华盛顿大学蛋白质设计研究所 Baker 实验室合作一年而成，在共享潜空间中协同设计蛋白质序列与结构。它可处理结合物设计、酶支架、基序条件化，以及 DNA、RNA 或小分子相关任务，在速度、质量与湿实验成功率上优于此前模型。该工具在柏林 GTC 以开源形式登陆 GitHub 与 Hugging Face，并作为英伟达 NIM 微服务提供，还与 Tamarind Bio 等伙伴集成以便使用。研究人员称结果「令人惊叹」，是生物学与医学的前沿跃升。", "body_en": "NVIDIA and UW Unveil RFD4-Proteina for Faster Protein Design.\n\nScientists at NVIDIA and the University of Washington just dropped a powerful new AI tool that designs proteins quicker and better than before. It's already drawing cheers for speeding up drug discovery.\n\nRFD4-Proteina, born from a year-long collaboration between NVIDIA's GenAIR team and the Baker Lab at UW's Institute for Protein Design, co-designs protein sequences and structures in a shared latent space. It handles binder design, enzyme scaffolding, motif conditioning, and work with DNA, RNA, or small molecules, outperforming prior models in speed, quality, and wet-lab success rates.\n\nReleased open source on GitHub and Hugging Face at GTC Berlin, it's available as an NVIDIA NIM microservice and integrated with partners like Tamarind Bio for easy use. Researchers called the results 'astonishing' and a state-of-the-art leap for biology and medicine.", "body_zh": "英伟达与华盛顿大学发布 RFD4-Proteina，加速蛋白质设计。\n\n英伟达与华盛顿大学科学家推出新的 AI 工具，可更快、更好地设计蛋白质，已被寄望加速药物发现。\n\nRFD4-Proteina 由英伟达 GenAIR 团队与华盛顿大学蛋白质设计研究所 Baker 实验室合作一年而成，在共享潜空间中协同设计蛋白质序列与结构。它可处理结合物设计、酶支架、基序条件化，以及 DNA、RNA 或小分子相关任务，在速度、质量与湿实验成功率上优于此前模型。\n\n该工具在柏林 GTC 以开源形式登陆 GitHub 与 Hugging Face，并作为英伟达 NIM 微服务提供，还与 Tamarind Bio 等伙伴集成以便使用。研究人员称结果「令人惊叹」，是生物学与医学的前沿跃升。", "url": "https://x.com/i/trending/2112905930044317939", "category": "News", "topics": ["Technology", "Biotech"], "updated_at": "2026-10-21T16:58:22.000Z"}, {"id": "2112802744491000212", "domain": "科学", "title_en": "UN Report: 1.5°C Target Now Requires Overshoot Before Return", "title_zh": "联合国报告：暂时超越 1.5°C 已不可避免，但仍可逆转", "hook_en": "The world has missed the chance to hold global warming below 1.5°C without going over the line first, a new UN report warns. But swift action could still keep the exceedance short and pull temperatures back by 2100.", "hook_zh": "联合国传来沉重消息：数十年气候行动迟缓意味着将暂时突破 1.5°C 升温上限；但领导层称紧急行动仍可在本世纪末把温度拉回。", "summary_en": "The UN Environment Programme's Emissions Gap Report states that current policies point to up to 2.8°C of warming by century's end, while national pledges would limit it to 2.6°C. To minimize overshoot to 1.7-1.8°C mid-century with a fair shot at returning to 1.5°C by 2100, emissions must drop 18% by 2030, 45% by 2035, and 69% by 2040 from 2025 levels. Key steps include tripling renewable electricity, slashing coal power by 75%, and cutting methane by 25%, as UN leaders like António Guterres urge pulling back from the brink ahead of COP31.", "summary_zh": "联合国环境规划署《2026 排放差距报告》警告，现行政策指向升温约 2.8°C，国家承诺可压至约 2.6°C。即便乐观路径，本世纪中叶仍见 1.7–1.8°C，之后才可能于 2100 年回到 1.5°C，需相对 2025 年水平在 2030 年减排 18%、2035 年 45%、2040 年 69%，并大规模碳移除。UNEP 负责人 Inger Andersen 与古特雷斯强调，要将「超标」幅度压到最小，必须立即全力以赴，在煤油气排放仍升之际依托可再生扩张。", "body_en": "UN Report: 1.5°C Limit Overshoot Now Inevitable.\n\nYears of slow action have closed the door on staying below 1.5°C warming without a temporary breach. The focus shifts to limiting how high and how long temperatures climb before dropping back.\n\nThe UN Environment Programme’s 2026 Emissions Gap Report states that global warming will exceed the Paris Agreement’s 1.5°C target in coming years, with the best-case peak at 1.7–1.8°C mid-century and a 50% chance of returning below 1.5°C by 2100. This requires emissions cuts of 18% by 2030, 45% by 2035, and 69% by 2040 from 2025 levels, plus large-scale carbon removal.\n\nCurrent pledges only achieve 5–8% cuts by 2030, heading toward 2.6°C or more warming. UNEP’s Inger Andersen calls for urgent action to minimize risks like floods and heatwaves ahead of COP31 talks.", "body_zh": "联合国报告：暂时超越 1.5°C 已不可避免，但仍可逆转。\n\n联合国传来沉重消息：数十年气候行动迟缓意味着将暂时突破 1.5°C 升温上限；但领导层称紧急行动仍可在本世纪末把温度拉回。\n\n联合国环境规划署《2026 排放差距报告》警告，现行政策指向升温约 2.8°C，国家承诺可压至约 2.6°C。即便乐观路径，本世纪中叶仍见 1.7–1.8°C，之后才可能于 2100 年回到 1.5°C，需相对 2025 年水平在 2030 年减排 18%、2035 年 45%、2040 年 69%，并大规模碳移除。\n\nUNEP 负责人 Inger Andersen 与古特雷斯强调，要将「超标」幅度压到最小，必须立即全力以赴，在煤油气排放仍升之际依托可再生扩张。", "url": "https://x.com/i/trending/2112802744491000212", "category": "News", "topics": ["News"], "updated_at": "2026-10-21T16:57:31.000Z"}, {"id": "2112365272892133749", "domain": "科学", "title_en": "MiniMax Launches M3.1 Flash, Unveils Stealth Space Bunny Model", "title_zh": "MiniMax 发布 M3.1 Flash，揭开隐身「Space Bunny」身份", "hook_en": "Developers lit up when MiniMax revealed its leaderboard-topping Space Bunny was actually an early M3.1 Flash – now live and slashing AI costs dramatically.", "hook_zh": "开发者沸腾：MiniMax 证实登顶榜单的「Space Bunny」实为早期 M3.1 Flash——现已上线并大幅压低 AI 成本。", "summary_en": "MiniMax released M3.1 Flash, confirming the anonymous Space Bunny that dominated charts with over 200 trillion tokens as its precursor. It excels in coding, agent workflows, and complex tasks, with benchmarks like 73.7% on DeepSWE for software engineering and nearly 3x faster inference than its prior version. Testers report building hardware pages for $0.014 versus $1.22 on rivals, running four times faster, while API pricing stays at $0.15 per million input tokens. Available now on Ollama for free trials and tools like Cline, it draws praise for affordability in design and automation, though some note gaps in pure coding metrics.", "summary_zh": "MiniMax 发布 M3.1 Flash，确认累计逾 200 万亿 tokens、长期霸榜的匿名 Space Bunny 即其前身。模型擅长编程、智能体工作流与复杂任务，DeepSWE 软件工程基准约 73.7%，推理速度较前代近 3 倍。测试者称搭建硬件页面成本约 0.014 美元对竞品约 1.22 美元，速度约快四倍；API 输入价仍为每百万 tokens 0.15 美元。现已上 Ollama 免费试用及 Cline 等工具，设计与自动化场景因性价比受赞，纯编程指标仍有差距。", "body_en": "MiniMax Launches M3.1 Flash, Unveils Stealth Space Bunny Model.\n\nDevelopers lit up when MiniMax revealed its leaderboard-topping Space Bunny was actually an early M3.1 Flash – now live and slashing AI costs dramatically.\n\nMiniMax released M3.1 Flash, confirming the anonymous Space Bunny that dominated charts with over 200 trillion tokens as its precursor. It excels in coding, agent workflows, and complex tasks, with benchmarks like 73.7% on DeepSWE for software engineering and nearly 3x faster inference than its prior version.\n\nTesters report building hardware pages for $0.014 versus $1.22 on rivals, running four times faster, while API pricing stays at $0.15 per million input tokens. Available now on Ollama for free trials and tools like Cline, it draws praise for affordability in design and automation, though some note gaps in pure coding metrics.", "body_zh": "MiniMax 发布 M3.1 Flash，揭开隐身「Space Bunny」身份。\n\n开发者沸腾：MiniMax 证实登顶榜单的「Space Bunny」实为早期 M3.1 Flash——现已上线并大幅压低 AI 成本。\n\nMiniMax 发布 M3.1 Flash，确认累计逾 200 万亿 tokens、长期霸榜的匿名 Space Bunny 即其前身。模型擅长编程、智能体工作流与复杂任务，DeepSWE 软件工程基准约 73.7%，推理速度较前代近 3 倍。\n\n测试者称搭建硬件页面成本约 0.014 美元对竞品约 1.22 美元，速度约快四倍；API 输入价仍为每百万 tokens 0.15 美元。现已上 Ollama 免费试用及 Cline 等工具，设计与自动化场景因性价比受赞，纯编程指标仍有差距。", "url": "https://x.com/i/trending/2112365272892133749", "category": "News", "topics": ["Technology", "AI"], "updated_at": "2026-10-21T11:36:47.000Z"}]};
